INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('d79838b1-fd1b-5bbf-aeb3-efcc470b70db', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 9, 9, 'ፈርዖንም ሹሞቹን፥ “የእግዚአብሔር መንፈስ አድሮበታልና እንደዚህ ሰው ያለ ብልህና ዐዋቂ ሰው አናገኝም” አላቸው።'),
  ('6e964b88-b736-536d-af52-98ad179d82c7', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 10, 10, 'በመንግሥቱም ሁለተኛ ሰው አድርጎ ሾመው፤ የግብፅንም ሀገር ሁሉ አስገዛው፤ በፈርዖንም ሁለተኛ ሰረገላ ላይ አስቀመጠው፤ የነጭ ሐር ቀሚስም አለበሰው፤ በአንገቱም ዝርግፍ ወርቅ አሰረለት።'),
  ('fa39bc16-446d-545c-a633-944dc7a347e5', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 11, 11, '“ኤል ኤል አብሪር” ብሎ በፊቱ ዐዋጅ ነገረለት፤ በእጁም የወርቅ ቀለበት አደረገለት፤ በቤቱ ሁሉ ላይ አሠለጠነው፤ ከፍ ከፍም አደረገው። እንዲህም አለው፥ “ከዙፋኔ ብቻ በቀር ከአንተ አልበልጥም።”'),
  ('7a41a51e-4bec-55b4-a143-b73b369a31bc', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 12, 12, 'ዮሴፍም በግብፅ ሀገር ሁሉ ሠለጠነ፤ የፈርዖንም መኳንንት ሁሉ ሹሞቹም ሁሉ፥ የንጉሡንም ሥራ የሚሠሩ ሁሉ ወደዱት፤ በቅንነት ይሔዳልና፥ ትዕቢትም የለውምና፥ ኵራት፥ ፊት አይቶም ማድላት የለውምና፥ መማለጃንም መቀበል የለውም ነበርና። በግብፅ ላሉ አሕዛብ ሁሉ በሚገባ ይፈርድላቸው ነበርና።'),
  ('3d264ce6-ed00-5344-ac0a-78fd3de5808a', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 13, 13, 'የግብፅም ሀገር በዮሴፍ ምክንያት በፈርዖን ፊት ሰላም ሆነች። እግዚአብሔር ከእርሱ ጋር አለና። በፈርዖን ዘመዶች ሁሉ፥ በሚያውቁት ሰዎችም ሁሉ ፊት፥ ለእርሱም ምስክርነትን በሚሰጡ ሰዎች ፊት ባለምዋልነትንና ምሕረትን ሰጠው። የፈርዖንም መንግሥት ቀናች። ባለጋራ አልነበረም። ክፉም አልነበረም።'),
  ('aad25feb-a7e3-548c-a1a6-21356fb06766', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 14, 14, 'ንጉሡም ዮሴፍን “ሰፋንጢፋንስ” ብሎ ጠራው። ለዮሴፍ ሚስት ትሆነው ዘንድ የእንጀራ አሳላፊዎች አለቃ የሚሆን የኤሌዮጲስ ካህን ልጅ የፋጢፋራንን ልጅ ሰጠው።'),
  ('37d5634c-2c3d-5a20-a48e-fea209ef59db', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 15, 15, 'ዮሴፍም በፈርዖን ፊት በቆመ ጊዜ የሠላሳ ዓመት ሰው ነበር።'),
  ('99c4d9eb-cdb4-5aaf-a0e5-04aafb0d0cb6', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 16, 16, 'በዚያም ዓመት ይስሐቅ ሞተ። ስለ ሁለቱ ሕልሞች ትርጓሜ ዮሴፍ እንደ ተናገረው ደረሰ።'),
  ('a686f602-b1d9-5547-ad19-5d0f16883149', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 17, 17, 'በግብፅ ሀገር ሁሉ ሰባት ዓመት ጥጋብ ሆነ፤ የግብፅ ምድርም ብዙ ፍሬን አፈራች፤ አንዲቱ መስፈሪያ ሺህ ስምንት መቶ መስፈሪያ ሆነች።'),
  ('46d7abe9-6e10-5420-a69c-3c2d4fa8b028', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 18, 18, 'ዮሴፍም ስንዴው እስኪመላ ድረስ፥ ከብዛቱም የተነሣ መቍጠርና መስፈር እስኪሳናቸው ድረስ፥ የከተማውን ምግብ በየሀገሩ ሰበሰበ።'),
  ('6e9c657c-e4fb-5f33-acee-0a4799848f94', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 19, 19, 'በአርባ አምስተኛው ኢዮቤልዩ፥ በሁለተኛውም ሱባዔ፥ በሁለተኛው ዓመት፥ ይሁዳ ለበኵር ልጁ ለኤር ከአራም ልጆች ወገን ሚስትን አጋባው፤ ስምዋም ትእማር ይባላል።'),
  ('1120cec4-525b-5850-ae49-9789ba24cf85', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 20, 20, 'ጠላትም፥ ከእርስዋም ጋር አልተኛም፤ እናቱ ከከነዓን ልጆች ነበረችና፤ ከእናቱም ወገን ሚስትን ያገባ ዘንድ ወደደ፥ አባቱ ይሁዳ ግን አልፈቀደለትም።'),
  ('c2a38771-6c35-533f-a812-eae4a8421967', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 21, 21, 'ያም የይሁዳ የበኵር ልጅ ኤር ክፉ ነበረ፤ እግዚአብሔርም ቀሠፈው።'),
  ('5aa6b4b3-d4a8-5fe3-ad7f-7020c5d6458c', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 22, 22, 'ይሁዳም ልጁን አውናንን አለው፥ “ወደ ወንድምህ ሚስት ግባ፤ ዋርሳም አድርጋት። ለወንድምህም ዘር ተካለት።”'),
  ('b493e78c-e3c5-59d2-a028-a82fff623721', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 23, 23, 'አውናንም የእርሱ ልጅ እንደማይሆንና የወንድሙ ልጅ እንደሚሆን ዐወቀ፤ ወደ ወንድሙ ሚስትም ገባ። ነገር ግን ዘሩን በምድር ላይ ያፈስስ ነበር። ይህም በእግዚአብሔር ፊት ክፉ ሆነ፥ ቀሠፈውም።'),
  ('0194269c-d2cd-569e-ad55-8a79750e8db0', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 24, 24, 'ይሁዳም ምራቱን ትእማርን፥ “ልጄ ሴሎም እስኪያድግ ድረስ መበለት ሆነሽ በአባትሽ ቤት ተቀመጪ፤ ለእርሱም ሚስት ትሆኚው ዘንድ እሰጥሻለሁ” አላት።'),
  ('23fce183-2cb7-50c7-a6e3-6451e1cb09ff', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 25, 25, 'እርሱም አደገ፥ የይሁዳ ሚስት ቢድሱኤል ግን ያገባ ዘንድ ለልጅዋ ሴሎም አልፈቀደችም፤ የይሁዳ ሚስት ቢድሱኤልም በዚህ ሱባዔ በአምስተኛው ዓመት ሞተች።'),
  ('6a286a74-ca00-5a37-a7f4-d82c065deee8', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 26, 26, 'በስድስተኛው ዓመት ይሁዳ በጎቹን ይሸልት ዘንድ ወደ ቴምናታ ወጣ፤ ለትእማርም “እነሆ፥ አማትሽ በጎቹን ይሸልት ዘንድ ወደ ቴምናታ ይወጣል” ብለው ነገሩአት።'),
  ('41981a1e-8594-5468-a911-4472c1123c71', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 27, 27, 'የመበለትነቷንም ልብስ ትታ መጐናጸፊያዋን ለበሰች። አጊጣም በቴምናታ ጎዳና በር ተቀመጠች።'),
  ('8cecb2fc-dcd1-54cd-a116-6474b92a905a', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 28, 28, 'ይሁዳም ሲሄድ አገኛት፥ ጋለሞታም እንደ ሆነች ተጠራጥሮ፥ “ወደ አንቺ ልግባ” አላት፤ እርሷም፥ “ግባ” አለችው፥ ገባም፥ እርስዋም፥ “ዋጋዬን ስጠኝ” አለችው። “በጣቴ ካለ ቀለበቴ፥ ከኵፍየቴና በእጄ ካለ ዘንጌ በቀር በእጄ የለኝም” አላት።'),
  ('4c0f709d-f921-5f28-ac0a-1fa7187079e0', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 29, 29, 'እርስዋም፥ “ዋጋዬን እስክትሰድልኝ ድረስ እነርሱን ስጠኝ” አለችው፤ እርሱም፥ “አንድ የፍየል ጠቦት እልክልሻለሁ” አላት። ለእርስዋም እነርሱን ሰጣት።'),
  ('13fd9f37-822a-5f08-abfb-06ce774ce7a8', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 30, 30, 'እርስዋም ፀነሰችለት፤ ይሁዳም ወደ በጎቹ ሄደ፥ እርስዋም ወደ አባቷ ቤት ሄደች።'),
  ('a186b54a-8fcd-5f0f-aefa-06b1ea5a2cfc', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 31, 31, 'ይሁዳም በበግ ጠባቂው በአዶላማዊው እጅ የፍየሉን ጠቦት ሰደደላት፤ እርሱም አጣትና፥ “በዚያ የነበረችው ጋለሞታ ወዴት አለች?” ብሎ የሀገሩን ሰዎች ጠየቃቸው፤ እነርሱም፥ “በዚህ ጋለሞታ የለችም፥ በእኛ ዘንድም ጋለሞታ የለችም” አሉት።'),
  ('431e5b7f-a4a3-519b-a9b9-3d2bb30ff07b', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 32, 32, 'ተመልሶም፥ “አጣኋት፥ የሀገሩንም ሰዎች ጠየቅኋቸው እነርሱም፦ በዚህስ ጋለሞታ የለችም አሉኝ” ብሎ ነገረው።'),
  ('f1ca875f-f7a4-5bbc-a91d-2014df9356e3', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 33, 33, 'እርሱም፥ “መዘባበቻ እንዳንሆን ተነሥ እንሂድ” አለው። ከዚህም በኋላ ሦስት ወር በሆናት ጊዜ እርስዋ እንደ ፀነሰች ታወቀች፤ ለይሁዳም፥ “እነሆ፥ ምራትህ ትእማር በዝሙት ፀነሰች” ብለው ነገሩት።'),
  ('1e0c8959-bd62-5d84-a263-7e1d0c7538e3', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 34, 34, 'ይሁዳም ወደ አባቷ ቤት ሄደ፥ እናቷንና አባቷን፥ ወንድሞችዋንም፥ “በእስራኤል ዘንድ ኀጢአት ሠርታለችና በእሳት ያቃጥሉአት ዘንድ አውጡአት” አላቸው።'),
  ('08384a45-68b3-55b2-afd6-4102833cc396', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 35, 35, 'እንዲህም ሆነ፥ ያቃጥሉአት ዘንድ ባወጡአት ጊዜ፥ “ለእርሱ ፀንሻለሁና ይህ የማን እንደ ሆነ ዕወቅ ብላ ቀለበቱን፥ ኵፍየቱንና ዘንጉን ለአማቷ ላከች።'),
  ('1ec5cdf8-03cf-5c56-a665-6dbb1796de16', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 36, 36, 'ይሁዳም፥ “ትእማር ከእኔ ይልቅ እውነተኛ ሆነች፤ ከእንግዲህም አያቃጥሉአት” አለ። ስለዚህም ነገር ለሴሎም አልተሰጠችም። ከዚያም በኋላ ዳግመኛ አልቀረባትም።'),
  ('73b8f8d2-3c42-56bf-a8dd-d52137c5f1ce', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 37, 37, 'ከፀነሰችም በኋላ በዚህ በሁለተኛው ሱባዔ በሰባተኛው ዓመት ሁለቱን ልጆች ፋሬስንና ዛራን ወለደች።'),
  ('5a0c86dc-0d70-5852-a87c-aa412b9bfd91', 'bc2da0c1-8aef-5b8d-a7c2-715b8a1e0262', '6ccff3c0-b3cf-5ca6-acd0-1c1a1e4fa44f', 38, 38, 'ከዚህ በኋላ ዮሴፍ ለፈርዖን የነገረው ሰባቱ የጥጋብ ዐመት ተፈጸመ።'),
  ('aab17d07-bb33-528c-aa96-9d7e7606a524', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 1, 1, 'ይሁዳም ከምራቱ ጋር ተኝቶአልና የሠራው ሥራ ክፉ እንደ ሆነ ዐወቀ። በዐይኖቹ ፊት ራሱን አዋረደ። የልጁንም ኀፍረት ገልጦአልና እንደ በደለና እንደ ሳተ ዐወቀ።'),
  ('8f08cae1-5525-5d39-a317-84efccc8d383', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 2, 2, 'ስለ በደሉም በእግዚአብሔር ፊት ያዝንና ይለምን ጀመር።'),
  ('b5a115ac-b50f-54fd-a3e0-7312bcb65253', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 3, 3, 'ፈጽሞም ስለ ለመነና ስለ አለቀሰ እንዲሰረይለት በሕልም ነገርነው። ከዚህም በኋላ ኀጢአት አልሠራም። ከኀጢአቱና ከአለማወቁ ተመልሶአልና ስርየት ሆነለት።'),
  ('e1916c2c-34fd-518e-a31f-b48b3367cf59', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 4, 4, 'በአምላካችን ፊት በድሎአልና፥ እንዲህ የሚያደርግን ሰው ሁሉ፥ ከምራቱም ጋር የሚተኛን ሰው ሁሉ ይቃጠልበት ዘንድ በእሳት ያቃጥሉት። በእነርሱ ኀጢአትና በደል ሆኖአልና ስለዚህ ነገር በእሳት ያቃጥሉአቸው።'),
  ('5ac8ec32-83f0-5fb9-a2bb-fef18de5b452', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 5, 5, 'አንተም፥ “በመካከላቸው ርኵሰትና ኀጢአት እንዳይሆን የእስራኤልን ልጆች እዘዛቸው፤ ከምራቱና ከአማቱ ጋር የሚተኛ ሁሉ ርኵሰትን አድርጎአልና ከእርስዋ ጋር የተኛውን ሰው ሴቲቱንም በእሳት ያቃጥሉ።”'),
  ('5f6eb695-874b-5353-ad01-573695e1b2d6', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 6, 6, 'ቍጣውና መቅሠፍቱም ከእስራኤል ይርቃል።'),
  ('b5ce709d-0ffa-5ba5-ad10-0780a3f2418c', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 7, 7, 'ለይሁዳም ሁለቱ ልጆቹ ከእርስዋ ጋር እንዳልተኙ ነገርነው፤ ስለዚህም ዘሩ ለሌላ ነገድ ሆነ።'),
  ('1adaf47c-c8be-5c50-aa37-be2c47a53d03', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 8, 8, 'ለልጆቹ ከአዘዛቸው ከአብርሃም ፍርድ የተነሣ ይሁዳ በእሳት ያቃጥሉአት ዘንድ ወድዶአልና፥ በልበ ቅንነትም ሄዶአልና፥ ፍርድንም መርምሮአልና አልጠፉም።'),
  ('08ba1f24-1df9-5812-a7c3-8a9dce055933', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 9, 9, 'በአርባ አምስተኛው ኢዮቤልዩ በሦስተኛው ሱባዔ በመጀመሪያው ዓመት በምድሩ ላይ ድርቅ ይመጣ ጀመር።'),
  ('30ca63d6-608b-5c88-a0cf-f5f05b51a039', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 10, 10, 'ዝናብም በምድር መዝነቡን ተወ። ምንም የሚወርድ አልነበረምና። ምድርም ድርቅ ሆነች። በግብፅ ምድር ግን ምግብ ነበር፤ አዝመራ በሆነበት በሰባቱ ዓመት ዮሴፍ የግብፅን እህል ሰብስቦ ጠብቆት ነበርና።'),
  ('5563baf7-5933-5b85-ac4b-1245f13199a0', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 11, 11, 'የግብፅ ሰዎችም ምግባቸውን ይሰጣቸው ዘንድ ወደ ዮሴፍ መጡ። እርሱም የመጀመሪያው ዓመት ስንዴ ያለበትን ጎተራ ከፍቶ ለሀገሩ ሕዝብ በወርቅ ሸጠ።'),
  ('8ea95481-331a-5d78-a7b6-344e3fee2a17', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 12, 12, 'ያዕቆብም በግብፅ እህል እንዳለ ሰማ። ከግብፅም እህል ሸምተው ያመጡለት ዘንድ ዐሥሩን ልጆቹን ላከ።'),
  ('2714b08f-b57a-5aab-afc2-87b39dee5a60', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 13, 13, 'ብንያምን ግን አልላከውም። ወደ ግብፅ ከሚሄድ ነጋዴ ጋር ደረሱ። ዮሴፍም ዐወቃቸው፤ እነርሱ ግን አላወቁትም፤ ከእነርሱም ጋር ተነጋገረ። እንዲህም ብሎ ጠየቃቸው፥ “እናንተ ሰላዮች አይደላችሁምን? የሀገሩንም መግቢያ ትሰልሉ ዘንድ መጥታችኋል።” አሰራቸውም።'),
  ('d30be40f-3d00-5c43-a842-f13f55b5362b', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 14, 14, 'ከዚህ በኋላ ፈታቸው፤ ስምዖንንም ብቻ አስቀረ። ዘጠኙ ወንድሞቹንም በአቅማዳቸው ስንዴውን ሞልቶ ሰደዳቸው። ወርቃቸውንም በአቅማዳቸው ጨመረላቸው፤ እነርሱ ግን አላወቁም።'),
  ('cfd28429-3cef-59d8-ab07-929963ae24bc', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 15, 15, 'አባታቸው በሕይወት እንደ አለ፥ ታናሽ ወንድማቸውም እንደ አለ ነግረውታልና ታናሽ ወንድማቸውን ያመጡ ዘንድ አዘዛቸው።'),
  ('20bc894b-749b-5ef9-a886-9cc7134e9f70', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 16, 16, 'ከግብፅ ሀገርም ወጥተው ወደ ከነዓን ምድር ደረሱ፤ ያገኛቸውንም ነገር ሁሉ ፥ የሀገሩ ገዢ ከእነርሱ ጋር ጭንቅ ነገርን እንደ ተናገረ፥ ብንያምንም እስኪያመጡ ድረስ ስምዖንን መያዣ አድርጎ እንደ አስቀረው ለአባታቸው ነገሩት።'),
  ('36927093-a0ff-52e4-a023-dd70608be083', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 17, 17, 'ያዕቆብም አላቸው፥ “የወላድ መካን አደረጋችሁኝ፥ ዮሴፍ የለ፥ ስምዖን የለ፥ ብንያምንም ትወስዱብኝ ነውን? ክፋታችሁ በእኔ ደረሰ፤ ልጄ ከእናንተ ጋር አይሄድም።'),
  ('99b715a5-6b07-592b-a548-afa2a80f6a74', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 18, 18, 'እናታቸው ሁለት ልጆች ወልዳ ነበርና አንዱ ሞተ፤ ይህንም ትወስዱብኝ ነውን? በመንገድ ታሞ ቢሞት ያረጀ ሰውነቴን በኀዘን ወደ መቃብር ታወርዳላችሁን?” አላቸው። ወርቃቸው ሁሉ ተቋጥሮ እንደ ተመለሰ አይቶአልና ስለዚህ ነገር እርሱን መላክ ፈራ።'),
  ('d080f87e-19d8-597b-abbc-23d1b7abc677', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 19, 19, 'ከግብፅ ሰዎች ብዙዎች ዮሴፍ ብዙ እህልን እንደሚሰበስብ፥ ለረኃቡም ዓመት በጎተራ እንደሚያስቀምጥና እንደሚጠብቅ ካዩት ጀምሮ ለምግብ እህላቸውን ሰብስበዋልና ከግብፅ በቀር በከነዓንና በምድር ሁሉ ራቡ ፈጽሞ ጸና።'),
  ('8d13ac75-ef47-5a75-ada6-83a6db968b6e', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 20, 20, 'የግብፅ ሰዎችም በመጀመሪያው የራብ ዓመት ተመገቡት።'),
  ('1d720b75-66ac-51d5-a912-63210a087543', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 21, 21, 'ያዕቆብም በምድር ረኃብ እጅግ እንደ ጸና፥ መዳንም እንደ ሌለ ባየ ጊዜ ልጆቹን፥ “እንዳንሞት ወደ ግብፅ ሄዳችሁ እህል ሸምታችሁ አምጡልን” አላቸው። እነርሱም፥ “ታናሹ ወንድማችን ከእኛ ጋር ካልሄደ አንሄድም” አሉት።'),
  ('73587556-52f3-525f-a592-dd2147e301bb', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 22, 22, 'ያዕቆብም ብንያምን ከእነርሱ ጋር ካልሰደደው ከራቡ የተነሣ ሁሉም እንደሚጠፉ ዐሰበ፥ ሮቤልም፥ “እርሱን በእጄ ስጠኝ፤ መልሼ ባላመጣልህ ስለ እርሱ ፋንታ ሁለቱን ልጆችን ግደላቸው” አለው።'),
  ('82c2310d-7c0d-58e3-a89b-4b99b79c7f80', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 23, 23, 'እርሱም፥ “ከአንተ ጋር አይሄድም” አለው። ይሁዳም ቀርቦ፥ “ከእኔ ጋር ስደደው፤ መልሼ ባላመጣልህም በሕይወት ዘመኔ ሁሉ በፊትህ በደለኛ ልሁን” አለ።'),
  ('2f2a45ee-dab0-56bf-a98d-77a4ba54f2fb', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 24, 24, 'በዚህ ሱባዔ በሁለተኛው ዓመት በዐሥረኛው ወር መባቻ ከእነርሱ ጋር ሰደደው፤ ከሚሄዱትም ሁሉ ጋር ወደ ግብፅ ደረሱ። ከእነርሱም ጋር እጅ መንሻቸው ልባንጃ፥ ለውዝ፥ ጠርቤንቶስና የማር ወለላ በእጃቸው ነበር።'),
  ('227b4b79-cae9-5004-a44d-afb126f73200', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 25, 25, 'ደርሰውም በዮሴፍ ፊት ቆሙ። ወንድሙን ብንያምንም ባየው ጊዜ ዐወቀው።'),
  ('3f060570-524d-5232-a3af-090de742c2cc', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 26, 26, '“ትንሽ ወንድማችሁ ይህ ነውን?” አላቸው። እነርሱም፥ “አዎን፥ ነው” አሉት። እርሱም፥ “ልጄ ሆይ፥ እግዚአብሔር ይጠብቅህ” አለው፥ ወደ ቤቱም ሰደዳቸው፤ ስምዖንንም አወጣላቸው።'),
  ('ba9e2d37-fc18-590f-a942-902a4b9b73fe', '4525012b-53a7-5ca4-acb2-c106729cbcdd', 'cf05cec2-4280-5a69-ac83-cb68f1e46914', 27, 27, 'ግብርም አገባላቸው፥ በእጃቸውም ያመጡትን እጅ መንሻቸውን አቀረቡለት። በፊቱም በሉ፤ ለሁሉም ፋንታ ፋንታቸውን ሰጣቸው። ከሁሉም ፋንታ ይልቅ የብንያም ፋንታ ሰባት እጅ በለጠ። በሉ፥ ጠጡም፥ ሄደውም አህዮቻቸው ባሉበት ዐደሩ።'),
  ('ef1d3466-d639-5a96-a0d0-6b80a28e5a2e', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 1, 1, 'ዮሴፍም እርስ በርሳቸው የደኅንነትና የሰላም ዐሳብ እንዳላቸው፥ ያም ባይሆን የጠብ ዐሳብ እንዳላቸው፥ ዐሳባቸውን ያውቅ ዘንድ ዐሰበ።'),
  ('b16bfafb-10a7-5ac5-a5da-45a45f0213b9', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 2, 2, 'በቤቱ ላይ የተሾመውንም ሹም፥ “በአቅማዳቸው ሁሉ እህልን ምላላቸው፥ ወርቃቸውንም በየአቅማዳቸው አድርግላቸው፤ የምጠጣበትንም የብሩን ጽዋ በታናሹ ልጅ አቅማዳ አድርገህ ስደዳቸው” አለው።'),
  ('88547c8f-bf22-5a53-a96d-36b5488b0e27', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 3, 3, 'እርሱም ዮሴፍ እንዳዘዘው አደረገ። በየአቅማዳውም እህሉን ሁሉ መላ፥ ወርቃቸውንም በየአቅማዳቸው ጨመረላቸው። የብሩንም ጽዋ በብንያም አቅማዳ ጨመረ፤ በነጋም ጊዜ ፈጥነው ሄዱ።'),
  ('8ad79b48-e1cb-5f6d-a6c1-da3456904abb', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 4, 4, 'ከዚያም በወጡ ጊዜ እንዲህ ሆነ። ዮሴፍ በቤቱ የተሾመውን ሹም፥ “ፈጥነህ ተከተላቸው፦ በጎ ነገርን ስላደረግሁላችሁ ፋንታ ክፉ ነገር ከፈላችሁኝ፤ ጌታዬም የሚጠጣበትን የብር ጽዋ ሰረቃችሁኝ ብለህ ተከራክረህ ታናሽ ወንድማቸውን መልስልኝ፥ ወደ አደባባይ ሳልወጣ ፈጥነህ አምጣው” አለው።'),
  ('b5ae8ec5-d1cc-5137-a62d-cf8ea7516e4f', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 5, 5, 'በኋላቸውም ፈጥኖ ተከትሎ እንዲህ ባለ ነገር ተናገራቸው። እነርሱም አሉት፥ “ለእኛ ለባሪያዎችህ እንዲህ ያለ ነገር አግባባቸው አይደለም። ይህን ነገር አያደርጉም፤ ከጌታህም ቤት ምንም ገንዘብ አይሰርቁም።'),
  ('f6420baa-cf53-5bca-a2b8-09237d169b73', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 6, 6, 'እኛ ባሪያዎችህ ቀድሞ በአቅማዳችን ያገኘነውን ወርቃችንን ስንኳ ከከነዓን መልሰናል፥ እንዴት ገንዘብ እንሰርቃለን? እነሆ፥ እኛም አለን፤ አቅማዳችንም አለ፤ በርብር።'),
  ('a4b5ad21-1f89-5d03-a92f-431d9638048f', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 7, 7, 'ከእኛም ጽዋውን ያገኘህበት አንዱ ሰው ይገደል፤ እኛም አህዮቻችንም ለጌታህ እንገዛ።”'),
  ('f1ae88c1-6b05-5534-a454-c00d8ea99821', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 8, 8, 'እርሱም አላቸው፥ “ነገሩ እንዲህ አይደለም፤ ጽዋውን ያገኘሁበትን ሰው እርሱን ብቻ ይዤ አገልጋይ አደርገዋለሁ፤'),
  ('1d0bb097-6860-54ee-abd6-24a0c7faa934', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 9, 9, 'እናንተ ግን በሰላም ወደ ቤታችሁ ተመለሱ።”'),
  ('f690f5ff-21b5-5c33-af92-f9e2a3d9b5b0', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 10, 10, 'ገንዘባቸውንም ሲበረብር ከትልቁ ጀምሮ በታናሹ ጨረሰ፤ በታናሹም በብንያም አቅማዳ ተገኘ። ደንግጠውም ልብሶቻቸውን ቀደዱ። አህዮቻቸውንም ጭነው ወደ ከተማ ተመለሱ። ወደ ዮሴፍም ቤት ደረሱ። ሁሉም በግንባራቸው በምድር ላይ ተደፍተው ሰገዱለት።'),
  ('71101c93-7f22-579f-ac17-ee1ad7102bdb', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 11, 11, 'ዮሴፍም፥ “ክፉ አደረጋችሁ” አላቸው። እነርሱም አሉ፥ “ምን እንናገራለን? ምንስ እንመልሳለን? አንተ ጌታችን የእኛን የአገልጋዮችህን በደል አገኘህብን፤'),
  ('412fa488-936d-52e4-a1d0-7f48adb8785d', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 12, 12, 'እነሆ፥ እኛ ለጌታችን ባሪያዎች ነን፤ አህዮቻችንም ለአንተ ናቸው።”'),
  ('93e19327-fb7f-59bb-aeb4-7c7c8552ca48', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 13, 13, 'ዮሴፍም አላቸው፥ “እኔስ እግዚአብሔርን እፈራለሁ፤ እናንተም ወደ ሀገራችሁ ሂዱ፥ ክፉ ሥራ ሠርቶአልና ወንድማችሁ ብቻ ተገዢ ይሁን፤ ሰው ጽዋውን እንደሚወድ፥ እኔም በዚህ ጽዋ እንደምጠጣ አታውቁምን? እርሱንም ሰረቃችሁኝ።”'),
  ('e77607bf-dc61-549d-adf5-f8734636e2f6', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 14, 14, 'ይሁዳም አለ፥ “ጌታዬ፥ አንተ በጆሮህ እየሰማህ አንድ ቃል ልናገር። የዚህ የአገልጋይህ እናት ለአባታችን ሁለት ልጆች ወለደች፤ አንዱ ወጥቶ ጠፋ፤ ያገኘውም የለም፤ ይህ ግን ለእናቱ እርሱ ብቻ ቀርቶአል።'),
  ('bfc10f8c-eaf6-5704-a511-a8abf3ae7926', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 15, 15, 'አገልጋይህ አባታችንም ይወደዋል። ልቡናውም ከዚህ ከልጁ ልቡና ጋር የታሰረች ናት። ወደ ባሪያህ ወደ አባታችን ብንሄድ፥ ይህም ሕፃን ከእኛ ጋር ካልሄደ ይሞታል።'),
  ('51ef862e-242c-5be3-aca1-52477f73be75', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 16, 16, 'ለሞት እስኪደርስ ድረስ አባታችንን በኀዘን እንገድላለን። ነገር ግን እኔ አገልጋይህ ስለዚህ ልጅ ፋንታ ለጌታዬ ተገዥ ሆኜ ልኑር፤ ልጁም ከወንድሞቹ ጋር ይሂድ። ከአገልጋይህ አባታችን እጅ ዋስ ሆኜ አምጥቼዋለሁና እኔ አገልጋይህ መልሼ ባልወስደው በዘመኑ ሁሉ አባታችንን እበድላለሁ።”'),
  ('22b242a0-33f4-543d-af5f-8b46b1946e1d', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 17, 17, 'ዮሴፍም የሁሉ ልቡና አንዱ ከአንዱ ጋር በበጎ ነገር እኩል እንደ ሆነ ባየ ጊዜ መታገሥ ተሳነው።'),
  ('7098e501-cdb3-503e-a280-672acc2fe4da', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 18, 18, 'እርሱም ዮሴፍ እንደ ሆነ ነገራቸው፥ በዕብራይስጥም ቋንቋ ከእነርሱ ጋር ተነጋገረ። አንገታቸውንም አቅፎ አለቀሰ። እነርሱ ግን አላወቁትም ነበር፤ እነርሱም ያለቅሱ ጀመር።'),
  ('4aff10d5-276a-5609-abca-39070702663b', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 19, 19, 'እርሱም አላቸው “በእኔ አታልቅሱ፥ አባቴን ፈጥናችሁ ወደ እኔ አምጡት፤ ሳልሞትም አባቴን ልየው፥ የወንድሜ የብንያምም ዐይኖች እያዩ ልየው። ይህ የራቡ ዘመን እነሆ፥ ሁለተኛ ዓመት ነው። ገናም አምስት ዓመት አለ፤ አዝመራ የለም፥ የእንጨት ፍሬም የለም፥ እርሻም የለም። እናንተም ከጓዛችሁ ጋር ፈጥናችሁ ኑ፤ በራብም አትሙቱ። ስለ ጓዛችሁም አትጨነቁ።'),
  ('b0cd87bf-f36f-5b82-a9de-8e3cc08364b9', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 20, 20, 'ብዙ ወገኖች ይድኑ ዘንድ እግዚአብሔር እኔን አስቀድሞ ለማዘጋጀት ልኮኛልና። እኔም ገና በሕይወት እንዳለሁ ለአባቴ ንገሩት።'),
  ('f1aef787-6ddb-554b-a945-e8ce820eb0b1', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 21, 21, 'ለፈርዖን እንደ አባቱ እሆን ዘንድ፥ በቤቱና በግብፅ ሀገርም ሁሉ እሠለጥን ዘንድ እግዚአብሔር እንደ ሾመኝ እነሆ፥ እናንተ ታያላችሁ።'),
  ('b2d75b11-fc51-549d-afa6-d463e20cfdd6', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 22, 22, 'ለአባቴም፦ ጌትነቴን ሁሉ፥ እግዚአብሔርም የሰጠኝን ብልጽግናና ክብርን ሁሉ ንገሩት።”'),
  ('a5b88210-eaa9-5ca7-a60b-45375187ac6e', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 23, 23, 'በፈርዖንም ትእዛዝ ለመንገድ ሰረገላዎችንና ስንቅን ሰጣቸው። ለሁሉም አራት ኅብር ያለው ልብስና ብርን ሰጣቸው። ለአባታቸውም ልብስና ብርን፥ ስንዴ የሚወስዱባቸውንም ዐሥር አህዮች ላከ። አሰናበታቸውም።'),
  ('30b436b2-851b-5da8-a29e-0f13afe62f87', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 24, 24, 'ወጥተውም ለአባታቸው፥ ዮሴፍ በሕይወት እንደ አለ፥ በምድር ላሉ አሕዛብ ሁሉ ስንዴን እንደሚሰፍር፥ በግብፅ ሀገር ሁሉም ላይ እንደ ሠለጠነ ነገሩት።'),
  ('b80f2b48-283a-516a-ac80-7505ba00325a', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 25, 25, 'አባታቸው ግን ልቡናው ደንግጦአልና አላመናቸውም።'),
  ('96c58b42-0b4c-54cd-af4b-d96cc5853b5e', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 26, 26, 'ከዚህ በኋላ ዮሴፍ የላከለትን ሰረገላዎች አይቶ ሰውነቱ እንደ ገና ታደሰ።'),
  ('db287bde-dacc-5e3a-ae12-98406e7d66c8', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 27, 27, 'እርሱም አለ፥ “ይህ ለእኔ ታላቅ ነው። ዮሴፍ ሕያው ነውና ሳልሞት ወርጄ ልየው” አለ።'),
  ('044f20c3-be66-5cae-a40e-6e172b3c6621', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 28, 28, 'ያዕቆብም በሦስተኛው ወር መባቻ ከከንዓን ከቤቱ ተነሥቶ በቤርሳቤህ ጎዳና ሄደ። በዚህም ወር በሰባተኛው ቀን ለአባቱ ለይስሐቅ አምላክ መሥዋዕትን ሠዋ።'),
  ('7614749d-2d81-52d0-ad01-9efef0c34e85', 'b8ba72b1-5cfe-5116-a89c-812051662054', '4b320102-a44f-58bf-a822-9137c1121883', 29, 29, 'ያዕቆብም በቤቴል ያየውን ሕልም ዐሰበ፥ ወደ ግብፅ መውረድንም ፈራ። ዮሴፍ ወደ እርሱ እንዲመጣ እርሱም ወደ ግበፅ እንዳይወርድ ይልክበት ዘንድ ሲያስብ ሰነበተ።'),
  ('25b5cb67-515c-5e58-af31-a2fe578ce499', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 1, 1, 'ይቀር ዘንድ፥ ወይም ይወርድ ዘንድ ራእይ ያይ እንደ ሆነ በዚያ ሰባት ቀን ተቀመጠ። ከከረመውም ስንዴ የመጀመሪያውን ፍሬ በዓል አደረገ።'),
  ('7c490a6a-ca97-58b7-af5f-273ec0bc2732', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 2, 2, 'በአውሬዎችና በከብቶች፥ በወፎችና በሰዎች ሁሉ ድርቅ ስለ ሆነ ከከነዓን ሀገር ሁሉ በምድር የሚዘሩት ምንም እፍኝ ሙሉ ዘር አልነበረምና።'),
  ('bd556081-2d32-5f8c-a0d9-bbc0fff49ec9', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 3, 3, 'በዐሥራ ስድስተኛውም ቀን እግዚአብሔር ተገለጠለት፥ “ያዕቆብ፥ ያዕቆብ” ብሎ ጠራው። ያዕቆብም፥ “እነሆ፥ አለሁ” አለ። እርሱም አለው፥ “የአባቶችህ የአብርሃምና የይስሐቅ አምላክ እኔ ነኝ። በዚያ ብዙ ወገን አደርግሃለሁና ወደ ግብፅ መውረድን አትፍራ፤ እኔ ከአንተ ጋር እወርዳለሁ። እኔም እወስድሃለሁ፥ በዚያችም ምድር ትቀበራለህ።'),
  ('072a5797-f529-5ee2-ac99-a2fd3e22a493', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 4, 4, 'ዮሴፍም እጁን በዐይኖችህ ላይ ያኖራል፤ አትፍራ፤ ወደ ግብፅም ውረድ።”'),
  ('4228dbe3-696a-5f9c-a81d-933061cbd5df', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 5, 5, 'ያዕቆብም ተነሣ፤ ልጆቹና የልጅ ልጆቹም ተነሡ፤ አባታቸውንና ጓዛቸውንም በሰረገላ ጫኑ።'),
  ('21403eed-72ef-5f10-a26a-b193595c63b0', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 6, 6, 'በዚህ በሦስተኛው ወር በዐሥራ ስድስተኛው ቀን ያዕቆብ ከዐዘቅተ መሐላ ተነሥቶ ወደ ግብፅ ሄደ።'),
  ('44c5a749-5182-56c2-ae4d-fe40eb9997ca', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 7, 7, 'ያዕቆብም ከእርሱ አስቀድሞ የጌሼምን ምድር ይጐበኝ ዘንድ ልጁን ይሁዳን ወደ ልጁ ዮሴፍላከ። ለእርሱ አቅራቢያ ይሆኑ ዘንድ፥ በዚያ ሊኖሩ እንዲመጡ ዮሴፍ ነግሮአቸዋልና።'),
  ('c6b0ce73-1152-5870-aeb8-1b1b613a7083', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 8, 8, 'ይህችውም በግብፅ ምድር መልካም ነበረች። ለእርሱም ቅርብ ነበረች፥ ለእስራኤልና ለከብቶቻቸውም የተመቸች ነበረች።'),
  ('59912d17-116e-52f8-a9ae-6baf4f7f734b', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 9, 9, 'ከአባታቸው ከያዕቆብ ጋር ወደ ግብፅ የወረዱ የያዕቆብ ልጆች ስማቸው ይህ ነው። የያዕቆብ የበኵር ልጅ ሮቤል ነው። የልጆቹም ስማቸው ኤኖክ፥ ፋሉስ፥ ኤስሮም፥ ከርሚ፥ ከእርሱ ጋር እነዚህ አምስቱ ናቸው።'),
  ('e7c21be0-30f5-5b3e-a7d9-c1965ac89575', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 10, 10, 'ስምዖንና ልጆቹ፥ የልጆቹም ስማቸው ይህ ነው። ኢሙኤል፥ ኢያሚን፥ አዕዎት፥ ኢያኪም፥ ሳዖር፥ የስፍንስዋቅ ልጅ ሳውል፥ ከእርሱ ጋር እነዚህ ሰባቱ ናቸው።'),
  ('3642990d-e6b8-5c0d-a3d3-c2a5c73b87cb', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 11, 11, 'ሌዊና ልጆቹ፥ የልጆቹም ስም ይህ ነው። ጌድሶር፥ ቀዓት፥ ሜራሪ፥ እኒህ አራቱ ናቸው።'),
  ('ee689451-9b34-52df-ab34-d9eabbb91f64', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 12, 12, 'ይሁዳና ልጆቹ፥ የልጆቹም ስም ሴሎም፥ ፋሬስ፥ ዛራ፥ እሊህ አራቱ ናቸው።'),
  ('58693ab5-37c4-56dd-ae04-ac6307f6b81c', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 13, 13, 'ይሳኮርና ልጆቹ፥ የልጆቹም ስም ይህ ነው። ቶላ፥ ፉኣ፥ ኢያስብ፥ ሳምሮን፥ እኒህ አምስቱ ናቸው።'),
  ('b0f0f579-a0da-5b5d-a283-a97452c24289', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 14, 14, 'ዛብሎንና ልጆቹ፥ የልጆቹም ስም ይህ ነው። ሳኦር፥'),
  ('53a4c06f-8c1a-5714-ab79-cdc04bf93c6c', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 15, 15, 'የያዕቆብ ልጆች፥ ልጆቻቸውም እነዚህ ናቸው፤ በመስጴጦምያ ልያ ለያዕቆብ የወለደችለት ስድስት ናቸው። አንዲቱ እኅታቸው ዲና ናት። ከልያ የተወለዱ ልጆች ሁሉ ከአባታቸው ከያዕቆብ ጋር ወደ ግብፅ የወረዱ ልጆቻቸውም ሃያ ዘጠኝ ናቸው። አባታቸው ያዕቆብም ከእነርሱ ጋር ተቈጥሮ ሠላሳ ሆኑ።'),
  ('bcf23cf9-0260-5ff4-aea8-5bd833882895', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 16, 16, 'የያዕቆብ ሚስት የልያ አገልጋይ ዘለፋ ለያዕቆብ የወለደችለት ልጆች ጋድና አሴር ናቸው። ከእነርሱ ጋር ወደ ግብፅ የወረዱት የልጆቻቸውም ስም ይህ ነው።'),
  ('fb0d9c32-991a-54f2-af3c-23cdc91d6908', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 17, 17, 'የጋድ ልጆች ሳፍዮን፥ አሐዲ፥'),
  ('8299d964-78a0-5b70-ac4f-17ac4137decc', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 18, 18, 'የአሴርም ልጆች፥ ኢያምና፥ ይሱአ፥ በርያ አንዲት እኅታቸውም ሣራ ናቸው። እነዚህ አምስቱ ናቸው።'),
  ('b1e93487-fc71-5e09-a70b-38c958ffb62e', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 19, 19, 'የዘለፋም ልጆች ዐሥራ አራት ናቸው። የልያም ሁሉ አርባ አራት ሆኑ።'),
  ('7faf24d6-944b-5aa3-ad5f-982098a1ef17', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 20, 20, 'የያዕቆብ ሚስት የራሔል ልጆች ዮሴፍና ብንያም ናቸው። አባቱ ወደ ግብፅ ሳይወርድ ለዮሴፍ በግብፅ ልጆች ተወለዱለት። የኤልዮጶሊስ ካህን የሚሆን የፋጢፋራ ልጅ አስኔት የወለደችለት ምናሴና ኤፍሬም ናቸው።፥ እነዚህ ሦስቱ ናቸው።'),
  ('c9253af9-b4a5-57f9-afc5-f057f28790c8', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 21, 21, 'የብንያምም ልጆች ላውባኤል፥ አስቤል፥ ጎአው፥ ንዕማን፥ አብሮድዮ፥ ራኤፍስ፥ ያኒማ፥ አፊም፥ የአም፥ ጋዐም፥'),
  ('35f63b51-de1d-5fd8-a359-363507801282', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 22, 22, 'ዳንና ንፍታሌምን የወለደችለት የያዕቆብ ሚስት የራሔል አገልጋይ የባላ ልጆች እነዚህ ናቸው። ከእነርሱ ጋር ወደ ግብፅ የወረዱት የልጆቻቸውም ስም ይህ ነው።'),
  ('e8185dbf-6639-566a-a9ec-e10cf7c7c053', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 23, 23, 'የዳን ልጆች ኩሲም፥ ሰሞን፥ አሱድ፥ ኢያሳክ፥ ሰሎሞን ናቸው፥ እኒህ ስድስቱ ናቸው። በገቡበት ዓመት በግብፅ ሞቱ። ለዳንም ኩሲም ብቻ ተረፈለት።'),
  ('3a719f9e-20c3-5c8f-a513-b250ba29182a', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 24, 24, 'የንፍታሌምም ልጆች ስማቸው ይህ ነው። ኢያስኤል፥ ገሀን፥ አስዓር፥ ያኩም፥ አው ናቸው፤ ከረሃቡ ዘመን በኋላ የተወለደ አው በግብፅ ሞተ። የራሔል ሰዎች ሁሉ ሃያ ሰባት ሆኑ፥ ወደ ግብፅ የወረዱ የያዕቆብ ልጆች ሁሉ ሰባ ሰዎች ናቸው።'),
  ('56e6a181-7a99-5507-adc3-9cd0fa893672', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 25, 25, 'እንግዲህ እነዚህ ልጆቹና የልጅ ልጆቹ ሁሉ ሰባ ናቸው። ሚስትም ሳያገቡ በግብፅ የሞቱት አምስት ናቸው፤ ልጅም አልነበራቸውም።'),
  ('1c443125-7ab9-5d6e-a745-26fa6735f0c9', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 26, 26, 'የይሁዳ ሁለቱ ልጆቹ ኤርና አውናን በከነዓን ሀገር ሞቱበት፥ ልጅም አልነበራቸውም፤ የሞቱትንም የእስራኤል ልጆች ቀበሩአቸው። እነዚህም ወገኖች ከሰባው ሰዎች ጋር ተቈጠሩ።'),
  ('e62dfca4-883c-55ad-a99d-a81b0732a5a0', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 27, 27, 'ያዕቆብም በአርባ አምስተኛው ኢዮቤልዩ በሦስተኛው ሱባዔ በሁለተኛው ዓመት በአራተኛው ወር መባቻ ወደ ግብፅ ወደ ጌሴም ምድር ገባ።'),
  ('64e44ba7-b030-549b-a282-4b6351eeca7b', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 28, 28, 'ዮሴፍም አባቱን ያዕቆብን ይቀበል ዘንድ ወደ ጌሴም ምድር መጣ። የአባቱንም አንገት አቅፎ አለቀሰ። ያዕቆብም ዮሴፍን፥ “አይችሃለሁና እንግዲህ ወዲህ ልሙት” አለው።'),
  ('d1373119-8b03-53d5-a726-4ebda340f125', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 29, 29, '“አሁንም ከአገልጋዩ ከያዕቆብ ምሕረቱንና ይቅርታውን ያላራቀ የእስራኤል አምላክ የአብርሃም አምላክ፥ የይስሐቅም አምላክ ይመስገን፤ በቤቴል ያየሁት ራእይ እውነተኛ ሕልም ነውና እኔ በሕይወት ፊትህን ማየቴ ለእኔ ታላቅ ነው፤ አምላኬ እግዚአብሔር ለዘለዓለሙ ይመስገን፤ ስሙም የተመሰገነ ነው” አለ።'),
  ('d76996e6-d6a7-55fb-ab8b-90497842a7b3', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 30, 30, 'ዮሴፍና ወንድሞቹ በአባታቸው ፊት እንጀራን በሉ፤ ወይንንም ጠጡ፤ ያዕቆብም ዮሴፍን ከወንድሞቹ ጋር በፊቱ ሲበላና ሲጠጣ አይቶታልና ፈጽሞ ደስ አለው። እርሱን የጠበቀውን፥ ዐሥራ ሁለቱን ልጆቹንም የጠበቀለትን፥ የሁሉን ፈጣሪ አመሰገነው።'),
  ('01d965cf-1c29-5a99-a4e2-7f3d0a50a79c', '34c55332-de69-5fe3-a3d3-78d37f253011', 'f70c5481-0256-520a-ae3e-e6e9e24aabfa', 31, 31, 'ዮሴፍም በጌሴም ምድርና በራምሴ በፈርዖን ፊት እነርሱ በሚገዙት በአውራጃዋም ሁሉ ይኖሩ ዘንድ ለአባቱ ገንዘብ ሰጠው፤ ለወንድሞቹም ሰጣቸው።'),
  ('59871108-56fc-5984-a14e-09f3d27df99c', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 1, 1, 'ያዕቆብ ከልጆቹ ጋር ከግብፅ ምድር በምትሻለው በጌሴም ምድር ኖረ። ያዕቆብም ወደ ግብፅ በገባ ጊዜ የመቶ ሠላሳ ዓመት ሰው ነበረ።'),
  ('09acc229-0e14-5355-a126-d8ebd03f389a', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 2, 2, 'ዮሴፍም ለአባቱና ለወንድሞቹ ለቤተሰቦቻቸውም ለሰባቱ የራብ ዓመት የሚበቃ ምግብን ሰጣቸው። ከራቡ ጽናት የተነሣም የግብፅ ምድር ተጨነቀች።'),
  ('78286b59-912a-5cdf-acaa-5503adc9b4a5', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 3, 3, 'ዮሴፍም መላዋን የግብፅ ምድርን በእህል ምክንያት ለፈርዖን እጅ አደረጋት። ሰውንና ከብቱን፥ ሁሉንም ለፈርዖን ገንዘብ አደረገ። የራቡም ዘመን ተፈጸመ።'),
  ('de6293aa-6de0-57dd-a70d-fb664e6aa898', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 4, 4, 'ዮሴፍ በስምንተኛው ዓመት ዘር ይዘሩ ዘንድ በግብፅ ላሉ ሰዎች ዘርንና ምግብን ሰጠ። ፈሳሹ በግብፅ ሀገር ሁሉ መልቶአልና፥ በሰባቱ የራብ ዐመታት በወንዝ አጠገብ ካሉ ከጥቂቶች ቦታዎች በቀር አያጠጣም ነበርና።'),
  ('922b1ff2-4855-5604-a4ae-c0321b9f98cf', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 5, 5, 'ዛሬ ግን ወንዙ መልቶአል፤ የግብፅ ሰዎችም ምድሩን ዘሩ፤ ምድርም በዚያ ዓመት ብዙ ስንዴን አፈራች። ያም ዓመት የአርባ አምስተኛው ኢዮቤልዩ የአራተኛው ሱባዔ መጀመሪያ ነው።'),
  ('f13c03c2-2c87-5a48-a4b4-43e7705d6c8a', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 6, 6, 'ዮሴፍም ከዘሩት እህል አምስተኛውን እጅ ወስዶ ለንጉሥ አገባ። አራቱንም እጅ ለዘርና ለምግብ ሊሆናቸው ተወላቸው። ዮሴፍም እስከዚህ ቀን ድረስ ለግብፅ ሀገር ሰዎች ይህን ሥርዐት አደረገላቸው።'),
  ('6c76d279-18fa-532e-a15f-fabb64211abc', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 7, 7, 'ያዕቆብም በግብፅ ሀገር ዐሥራ ሰባት ዓመት ኖረ። የኖረባቸውም ዓመታት ሁሉ ሦስት ኢዮቤልዩ ሆኑ፥ ሦስት ኢዮቤልዩም መቶ አርባ ሰባት ዓመት ነው። በአርባ አምስተኛው ኢዮቤልዩ በአምስተኛው ሱባዔ በአራተኛው ዓመት ሞተ።'),
  ('fb360638-0aee-5f67-a079-4c4d59c24cd2', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 8, 8, 'ያዕቆብም ሳይሞት ልጆቹን መረቃቸው። በግብፅ ሀገር የሚያገኛቸውን ሁሉ፥ በኋለኛውም ዘመን በእነርሱ ላይ የሚመጣባቸውን ሁሉ ነገራቸው፤ መረቃቸውም።'),
  ('2c9cd074-b4e0-54b9-acd5-b9b5e90ae5cb', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 9, 9, 'ለዮሴፍም በምድር ላይ ሁለት ዕጣ ሰጠው። እንደ አባቶቹም አንቀላፋ። በከነዓንም ሀገር ደርብነት ባላት ዋሻ በአባቱ በአብርሃም አጠገብ ተቀበረ። ይኸውም በከነዓን ሀገር ደርብነት ባላት ዋሻ ለራሱ በቈፈራት መቃብር ነው። የእርሱን መጽሐፎችና የአባቶቹን መጽሐፎች ሁሉ እስከዚህ ቀን ድረስ ለልጆቹ ይጠብቃቸውና ያድሳቸው ዘንድ ለልጁ ለሌዊ ሰጠው።'),
  ('5292b1d1-3273-5b97-aa0b-ef8fdd2c0d9d', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 10, 10, 'ያዕቆብም ከሞተ በኋላ እንዲህ ሆነ፤ የእስራኤል ልጆች በግብፅ ሀገር በዙ፤ ብዙ ወገንም ሆኑ። ወንድም ወንድሙን ይወድ ዘንድ፥ ባልንጀራም ከባልንጀራው ጋር ይረዳዳ ዘንድ ሁሉም በልቡናቸው የተካከሉ ሆኑ።'),
  ('a6839fd5-465f-5378-aa97-a3c78bae865f', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 11, 11, 'ዮሴፍም በኖረበት ዘመን ሁሉ በዐሥሩ የሱባዔ ዓመታት እጅግ በጣም በዙ። ዮሴፍም በኖረበት ዘመን ሁሉ የእስራኤልን ልጆች የግብፅ ሰዎች ሁሉ ያከብሩአቸው ነበረና አባቱ ያዕቆብ ከሞተ በኋላ ዮሴፍ በኖረበት በሕይወቱ ዘመን ሁሉ ባላጋራ አልነበረም፤ ምንም ክፉ አልነበረም።'),
  ('f9eaffea-424b-5766-ae1a-b803f16d0891', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 12, 12, 'ዮሴፍም የመቶ ዐሥር ዓመት ሰው ሲሆን ሞተ፤ በከነዓን ምድር ዐሥራ ሰባት ዓመት ኖረ፥ ዐሥር ዓመት ሲያገለግል ኖረ፥ ሦስት ዓመት በግዞት ቤት ኖረ፤ ሰማንያ ዓመት ከንጉሥ በታች ሆኖ የግብፅን ሀገር ሁሉ እየገዛ ኖረ። ሞተም፤ ወንድሞቹም ሁሉ ሞቱ። ያችም ትውልድ ሁላ ሞተች።'),
  ('162dcd73-a754-5428-a8bb-7382f2332fa8', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 13, 13, 'ከግብፅም በሚወጡበት ወራት ዓፅሙን ይወስዱ ዘንድ ሳይሞት የእስራኤልን ልጆች አዘዛቸው። የግብፅ ሰዎች ዕለቱን አውጥተው ዳግመኛ በከነዓን ሀገር እንደማይቀብሩት ዐውቆአልና ስለ ዓፅሙ አማላቸው። የከነዓን ንጉሥ መምከሮን አሱር በሚባል ሀገር ሲኖር ከግብፅ ንጉሥ ጋር በቆላ ተዋግቶአልና፥ በዚያም ገድሎታልና።'),
  ('8ef3f9aa-665b-5ce3-a893-976006cc07e7', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 14, 14, 'እስከ ኤርሞንም በር ድረስ ግብፃውያንን አሳደደ፤ በግብፅም ሁለተኛ ሌላ ንጉሥ ነግሦአልና መግባት ተሳነው፤ ከእርሱም ይልቅ በርትቶአልና ወደ ከነዓን ሀገር ተመለሰ፤ የግብፅ በሮችም ተዘጉ፤ ወደ ግብፅም የሚወጣና የሚገባ አልነበረም።'),
  ('c2d6557c-7383-59cf-a58e-422bad5ce720', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 15, 15, 'ዮሴፍም በአርባ ሰባት ኢዮቤልዩ በሦስተኛው ሱባዔ በሁለተኛው ዓመት ሞተ። በግብፅም ሀገር ቀበሩት፤ ከእርሱም በኋላ ወንድሞቹ ሁሉ ሞቱ።'),
  ('dda5f586-cca8-5cd5-a029-b2fcf3889d66', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 16, 16, 'በአርባ ሰባተኛው ኢዮቤልዩ በሁለተኛው ሱባዔ በሁለተኛው ዓመት የግብፅ ንጉሥ ከከነዓን ንጉሥ ጋር ይዋጋ ዘንድ ወጣ።'),
  ('d4ff8d74-0e7b-5d8b-aa90-2006c6841010', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 17, 17, 'የእስራኤልም ልጆች ከዮሴፍ ዓፅም በቀር የያዕቆብን ልጆች ዓፅሞች ሁሉ በምድረ በዳ በተራራ ላይ ባለች ደርብነት ባላት ዋሻ ቀበሩ።'),
  ('e7ae14a8-0965-5e62-a520-fc9d93bb059b', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 18, 18, 'ብዙ ሰዎችም ወደ ግብፅ ተመለሱ፤ ከእነርሱም ጥቂት ሰዎች በኬብሮን ቀሩ፤ አባትህ አብራንም ከእነርሱ ጋር ቀረ።'),
  ('0b49ec90-2805-5e2d-ab3f-3e125cd19c4f', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 19, 19, 'የከነዓን ንጉሥ የግብፅን ንጉሥ ድል ነሣው።'),
  ('534f685e-4db5-5e94-a498-1225c56fb718', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 20, 20, 'የግብፅንም ሰዎች እንዲህ አላቸው፥ “የእስራኤል ልጆች ከእኛ እነሆ፥ ፈጽመው በዙ፤ ሳይበዙም እንጠበብባቸው፤ ጦርነትም ሳይመጣብን፥ እነርሱም ሳይወጉን በአገዛዝ መከራ እናጽናባቸው፤ ይህ ካልሆነ ግን እነርሱ ከጠላቶቻችን ጋር አንድ ሆነው ይወጉናል፤ ልቡናቸውና ፊታቸውም ወደ ከነዓን ነውና ከምድራችን ይወጣሉ።”'),
  ('004c80af-0d53-59bb-a6ec-ad8b4e34689b', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 21, 21, 'በሥራም መከራ ያጸኑባቸው ዘንድ፥ የሠራተኛ አለቆችን ሾመባቸው፤ አዘዙአቸውም። ለፈርዖንም ፊጦምና ራሚስ የሚባሉ ጽኑ አንባዎችን ሠሩ። በግብፅም ሀገር ቅጥሩንና የፈረሰውን ግንብ ሁሉ ሠሩ። በግፍም ይገዙአቸው ነበር። ነገር ግን ክፉ ነገር የሚያደርጉባቸውን ያህል እንደዚሁ ፈጽመው ይበዙ ነበር። የግብፅም ሰዎች የእስራኤልን ልጆች ይጸየፉአቸው ነበር።'),
  ('dd18981b-4f60-5e02-adf3-72c89df485b4', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 22, 22, 'በአርባ ሰባተኛው ኢዮቤልዩ በሰባተኛው ሱባዔ በሰባተኛው ዓመት አባትህ ከከነዓን መጣ፤ በአርባ ስምንተኛው ኢዮቤልዩ በአራተኛው ሱባዔ በስድስተኛው ዓመት ተወለድህ፤ ይኸውም በእስራኤል ልጆች ላይ መከራ የጸናበት ዘመን ነው።'),
  ('c7aefd66-5523-573d-a73f-f614758bccdc', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 23, 23, 'የግብፅ ንጉሥ ፈርዖንም የተወለደውን ወንድ ልጃቸውን ሁሉ ወደ ባሕር ይጥሉ ዘንድ በእነርሱ ላይ ትእዛዝን አዘዘ።'),
  ('0a7252a8-721d-521b-a8cd-42e5e1bcf489', '810f6e9f-2ad0-5f05-abc0-c067c1eb1a80', '3517a3fe-965d-5012-a205-fe0431e12486', 24, 24, 'አንተም እስክትወለድ ድረስ ሰባት ወር ልጆቻቸውን ሲጥሉ ኖሩ። እናትህም ሦስት ወር ሸሸገችህ። ለእርስዋም ነገሩአት። ሣጥንም አሠራችልህ፥ በሙጫና አደሮ ማርም ለበጠችው፥ በወንዙም ዳር በፊላ ሣር ውስጥ አኖረችው። በውስጡም ሰባት ቀን አኖረችህ፥ እናትህም በሌሊት እየመጣች ታጠባህ ነበር፥ እኅትህ ማርያምም በቀን ከአሞራዎች ትጠብቅህ ነበር።'),
  ('067be616-837a-53e4-ac04-e432a57964bd', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 1, 1, 'በዚያም ወራት የፈርዖን ልጅ ተርሙት በወንዝ ትታጠብ ዘንድ ወጣች። ስታለቅስም ቃልህን ሰምታ ያመጡህ ዘንድ ደንገጥሮችዋን አዘዘች። ወደ እርስዋም አመጡህ፤ ከሣጥንም አወጣችህ፤ ራራችልህም።'),
  ('3500c997-0097-54ec-a4d4-4922eea374b1', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 2, 2, 'እኅትህም፥ “ከዕብራውያት ወገን ይህን ሕፃን አጥብታ የምታሳድገው ሞግዚት ሄጄ ልጥራልሽ?” አለቻት። ሄዳም እናትህን ኢዮካብድን ጠራቻት፤ ደመወዝዋንም ሰጠቻት፤ አሳደገችህም።'),
  ('b570b4d8-40fe-52e3-a1f6-7bfe69ee98fc', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 3, 3, 'ከዚህም በኋላ ባደግህ ጊዜ ወደ ፈርዖን ቤት ወሰዱህ። ልጁም ሆንኸው። አባትህም አብራን መጽሐፍን አስተማረህ።'),
  ('fcf5a60e-90cd-5942-a8dc-dff864821a82', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 4, 4, 'ሦስቱንም ሱባዔ ከፈጸምህ በኋላ ወደ ቤተ መንግሥት አገባህ፥ ከቤተ መንግሥትም እስከምትወጣበት ወራት ድረስ ሦስት የዓመት ሱባዔ በቤተ መንግሥት ኖርህ። ከእስራኤል ልጆች ወገን የሚሆን ጓደኛህን ዕብራዊውንም ሲደበድበው ግብፃዊውን አየኸው፤ ገድለህም በአሸዋ ውስጥ ቀበርኸው።'),
  ('7269f0fc-96b6-5a37-ab5d-dbd67ca49067', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 5, 5, 'በሁለተኛውም ቀን ከእስራኤል ልጆች ወገን ሁለት ሰዎች ሲጣሉ አገኘህ። በደለኛውንም፥ “ወንድምህን ለምን ትመታዋለህ?” አልኸው። ፈጽሞም ተቈጣ፥ “በእኛ ላይ አለቃና ፈራጅ አድርጎ የሾመህ ማን ነው? ወይስ ግብፃዊውን እንደ ገደልኸው ትገድለኝ ዘንድ ትወዳለህን?” አለህ።'),
  ('b9286400-ff54-55c3-a063-cfe1115af3c0', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 6, 6, 'ከዚህም ነገር መገለጥ የተነሣ ፈርተህ ሸሸህ።'),
  ('8e219e3e-47a8-52d1-a6e7-00ac45e938a6', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 7, 7, 'በአርባ ዘጠነኛው ኢዮቤልዩ በሦስተኛው ሱባዔ በስድሰተኛው ዓመት ወደዚያ ሄድህ፤ ስድስት ሱባዔ ከአንድ ዓመትም ተቀመጥህ። በዳግመኛው ሱባዔም በሁለተኛው ዓመት ወደ ግብፅ ተመለስህ፤ ይኸውም ኀምሳ ኢዮቤልዩ ነው።'),
  ('7ee3a2ba-0277-57a6-ae6e-f7d4fd80bc15', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 8, 8, 'በደብረ ሲና የተናገረህን አንተ ታውቃለህ፤ ወደ ግብፅ በተመለስህ ጊዜ በጎዳና በዳስ በዓል ቀን ገዢው መስቴማ ከአንተ ጋር ምን ሊያደርግ ወደደ? በፍጹም ኀይሉ ይገድልህ ዘንድ አይደለምን?'),
  ('bb11a33f-df6a-5113-a463-a3f28d7fa042', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 9, 9, 'በግብፃውያንም በቀልንና ፍርድን ታደርግ ዘንድ እንደ ተላክህ ባየህ ጊዜ ግብፃውያንን ከእጅህ ያድናቸው ዘንድ የወደደ አይደለምን? ከእጁም አዳንሁህ፤ በግብፅም በፈርዖንና በቤተ ሰቡ ሁሉ ላይ፥ በባሪያዎቹና በሕዝቡም ላይ በእውነት ታደርግ ዘንድ በተላክህበት ተአምራትንና ድንቅን አደረግህ።'),
  ('7e66dfbb-4fcf-5f00-ad9a-b70598ce800c', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 10, 10, 'እግዚአብሔርም ስለ እስራኤል በእነርሱ ጽኑ በቀልን አደረገ። በደምና በጓጉንቸር፥ በትንኝና በውሻ ዝንብ፥ በክፉ ቍስልና በሚፈላ ደዌ ሥጋ ፈጽሞ አጠፋቸው።'),
  ('b3e43948-8cdd-5078-a940-e38f3fdbe9c2', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 11, 11, 'ከብቶቻቸውንም በሞትና በበረድ ድንጋይ አጠፋ፤ አዝመራቸውንም በዚህ ሁሉ አጠፋ። ከበረድ የቀረውንም ቀሪውን በሚበላ አንበጣ አጠፋ። በጨለማ፥ በሰውና በከብት በኵር፥ በጣዖቶቻቸውም ሁሉ እግዚአብሔር በቀልን አደረገ። በእሳትም አቃጠላቸው፤ ሳይደረግም ታደርግ ዘንድ ሁሉ በአንተ እጅ ተላከ።'),
  ('6c70417f-7fa0-58e0-a901-535bbafa1e53', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 12, 12, 'የግብፅንም ንጉሥ በአገልጋዮቹ ሁሉ ፊትና በሕዝቡ ፊት ትናገረው ነበርህ። ሁሉም በቃልህ ተደረገ። ታላላቆችና ክፉዎች ዐሥሩ መቅሠፍቶች ለእስራኤል በቀልን ትመልስለት ዘንድ በግብፅ ሀገር መጡ። እግዚአብሔርም ስለ እስራኤል ሁሉን አደረገ። በግፍ እንደ ገዙአቸው በእነዚያ ላይ በቀልን ይመልስ ዘንድ ከአብርሃም ጋር መሐላን እንደ ተማማለበት ፈቃዱ አደረገ።'),
  ('356bad00-f57b-5866-ab67-c8e205945fdb', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 13, 13, 'ገዢው መስቴማ በፊትህ ይከራከርህ ነበር፥ በፈርዖንም እጅ ይጥልህ ዘንድ ይወድ ነበር፥ የግብፅንም ሰዎች በምዋርታቸው ይረዳቸው ነበር። ይቃወምላቸውም ነበር። በፊትህም ክፉ ሥራ ይሠሩ ነበር። በፊትህም ክፉ ሥራን ይሠሩ ዘንድ ተውናቸው። ድኅነት ግን በእጃቸው ይደረግ ዘንድ አልፈቀድንላቸውም። እግዚአብሔርም በክፉ ቍስል አጠፋቸው፤ አንድ ተአምራትን ስንኳ ምንም ከማድረግ አሳጥተናቸዋልና መቃወም ተሳናቸው።'),
  ('92324ba3-4927-5e81-a759-aac1536b1307', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 14, 14, 'ግብፃውያንም በሠራዊቶቻቸው ሁሉ፥ በፈረሶቻቸውና በሰረገላዎቻቸው፥ በግብፅም ሠራዊት ሁሉ ብዛት ከአንተ በኋላ ይከተሉ ዘንድ እስኪበረታና ለግብፃውያን እስኪያሰማቸው ድረስ ደርሶ፥ ገዥ መስቴማ በተአምራትና በድንቅ ሁሉ አላፈረም።'),
  ('fc7cf7e3-cae5-5d34-a10f-4e4b5807275e', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 15, 15, 'እኔም በአንተና በግብፃውያን መካከል በእስራኤልም መካከል ቆምሁ። እስራኤልንም ከእጁና ከሠራዊቱ እጅ አዳንናቸው።'),
  ('44b864d1-70a7-5d3f-a67b-78fcf60e1290', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 16, 16, 'እግዚአብሔርም እንደ ደረቅ ምድር በባሕር መካከል አሻገራቸው። እስራኤልንም ይከተሉ ዘንድ ያወጣቸውን ወገኖች ሁሉ የግብፅ ሰዎች የእስራኤልን ልጆች በባሕር እንደ ጣሉ፥ አምላካችን እግዚአብሔር በባሕር መካከል ከእስራኤል ልጆች በታች በወንዙ ጥልቅ ጣላቸው። ዐሥር እልፍ ጊዜ በቀልን ተበቀላቸው። ከእስራኤል ልጆች ወገን በፈሳሽ መካከል ስለ ጣሉት ስለሚጠባ አንድ ሕፃን ፋንታም በሦስት ወገን የሚመክቱ ሺህ አርበኞችን ተበቀላቸው።'),
  ('3b974d3f-160f-5797-a5a2-8799a44d435c', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 17, 17, 'በዐሥራ አራተኛውና በዐሥራ አምስተኛው፥ በዐሥራ ስድስተኛውና በዐሥራ ሰባተኛው፥ በዐሥራ ስምንተኛውም ቀን ገዢው መስቴማ እንዳይጣላቸው ከእስራኤል ልጆች በኋላ ታስሮ ተግዞ ነበር።'),
  ('7863a1d6-0749-5155-a042-246c53177b3d', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 18, 18, 'በዐሥራ ዘጠነኛው ቀን ግን የግብጽን ሰዎች ይረዱአቸው ዘንድ፥ የእስራኤልንም ልጆች ይከተሉ ዘንድ አሰናበትናቸው። ልቡናቸውንም አጸና፥ አበረታቸውም፤ ግብፃውያንንም ያጠፋቸው ዘንድ፥ በባሕርም መካከል ይጥላቸው ዘንድ በአምላካችን በእግዚአብሔር ዘንድ ታሰበ።'),
  ('03929079-3baa-5326-ac7f-fcb1c12f18b3', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 19, 19, 'ከግብፅ ሰዎች ልብስንና ገንዘብን፥ የብሩን ዕቃና፥ የወርቁን ዕቃ፥ የናሱንም ዕቃ በሚጠይቁበት ቀን የእስራኤልን ልጆች እንዳይጣላቸው፥ በግፍም ስለ ገዙአቸው ፋንታ ይማርኩአቸው ዘንድ በዐሥራ አራተኛው ቀን አሰርነው። የእስራኤልንም ልጆች ከግብፅ ባዶአቸውን አላወጣናቸውም።'),
  ('daffc78e-677f-594d-a84d-9a01cace8505', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 20, 20, 'መጀመሪያው ወር በባተ በዐሥራ አራተኛው ቀን ገና ሳይመሽ ትሠዋው ዘንድ፥ በዐሥራ አምስተኛውም ቀን ማታ ፀሐይ ከሚገባበት ጊዜ ጀምሮ በሌሊት ይበሉት ዘንድ እግዚአብሔር ስለ ፋሲካው ያዘዘህን ትእዛዝ ዐስብ፤ ይህችም ሌሊት የበዓል መጀመሪያ ናት፤ የፋሲካም መጀመሪያ ናት።'),
  ('a6dfc2ea-4100-5f29-a57a-ce67b2c7046f', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 21, 21, 'እናንተም በግብፅ የፋሲካ በዓል አድርጋችሁ ትበሉ ዘንድ ትቀመጣላችሁ፤ የመስቴማ ሠራዊትም ሁሉ በግብፅ ሀገር ከፈርዖን በኵር ጀምሮ ተማርካ በወፍጮ ሥር እሰከምታገለግል ባሪያ በኵር ድረስ የበኵር ልጁን ይገድል ዘንድ፤ ከብቱንም ሁሉ ያጠፋ ዘንድ ተላከ።'),
  ('1c34f251-a587-5934-a66c-955bae729f47', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 22, 22, 'በበሩ የደም ምልክት አለና በቤት ያሉ ሰዎች ሁሉ ይድኑ ዘንድ ሠራዊቱ አልፈው ይሄዳሉ እንጂ ዓመት የሆነውን የበግ ደም በበሩ ወዳዩበት ቤት ለመግደል እንዳይገቡ እግዚአብሔር የሰጣቸው ምልክት ይህች ናት።'),
  ('96aefa55-4387-5ac4-a18c-c7b289008bb1', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 23, 23, 'የእግዚአብሔርም ሠራዊት ሁሉ እግዚአብሔር እንዳዘዛቸው መጠን ሁሉን አደረጉ። ከእስራኤልም ልጆች ሁሉ አልፈው ሄዱ። ከከብት ጀምሮ እስከ ሰው ድረስ፥ እስከ ውሻም ድረስ ከእነርሱ ሰውን ሁሉ ለማጥፋት መቅሠፍት ወደ እስራኤል አልገባም።'),
  ('9a5232cb-df40-5a70-a740-0851e6ccb774', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 24, 24, 'መቅሠፍቱም በግብፅ እጅግ ጽኑ ሆነ፤ በግብፅም በድን፥ ልቅሶና ጩኸት በውስጡ የሌለበት ቤት አልነበረም፤ እስራኤል ሁሉ ግን ተቀምጦ የፋሲካውን ሥጋ እየበላና ወይኑን እየጠጣ የአባቶቹን አምላክ እግዚአብሔርን ያመሰግንና ይባርክ ነበር። ከጽኑ አገዛዝና ክፉ ከምትሆን ከግብፅም ለመውጣት ተዘጋጅቶ ነበር።'),
  ('3ea72c0d-a3e7-5712-a930-f1e7e9172269', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 25, 25, 'አንተም ባለ በዘመንህ ሁሉ ይህችን ቀን ዐስብ፤ ከአንዱ ዘመን እስከ አንዱ ዘመን በሕይወት በኖርህበት ዘመን ሁሉ እንደ ሥርዐቱ ሁሉ በዕለቱ በዓመት አንድ ጊዜ አድርጋት።'),
  ('a03fde19-a31b-5858-a3d6-6960fd9c54a3', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 26, 26, 'የዘለዓለም ሥርዐት ነውና ከቀን ቀንን፥ ከወርም ወርን አታስተላልፍ። በየዓመቱ ሁሉ ከዓመት አንድ ቀን በየትውልዳቸው ሁሉ ዕለቱን በዓል ያደርጉት ዘንድ በእስራኤል ልጆች ላይ ሥርዐት እንደ ሆነ በሰማይ ጽላት ተጽፏል። የዘለዓለም ሥርዐት ነውና የተወሰነ ዘመንም የለውም።'),
  ('839fa019-f689-58b5-a1b5-26498041f7bb', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 27, 27, 'ሰው ንጹሕ ሆኖ ሳለ በጊዜው በዕለቱ ያደርገው ዘንድ በዓሉ በሚከበርባት ቀን እግዚአብሔር ወድዶ የሚቀበለውን ቍርባን ለማቅረብ፥ በእግዚአብሔርም ፊት ለመብላትና ለመጠጣት ባይመጣ የእግዚአብሔርን ቍርባን በጊዜው አላቀረበምና ንጹሕ የሆነው፥ ሀገሩም ቅርብ የሆነው ያ ሰው ይጥፋ። ያም ሰው ለራሱ የኀጢአቱን ፍዳ ይቀበላል። ቀኑ ሁለቱ እጅ ለብርሃን፥ ሦስቱ እጅ ለጨለማ ተሰጥቶአልና፥ መጀመሪያው ወር በባተ በዐሥራ አራተኛው ቀን በምሽቱ መካከል ከቀኑ ሦስተኛ ክፍል ጀምሮ እስከ ሌሊቱ ሦስተኛ ክፍል ድረስ የእስራኤል ልጆች መጥተው ከቀኑ በጊዜው በዓል ያድርጉ።'),
  ('4ec57431-c330-582f-a21e-2d6708f11a39', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 28, 28, 'በምሽቶች መካከል በዓል ታደርግ ዘንድ እግዚአብሔር ያዘዘው ሥርዐት ይህ ነው። የሚሠዋበትም በምሽቱ ወሰን ጊዜ ይሁን እንጂ በብርሃኑ ጊዜ ሁሉ አይሁን። እስከ ሌሊቱ ማግሥት ድረስ ማታ ጊዜ ይብሉት። ከሌሊቱ ማግሥት፥ ከዚያም በኋላ የተረፈውን ሥጋ ሁሉ በእሳት ያቃጥሉት።'),
  ('507d64f7-5faa-505f-a770-b08acddf5514', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 29, 29, 'በእሳት ጠብሰው አብስለው ይብሉት እንጂ ቅቅሉንና ብርንዶውን አይብሉት። ከእግሩና ከሆድ ዕቃውም ጋር ራሱን በማስተንተን በእሳት ይጥበሱት። ከእስራኤልም ልጆች ምንም የሚሰበር ሰውነት የለምና ከእርሱ የሚሰበር አጥንት አይኑር።'),
  ('b0a70b6e-56b9-56d7-a6ad-d02e799a0a11', '44c770a8-7e05-5b1e-ae01-8ff8dd10b8e3', 'f67eed97-1e32-509c-ae2b-9fb198a96ff0', 30, 30, 'ስለዚህ ነገር በጊዜው ጊዜ ፋሲካን ያደርጉ ዘንድ እግዚአብሔር የእስራኤልን ልጆች አዘዛቸው። ከእርሱም ምንም አጥንትን መስበር አይኑር። የበዓል ቀን ናትና፥ የታዘዘችም ቀን ናትና፥ በዓል የሚደረግባትም ቀን ስለ ሆነች ከእርስዋ ከቀን ወደ ቀን፥ ከወርም ወደ ወር መተላለፍ የለምና።'),
  ('d1f94931-80e2-5067-ac30-2a30531dc480', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 1, 1, 'አንተም የእስራኤልን ልጆች በዘመናቸው፥ በየዓመቱ ሁሉ በዓመት አንድ ቀን በጊዜው ፋሲካን ያደርጉ ዘንድ እዘዛቸው።'),
  ('0aa94ef2-ec9f-5a6d-acb2-ce33fdf5aa34', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 2, 2, 'የሚወደደው መታሰቢያ ከእግዚአብሔር ፊት ይመጣል። በሁሉ እንደ ታዘዘ በጊዜው በዓልን ባደረጉ ጊዜ በዚያ ዘመን ፈጽሞ ለማጥፋት መቅሠፍት አይመጣባቸውም።'),
  ('3b120514-70e0-5e79-ac89-39f265b3c435', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 3, 3, 'ከእንግዲህም ወዲህ መበላቱ ከእግዚአብሔር ቤተ መቅደስ ውጭ አይሁን፥ ነገር ግን በእግዚአብሔር ቤተ መቅደስ ትይዩና በእስራኤል ወገኖች ሁሉ ፊት በጊዜው ያድርጉት። የመጣዉ ሰው ሁሉ ከሃያ ዐመት ጀምሮ ከዚያም በላይ ያለ በአምላካችሁ ቤተ መቅደስ በእግዚአብሔር ፊት በዕለቱ ይብላው፥ በእግዚአብሔር ቤተ መቅደስ ይበሉት ዘንድ እንደዚህ ተጽፎአልና፥ ተሠርቶአልምና፤'),
  ('e2a6a442-ac7a-505f-acfd-cf7fceab3bb2', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 4, 4, 'የእስራኤል ልጆች ይዘዋት ወደሚኖሩ ወደ ከነዓን ከገቡ በኋላ፥ እግዚአብሔር የሚመሰገንበት ቤተ መቅደስ በኢየሩሳሌም እስኪሠራ ድረስ ሠራዊቶቻቸው ከያዙአቸው ሀገሮች በአንዱ ቦታ በምድር መካከል የእግዚአብሔርን ድንኳን ይተክላሉ።'),
  ('afb7893c-a34d-5626-ad33-e83cca86117c', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 5, 5, 'መጥተውም በእግዚአብሔር ድንኳን መካከል የፋሲካን በዓል የሚያደርጉ ይሁኑ። በዓመት በዓመትም በእግዚአብሔር ፊት ይረዱት።'),
  ('a9ba317d-640b-5866-aace-b34bec1ec405', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 6, 6, 'በወረሱአት ሀገር ላይ በእግዚአብሔር ስም ቤተ መቅደስ በተሠራባት ቀን ወደዚያ ሄደው ፀሐይ ሲገባ ከቀኑ በሦስተኛው ክፍል በማታ ጊዜ የፋሲካውን በግ ይረዱ፤ ደሙን በመሠዊያው ዙሪያ ይርጩት፤ ስቡንም በመሠዊያው ላይ ባለ በእሳቱ ላይ ያኑሩት። ሥጋውንም በእግዚአብሔር ፊት በቤተ መቅደስ ዐደባባይ በእሳት ጠብሰው ይብሉት።'),
  ('b594b639-591c-53c9-a8d6-5152fc5b6086', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 7, 7, 'በእግዚአብሔር ድንኳን ነው እንጂ፥ ያም ባይሆን ስሙ በሚጠራበት በቤቱ ፊት ነው እንጂ በከተማቸውና በአውራጃቸው ሁሉ ፋሲካን ማድረግ አይችሉም፤ እግዚአብሔርንም ከመከተል ወጥተው አይሳቱ።'),
  ('7bb3c856-b6bc-57a5-a2f8-8bf40d7b492b', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 8, 8, 'አንተም ሙሴ፥ ዓመቱን በዓመት፥ ቀኑንም በቀን ታደርገው ዘንድ እንደ ታዘዘልህ የፋሲካውን ሥርዐት ይጠብቁ ዘንድ፥ በዐሉን ሊያደርጉ ሰባት ቀን ቂጣ ይበሉ ዘንድ፥ ከግብፅ በወጣችሁ ጊዜ ባሕሩን ተሻግራችሁ ወደ ሱር ምድረ በዳ እስክትደርሱ ድረስ ይህችን በዓል በመቸኮል አድርጋችኋታልና በባሕርም ዳርቻ ላይ ፈጽማችኋታልና መሥዋዕት በሚሠዋባቸው በእነዚህ በሰባቱ ቀኖች በአምላካችሁ መሠዊያ ላይ ዕለት ዕለት ቍርባኑን ወደ እግዚአብሔር ያቀርቡ ዘንድ የእስራኤልን ልጆች እዘዛቸው።'),
  ('929e5f88-0d85-5a12-ab13-fb6fb79589c8', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 9, 9, 'ከዚህም ሥርዐት በኋላ በሱባዔ የሚቈጠረውን ቀን በሲና ምድረ በዳ ነገርሁህ። ይህችውም ምድረ በዳ በሲናና በኤሎም መካከል ያለች ናት። የምድር ሰንበታትንም በደብረ ሲና ነገርሁህ። በዓመቶች ሱባዔ ውስጥ በኢዮቤልዩ የሚቈጠሩ ዓመቶችንም ነገርሁህ። ዓመቱን ግን ወደምትይዙአት ምድር እስክትገቡ ድረስ አልነገርንህም። በእርስዋም ላይ በመኖራቸው ምድር ዕረፍትን ታድርጋለች። የኢዮቤልዩንም ዓመት ያውቃሉ።'),
  ('722d1ee4-a942-554b-a72a-3aabd9394920', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 10, 10, 'ስለዚህ ነገር በዓመቶች የሚቈጠረውን ሱባዔ ሠራሁልህ። አዳም ከተፈጠረ ጀምሮ እስከዚህች ቀን ድረስ ያለው ዘመን አርባ ዘጠኝ ኢዮቤልዮታትና አንድ ሱባዔ ከሁለት ዓመት ነው። በምዕራብ በኩል ዮርዳኖስን ተሻግረው ወደ ምድረ ርስት ማዶ እስኪገቡ ድረስ የእግዚአብሔርን ትእዛዝ ለማወቅ ገና አርባ ዘመን ቀርቶአል። እስራኤል ከዝሙት፥ ከበደል፥ ከርኵሰት፥ ከመተዳደፍ፥ ከኀጢአት፥ ከስሕተትም ሁሉ እስኪነጻ ድረስ ብዙ ኢዮቤልዮታት ያልፋሉ።'),
  ('eb203d76-e495-5087-a2c4-fd7a8f552a06', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 11, 11, 'በምድርዋም ሁሉ ተዘልሎ ይኖራል፤ ከእንግዲህም ለእርሱ ማንም ባላጋራ አይኖርም። ምንም ክፉ ነገር አይኖርም። ምድርም ከዚያች ቀን ጀምሮ እስከ ዘመኑ ፍጻሜ ድረስ ትነጻለች።'),
  ('1978b2af-41d4-5c24-aeae-fa224e54c39e', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 12, 12, 'የሰንበታትንም ሥርዐት እነሆ፥ ጻፍሁልህ። የሥርዐቱንም ፍርድ ጻፍሁልህ። በስድስቱም ቀኖች ሥራህን ሥራ።'),
  ('5721268d-4a15-552d-ac20-ea7f1850e253', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 13, 13, 'ሰባተኛዪቱ ቀን ግን አምላካችሁ እግዚአብሔር ከመፍጠር ያረፈባት ቀን ናትና፥ እናንተና ልጆቻችሁ፥ ወንዶች ባሪያዎቻችሁና ሴቶች ባሪያዎቻችሁም፥ ከብቶቻችሁም ሁሉ፥ በአንተ ዘንድ የሚኖር መጻተኛም ቢሆን ሥራውን ሁሉ አትሥሩባት። በዚያችም ቀን ማንኛውንም ሥራ የሚሠራባት ሰው ይሙት። ይህችን ቀን የሚሽራት ሰው ሁሉ፥ ከሚስቱም ጋር የሚገናኝባት ሰው፥ ገሥግሦም ሄዶ ሥራን ይሠራ ዘንድ ነገርን የሚነጋገርባት ሰው ሞትን ይሙት።'),
  ('80576226-3560-593a-a2c9-9c51bfdd4eea', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 14, 14, 'የሚሸጥባትና የሚለውጥባትም ሰው ሁሉ፥ ውኃንም የሚቀዳ ሰው፥ በስድስተኛዪቱም ቀን ያላዘጋጀ፥ ከድንኳኑ፥ ወይም ከቤቱ ያወጣ ዘንድ የሚሸከመውን ሸክም ሁሉ የሚያነሣ ሰው ይሙት።'),
  ('48c6d578-308a-5372-ae5b-b03fecf03746', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 15, 15, 'በስድስተኛው ቀን ያዘጋጃችሁትን በልታችሁና ጠጥታችሁ ለማክበር በዚህች ቀን ከሥራው ሁሉ ዕረፉባት እንጂ፥ በዓል የምታደርጉባትን ቀን የሰጣችሁን አምላካችሁን እግዚአብሔርንም አመስግኑባት እንጂ በሰንበት ቀን ምንም ሥራን አትሥሩ። የተቀደሰች ቀን ናት፤ በዘመናቸው በቀኑ ሁሉ ይህች ቀን ለእስራኤል ሁሉ የተቀደሰች የመንግሥት ቀን ናት።'),
  ('2622a781-ee87-5795-abac-12543ac11a48', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 16, 16, 'በዚህች የበዓል ቀን በልተውና ጠጥተው ሊጠግቡባት፥ በእግዚአብሔር ፊት በየቀኑና በየሱባዔው ዕጣንን ከማጠን፥ ቍርባንንም ከማቅረብ፥ መሥዋዕትንም ከመሠዋት በቀር ሰው ከሚሠራው ሥራ ሁሉ ሊያርፍባት እግዚአብሔር ለእስራኤል የሰጠው ታላቅ ክብር ናትና አክብሩአት።'),
  ('e429ef6d-92c5-5ece-ab3e-bfa7b382638e', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 17, 17, 'በአምላካችሁ በእግዚአብሔር ቤተ መቅደስ በሰንበት ቀን ይህ ሥራ ብቻ ይሠራ። የእስራኤልን ልጆች ኀጢአት ያስተሰርዩ ዘንድ፥ በእግዚአብሔር ፊት ተቀባይነት ያለው መባን ለመታሰቢያ ዕለት ዕለት ያቅርቡ። እንደ ታዘዘም ለዘለዓለሙ ዕለት ዕለት ይቀበላቸዋል።'),
  ('6a2a22e4-02d6-5922-ae44-cd049c10516f', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 18, 18, 'ሥራን የሚሠራባት ሰው ሁሉ፥ መንገድንም የሚሄድባት ሰው፥ የሚያርስባትና የሚቈፍርባትም ሰው፥ በቤቱም ቢሆን፥ በሁሉም ቦታ ቢሆን፥ እሳት የሚያነድባት ሰው፥ በእንስሳውም ላይ የሚጭን ሰው፥ በመርከብም በባሕር የሚሄድ ሰው፥'),
  ('5e8e624d-27b2-5ffe-a9ff-312e78a02eb2', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 19, 19, 'ማናቸውንም መትቶ የሚገድል ሰው ሁሉ፥ እንስሳንና ወፍንም የሚያርድባት ሰው፥ አውሬም ቢሆን ወፍም ቢሆን ዓሣም ቢሆን የሚያጠምድ ሰው፥ የሚጾምባትም ሰው፥ በሰንበት ቀን ጠብ የሚያነሣ፥ ከዚህ ሥርዐትም ወጥቶ ይህን ሁሉ ሥራ በሰንበት ቀን የሚሠራ ሰው ይሙት።'),
  ('daa7e823-15e7-52a1-a733-0b96c2957cc7', 'c3823266-913b-5063-a13c-04972172b409', '30f63548-a952-5dbc-a684-769f0936b84a', 20, 20, 'የበዓሉንና የቀኑን ሥርዐት በየዘመኑ አከፋፈል እጽፍልህ ዘንድ በእጄ በሰጠኝ በሰማይ ጽላት እንደ ተጻፈ፥ ምድር ዕረፍት እንድታደርግ እንደ ታዘዘ፥ የእስራኤል ልጆች በዓልን የሚያደርጉ ይሆኑ ዘንድ ሥራን የሚሠራባት ሰው ሁሉ ይሙት።'),
  ('128acf58-7514-5518-a171-989a39b8c01d', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 1, 1, 'ክፉዎችንና ዝንጉዎችን ለማራቅ፥ በመከራ ቀን ይገኙ ዘንድ ያላቸውን ምርጦችንና ጻድቃንን እንደ ባረከ የሚናገረው የሄኖክ ቃለ በረከት፤'),
  ('56897538-f487-509f-af54-c1cca5902068', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 2, 2, 'ሄኖክም ተናገረ፤ እንዲህም አለ- “ከእግዚአብሔር ዘንድ የሆነ ጻድቅ ሰው ዐይኖቹ ተገልጠው ሳለ- መላእክት ያሳዩኝን በሰማያት ያለ ቅዱስ ራእይ ያይ ነበር። ከእነርሱም ሁሉን ሰማሁ። እኔም የማየውን ዐወቅሁ።'),
  ('2487cc33-c0cd-5e05-a731-baf9341fd0ef', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 3, 3, 'ለዚህም ትውልድ አይደለም። ነገር ግን ለሚመጣው ለሩቁ ትውልድ ነው።'),
  ('38433964-a7b6-5c57-a977-651c51583f81', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 4, 4, 'ስለ ተመረጡት ተናገርሁ። ስለ እነርሱም በምሳሌ እንዲህ አልሁ። ቅዱሱና ገናናው የዓለም ፈጣሪ ከማደሪያው ይወጣል።'),
  ('272628b2-ca10-5801-ac5d-f1650eccebe5', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 5, 5, 'ከዚያም በደብረ ሲና ተራራ ላይ ይቆማል፤ በሰፈሩ ይታያል፤ በኀይሉም ጽናት ከሰማይ ይገለጣል፤ ሁሉም ይፈራል፤ መላእክትም ይነዋወጣሉ፤ እስከ ምድር ዳርቻም ድረስ ፍርሀትና ታላቅ እንቅጥቅጥ ይይዛቸዋል። ረጃጅሞች ተራሮች ይደነግጣሉ። ረጃጅም ኮረብታዎችም ዝቅ ይላሉ። ከትኩሳቱም የተነሣ እንደ አደሮ ማር ይቀልጣሉ። ምድርም ትሰጥማለች። በምድርም ላይ ያለ ሁሉ ይጠፋል።'),
  ('b857d158-3d4d-529d-ae85-130fa75b53e6', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 6, 6, 'ፍርድ በሁሉም ላይ በጻድቃንም ሁሉ ላይ ይሆናል።'),
  ('3a21604d-fac1-5456-aee5-4312b716f786', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 7, 7, 'ለጻድቃን ግን ሰላምን ያደርግላቸዋል፤ የተመረጡትንም ይጠብቃቸዋል፤ ለእነርሱም ይቅርታ ይደረግላቸዋል።'),
  ('43905c47-e75c-5232-af45-0da82b02a1ed', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 8, 8, 'ሁሉም የአምላክ ገንዘቦች ይሆናሉ። ይከናወናሉ፤ ይባረካሉ፤ የአምላክም ብርሃን ይበራላቸዋል።'),
  ('29320f29-9c0b-54d3-a6d8-a8fc6f818654', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 9, 9, 'ፍርድን ያደርግላቸው ዘንድ እነሆ፥ ከብዙ ቅዱሳን ጋር ይመጣል፤ ዝንጉዎችንም ያጠፋቸዋል፤ ኃጥኣንና ዝንጉዎች ፈጽመው በእርሱ ላይ ስለ አደረጉት ሁሉ ሥጋዊዉን ሁሉ ይወቅሳል።'),
  ('428dfeda-c646-534b-a203-28676d7b95ae', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 10, 10, 'በሰማይ የሚኖሩ ብርሃናት መንገዳቸውን እንዴት እንደማይለውጡ፥ ሁሉም እንደሚወጣና እንደሚገባ፥ ሁሉም በየዘመኑ እንደ ተሠራ፥ ከሥርዐታቸውም እንደማይተላለፉ በሰማይ ያለውን ሥራ ሁሉ ተረዱ።'),
  ('8a1eb5b3-293d-5eeb-a26f-c2c05fa54c1c', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 11, 11, 'ምድርን እይዋት፥ ከመጀመሪያው ጀምሮ እስከ መጨረሻው ድረስ በእርሷ ላይ ከሚሠራው ሥራ የተነሣ የሚታይ የአምላክ ሥራው ሁሉ እንደማይለወጥ አስተውሉ።'),
  ('333ce326-51a3-5f21-a8ff-fec695881183', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 12, 12, 'በጋውን፥ ክረምቱንም እዩት፤ ምድር ሁሉ ውኃን እንደ ተመላች፥ ደመናውና ጤዛውም፥ ዝናቡም በእርሷ ላይ እንደሚያርፉባት ተመልከቱ።'),
  ('056a455b-4a00-5c36-ad7b-e875a770b2e7', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 13, 13, 'ከአረጀው ጀምሮ አዲሱ እስከሚመጣ ድረስ ለሁለትና ለሦስት ዓመት ከሚቈዩትና ከማይረግፉት ከዐሥራ አራት ዛፎች በቀር ዛፎች ሁሉ ደርቀው፥ ቅጠሎቻቸውም ሁሉ ረግፈው እንዴት እንደሚታዩ ተረዱ፤ እዩም።'),
  ('76a239fb-0356-55a2-a782-df8610b4ce20', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 14, 14, 'ዳግመኛም ፀሐይ በምድር ላይ አስቀድሞ እንደሚጸና የበጋውን ወራት ተረዱ።'),
  ('e63f23fc-8b9b-5a97-aba5-d35e237b5931', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 15, 15, 'እናንተ ግን ስለ ፀሐይ ዋዕይ ጥላና መጠለያ ትፈልጋላችሁ፤ ምድርም ከሐሩሩ ትኩሳት የተነሣ ትቃጠላለች።'),
  ('66648450-0c61-5689-a6a9-fa2620320e8f', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 16, 16, 'እናንተ ግን ስለ ዋዕይዋ ምድርንና ድንጋይዋን መርገጥ አትችሉም።'),
  ('cc1afa72-d90a-5e77-acfa-9ae49a0d778a', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 17, 17, 'ዛፎች በቅጠል ልምላሜ እንዴት እንደሚሸፈኑና እንደሚያፈሩ ተረዱ።'),
  ('82a9fb29-b8d4-5fed-af16-fe59a4277d1e', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 18, 18, 'ስለ ሁሉም አስተውሉ፤ ለዘለዓለሙ ሕያው ሆኖ የሚኖር እርሱ እነዚህን ሁሉ እንደ ፈጠረላችሁም ዕወቁ።'),
  ('ab25e6fc-fccf-5c98-aae0-69835d04a3d8', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 19, 19, 'በየዓመቱ የሚሆነው ሥራውም በፊቱ ነው፥ ፍጥረቱም ሁሉ ለእርሱ ይገዛሉ። አይለወጡምም፥ ነገር ግን አምላክ እንደ ሠራው ሁሉ እንዲህ ይደረጋል።'),
  ('6d0662df-6e35-543e-a442-003e47b92c38', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 20, 20, 'ባሕሮችና ፈሳሾችም አንድ ሆነው ሥራቸውን እንዴት እንደሚፈጽሙ እዩ።'),
  ('6d10fcf8-e16d-52d7-aa9d-4fabf3a62393', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 21, 21, 'እናንተ ግን አልታገሣችሁም፤ የጌታንም ትእዛዝ አላደረጋችሁም። ነገር ግን ተላልፋችሁ በረከሰች አፋችሁ በገናናነቱ ላይ ታላላቅና የጸኑ ቃላትን አማችሁት። እናንተ ልበ ድንጋዮች ሰላም አትሆንላችሁም።'),
  ('c090e6e8-7b2b-54d6-a77c-b6cb49001753', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 22, 22, 'ስለዚህም እናንተ ዘመናችሁን ትረግማላችሁ፤ የሕይወት ዘመናችሁንም ታጣላችሁ፤ የዘለዓለም መርገምም ይበዛል። ይቅርታም አይሆንላችሁም።'),
  ('4e7e6f13-6594-519a-a4b7-da2cafee62e4', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 23, 23, 'በዚያም ወራት በዘለዓለም ርግማን ለጻድቃን ሁሉ ሰላማችሁን'),
  ('b4faeddf-32a6-5e72-aeb9-84f93aa84b68', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 24, 24, 'ለተመረጡ ግን ብርሃን፥ ፍቅር፥'),
  ('a1f985c7-8d21-5cb6-adb9-ca9a22f68b3b', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 25, 25, 'እነርሱም ምድርን ይወርሷታል። ለእናንተ ለዝንጉዎች ግን ርግማን ይሆንባችኋል።'),
  ('a0ef89bc-a587-5d54-ab88-d66c514b55d5', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 26, 26, 'ያንጊዜም ለተመረጡት ሰዎች ጥበብ ይሰጣቸዋል፤ እነርሱም ሁሉ በሕይወት ይኖራሉ፤ በመዘንጋትም ቢሆን ወይም በትዕቢት ዳግመኛ አይበድሉም፤ ነገር ግን ጥበብ ያላቸው ለእርሱ ይገዛሉ።'),
  ('905ecb96-a0fc-565c-a1cb-72e20fffa36a', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 27, 27, 'ዳግመኛም አይበድሉም፤ በሕይወት ዘመናቸውም ሁሉ አይፈረድባቸውም። የሕይወት ዘመናቸውን ቍጥር ይፈጽማሉ እንጂ በመቅሠፍትና በመዓት አይሞቱም።'),
  ('08cf136d-cdbe-5fee-a803-caa5884bef12', 'db1666bb-93f0-5072-a071-72404e30aa17', '14245e2f-6115-5ebb-a28e-0000ac0b8f4f', 28, 28, 'ሕይወታቸውም በሰላም ይበዛል። የደስታቸው ዓመታትም በሐሤትና በዘለዓለም ሰላም፥ በሕይወታቸው ዘመን ሁሉ ይበዛሉ።'),
  ('818862b7-0b13-5434-adfc-a8bc241ef18f', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 1, 1, 'የሰው ልጆች ከበዙ በኋላ እንዲህ ሆነ።'),
  ('23eff96c-ca71-5d0e-a470-54f5b8649c5e', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 2, 2, 'በእነዚያ ወራት መልከ መልካሞችና ደመ ግቡዎች ሴቶች ልጆች ተወለዱላቸው። የሰማይ ልጆች መላእክትም'),
  ('a973d662-e937-5cb0-ad1d-88e4bee75885', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 3, 3, 'እርስ በርሳቸውም- “ኑ ለእኛ ከሰው'),
  ('d3f0a596-e80d-57ce-af30-e1dad6f1a85a', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 4, 4, 'አለቃቸው ስማዝያ- “እኔስ ይህ ሥራ ይሠራ ዘንድ ምናልባት አትወድዱ እንደ ሆነ እፈራለሁ። የዚህችም ታላቅ ኀጢኣት ፍዳ ተቀባይ እኔ ብቻ እሆናለሁ” አላቸው።'),
  ('c48b6f71-0652-5782-acc4-b01df2ab82e7', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 5, 5, '“ይችን ምክር እንዳንለውጣት፥ ይችንም ምክር ቁም ነገር እንድናደርጋት ሁላችን መሐላ እንማማል፤ እርስ በርሳችንም እንወጋገዝ” ብለው ሁሉም መለሱለት።'),
  ('7f52d7b4-8971-552b-a5b1-ae3a9e0d85e8', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 6, 6, 'ያንጊዜም ሁሉም አንድ ሆነው ማሉ፤ እርስ በርሳቸውም በነገሩ ተወጋገዙ፤ ሁሉም ሁለት መቶ ሆኑ።'),
  ('93867aff-dcf1-563c-a8fc-a139d25ffaeb', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 7, 7, 'አርዲስ ወደሚባል ቦታም ወረዱ፤ ይኸውም የኤርሞን ተራራ ራስ ነው። እርስ በርሳቸው ተወጋግዘው ምለውበታልና የኤርሞን ተራራ ብለው ጠሩት።'),
  ('29b36410-3fa5-587d-aa4f-3f8bee2c2e53', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 8, 8, 'የአለቆቻቸውም ስሞች ይህ ነው፤ አለቃቸው ስማዝያ፥ ዑራኪ፥ በራምኤል፥ ኮከቢኤል፥ ጣምኤል፥ ራሙኤል፥ ዳንኤል፥ ኢዜቂኤል፥ ሱሩቃያል፥ አሣኤል፥ አርማሮስ፥ በጥርኤል፥ አናንኤል፥ ዘቄቤ፥ ሳምሳፒኤል፥ ሰርትኤል፥ ጡሩኤል፥ ዮምያኤል፥ አራዝያል፤ የሁለቱ መቶ መላእክት አለቆች እኒህ ናቸው፤ ሌሎቹም ሁሉ ከእነሱ ጋር ነበሩ።'),
  ('1b6c31e6-0f04-59e0-a1ab-16e43e5eaebb', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 9, 9, 'ለራሳቸውም ሚስቶችን አገቡ፤ ሁሉም ለየራሱ አንድ አንድዋን መረጠ።'),
  ('a0548ba2-d0bc-578d-a9a3-c46b4311ee78', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 10, 10, 'ወደ እነርሱም ይገቡ ዘንድ ጀመሩ፤ ከእነርሱም ጋር አንድ ሆኑ።'),
  ('c9365ae8-713d-5a42-a544-25da15f7b0da', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 11, 11, 'ሟርትንና ምታት ማሳየትን አስተማሯቸው። ሥር መማስንና ቅጠል መበጠስንም አመለከትWaቸው።'),
  ('65c726ea-a711-514a-ae1f-0c146f3e6df0', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 12, 12, 'እነርሱም ፀንሰው ረጃጅሞች ረዓይትን ወለዱ። ቁመታቸው ሦስት ሦስት ሺህ ክንድ ነበር።'),
  ('47c2f030-6eb9-532b-a503-3d34bfc77e46', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 13, 13, 'እነዚህም ሰዎች እነርሱን መመገብ እስኪሳናቸው ድረስ ሰው የደከመበትን ሁሉ በሉ።'),
  ('acd28933-04b0-570f-a03e-d3bbe6e6a64f', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 14, 14, 'ረዓይትም ሰዎችን ይበሏቸው ዘንድ ተመለሱባቸው።'),
  ('120d251b-ffeb-54d4-a964-1abd0706e66b', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 15, 15, 'በወፎችና በአራዊት፥ በሚንቀሳቀሱና በዓሣዎችም ይበድሉ ዘንድ ጀመሩ።'),
  ('0a3be3d8-349e-59fd-ae2a-e7832e728c8d', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 16, 16, 'እርስ በርሳቸውም ሥጋቸውን ተባሉ፤ ከእርሷም ደምን ጠጡ።'),
  ('e734967f-ade8-513a-a2a1-b7ed160e0768', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 17, 17, 'ያንጊዜም ምድር ዐመፀኞችን ከሰሰቻቸው።'),
  ('22f89d9f-8968-5683-aa90-9ce2b4c27e72', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 18, 18, 'አዛዝዔልም ለሰዎች ሰይፍና ሾተል፥ ጋሻና ጥሩር መሥራትን አስተማራቸው።'),
  ('0354b395-4c0c-546a-a04c-71b0e506a019', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 19, 19, 'ከእነርሱም በታች ላሉት አምባሮችን፥ ጌጥን፥ ዐይን መኳልንና ቅንድብ መሸለልን፥ ከተመረጠና ከከበረ ከዕንቍም ሁሉ በከበረውና በተመረጠው ዕንቍ ማጌጥን፥ እንሶስላ መሞቅን ሁሉና የዓለሙን ለውጥ አሳያቸው።'),
  ('b82a1ead-2fc2-59d4-ab7a-414533d55a62', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 20, 20, 'ታላቅ ዝንጋዔና ብዙ ዝሙትም ተደረገ። ሳቱ፤ አመነዘሩም፤ መንገዳቸውም ሁሉ ጠፋ።'),
  ('702845f0-81f4-5f83-a950-ed4b055bfbb9', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 21, 21, 'አሚዛራክ ምታት ማሳየትን፥ ሥር መማስን ሁሉ አስተማረ። አርማሮስም ጋኔን መሳብን አስተማረ።'),
  ('ab2acc9d-59ad-5b74-a259-a2d190f901d9', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 22, 22, 'በራቅኤልም ኮከብ መቍጠርን አስተማረ።'),
  ('0cdcad45-a856-535a-abda-fcaa4daacbd7', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 23, 23, 'ኮከብኤልም ምልክት ማሳየትን አስተማረ።'),
  ('03902ffb-45c5-50cd-a8f3-db41a0874aa1', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 24, 24, 'ጥሞኤልም ኮከብ መቍጠርን አስተማረ።'),
  ('a29e45ac-a04a-5eef-aa5e-5eef94eb345c', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 25, 25, 'አስራድኤልም የጨረቃን አካሄድ አስተማረ።'),
  ('bea956d5-1f3d-5dfa-a2c1-ecf6e4dd9621', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 26, 26, 'በሰዎችም ጥፋት ሰዎች ጮኹ፤ ቃላቸውም ወደ ሰማይ ደረሰ።'),
  ('fef1de02-cde3-5605-a83b-884b167e0c69', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 27, 27, 'ያንጊዜም ሚካኤልና ገብርኤል፥ ሱርያልና ዑራኤል በሰማይ ሆነው ጐበኙ።'),
  ('f4c86e7f-61ce-5b1d-a472-a098a7ab0088', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 28, 28, 'በምድር ላይ የሚፈስሰውን ብዙ ደምና በምድር ላይ የሚደረገውን ግፍ ሁሉ አዩ።'),
  ('b3e5493c-ea9f-5eb0-a2e1-a9168423275a', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 29, 29, 'እርስ በርሳቸውም በጩኸታቸው ድምፅ እንዲህ አሉ- “ምድር ብቻዋን እስከ ሰማይ በር ጮኸች።'),
  ('059089a3-51b1-5997-aa6a-1d7cad24e604', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 30, 30, 'አሁንም የሰማይ ቅዱሳን ሆይ፥ የሰዎች ነፍሳት ፍርድን ወደ እግዚአብሔር አግቡልን እያሉ እናንተን ይማጠናሉ።'),
  ('a20e655a-51b4-54fb-abf5-a098829156f3', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 31, 31, 'ለጌታቸው ለንጉሡም እንዲህ አሉት- የጌቶች ጌታ፥ የአማልክት አምላክ፥ የነገሥታትም ንጉሥ አንተ ነህና።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('91289ebf-9dc5-5ec0-af0a-cb2d8a00826d', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 32, 32, 'የጌትነትህም ዙፋን ለልጅ ልጅ ዘመን ለዘለዓለም ነው። ስምህም ለልጅ ልጅ ዘመን ቅዱስና ክቡር የተመሰገነም ነው። አንተም ክቡር ምስጉን ነህ።'),
  ('a8aa54f1-0120-5986-ae0a-cda6f5cc8402', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 33, 33, 'ሁሉንም አንተ ፈጠርህ፤ የሁሉም ሥልጣን ከአንተ ጋር ነው፤ ሁሉም በፊትህ ፈጽሞ የተገለጠ ነው።'),
  ('ac9de6e5-fa5e-590b-ab24-98e398b9a21f', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 34, 34, 'አንተም ሁሉን ታያለህ፤ ከአንተም ሊሰወር የሚቻለው የለም።'),
  ('6be6d090-aea2-570f-a5df-c63a7a196131', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 35, 35, '“አዛዝኤል በምድር ላይ ግፍን ሁሉ እንደ አስተማረ፥ በሰማያት የሚሠሩትን፥ በዓለም የተሰወሩትን ሁሉ እንደ ገለጠ፥ ያደረገውን እይ።'),
  ('5919b1e6-b855-52f1-a4e2-7795ae96f3c9', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 36, 36, '“ከእርሱ ጋር በአንድነት ያሉትን ይገዛ ዘንድ አንተ ሥልጣን የሰጠኸው ስማዝያም ምታት ማሳየትን እንደ አመለከተ፥'),
  ('6200bde4-df59-51de-a077-a07572a6ce25', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 37, 37, 'በአንድነትም ወደ ሰው ሴቶች ልጆች እንደ ሄዱ፥ ከእነዚያም ሴቶች ጋር እንደ ተኙ፥ እንደ ረከሱ፥ እኒህንም ኀጢአቶች እንደ ገለጡላቸው፥'),
  ('14247be5-3141-5fbc-ad14-9d2706d9246d', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 38, 38, 'ሴቶችም ረዓይትን እንደ ወለዱ፥ በዚህም ምድር ሁላ ደምንና ግፍን እንደ ተመላች እይ።'),
  ('df422a6f-2013-5e41-a2d0-e4ada03ea9ee', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 39, 39, 'አሁንም እነሆ፥ የሞቱት ሰዎች ነፍሳት ይጮኻሉ፤ እስከ ሰማይ ደጅም ድረስ ይከስሳሉ።'),
  ('4609c29e-040b-5c3f-acc1-006c34f54d76', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 40, 40, 'ጩኸታቸውም ወጣ። በምድር ላይ ከሚሠራው ዐመፅ ፊትም መውጣት አይችሉም።'),
  ('78bb916a-8e84-5176-af3d-d924fda08701', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 41, 41, 'አንተም ሳይሆን ሁሉን ታውቀዋለህ፤ ይህንና የእነርሱንም አንተ ታውቀዋለህ።'),
  ('8fa3c437-3ccf-5572-a0c5-cd5189331f89', 'd15aacb1-8f77-598c-ad3c-b5928d6b68e7', '98c70f2e-30e8-59f2-a747-4f81103bb046', 42, 42, 'የምትነግረንም ነገር የለም። ስለዚህም ምን እናደርጋቸው ዘንድ ይገባል?”'),
  ('c17f946a-6e79-556c-ae5b-59d866bbefce', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 1, 1, 'ያንጊዜም ልዑሉና ገናናው፥ ቅዱሱም ተናገረ፥ ወደ ላሜህ ልጅ ወደ ኖኅም አርሰየላልዩርን ላከው።'),
  ('6d4c050d-5797-55fe-a8f0-606cb25a5f5e', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 2, 2, 'እንዲህም በለው አለው- በእኔ ስም ራስህን ሰውር፤ ምድር ሁሉ ትጠፋለችና የሚመጣውን ፍጻሜ ግለጽለት።'),
  ('adcc0380-60fa-54a1-ab50-c1a2a291d7ce', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 3, 3, 'በምድር ሁሉ ላይ የጥፋት ውኃ ይመጣል፤ በውስጥዋም ያለው ሁሉ ይጠፋል።'),
  ('51d39416-8886-581a-aa77-6144f3bbefdc', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 4, 4, 'አሁንም እርሱ ይሸሽ ዘንድ፥ ዘሩም በምድር ሁሉ ይኖር ዘንድ አስተምረው።”'),
  ('6e70fa01-fbe8-5734-af4a-5c90cdbd6b96', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 5, 5, 'ዳግመኛም እግዚአብሔር ሩፋኤልን እንዲህ አለው- “አዛዝኤልን እጁንና እግሩን አስረህ በጨለማ ውስጥ አግዘው።'),
  ('8c25dfab-0b68-5d38-aa15-f9406f861a33', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 6, 6, 'በዱዳኤል ያለች ምድረ በዳዋንም ክፈታት፤ እርሱንም በዚያ በጨለማው ውስጥ ጣለው፤ በላዩም ጠማማና ሻፎ ድንጋዮችን ግጠምበት።'),
  ('5025f701-7245-55e3-a041-0b995bf47eaa', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 7, 7, 'ጨለማንም አልብሰው፤ በዚያም ለዘለዓለሙ ይኑር፤ ብርሃንንም እንዳያይ፥ በታላቅዋም የፍርድ ቀን ወደ ገሃነም እንዲላክ ፊቱን ሸፍነው።'),
  ('713c3eb4-1ae5-504b-a9d4-1642e3cd471e', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 8, 8, 'መላእክት'),
  ('494d6c44-3b65-5239-a107-aab1da0f3133', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 9, 9, 'ትጉሃን'),
  ('682166b9-00db-5575-a005-0fb575305f8e', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 10, 10, 'ምድርም ሁላ በአዛዝኤል ሥራ ትምህርት ጠፋች፤ ኀጢአትን ሁሉ በእርሱ ጻፍበት።”'),
  ('a77dc569-c3c2-5674-a208-de65efa10291', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 11, 11, 'ገብርኤልንም እግዚአብሔር አለው- “በዘፋኞችና በተናቁ ሰዎች ላይ፥ በአመንዝራ ልጆች ላይም ሂድ፥ የአመንዝራዪቱን ልጆችና የትጉሃንን'),
  ('5e07913b-685e-54d0-ac06-42ee6051a5bd', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 12, 12, 'እርስ በርሳቸውም አስወጥተህ ስደዳቸው፤ የዘመን ርዝመት የላቸውምና እነርሱ ራሳቸው በጦርነት ይጠፋፋሉ።'),
  ('0756aa2d-1b86-51d7-af8d-aefc62cca4f8', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 13, 13, 'የዘለዓለም ሕይወትን ሊኖሩ ተስፋ ያደርጋሉና፤ ከእነርሱ እያንዳንዱ አምስት መቶ ዘመንን ሊኖር ተስፋ ያደርጋልና ሁሉም ይለምኑሃል፤ ስለ እነርሱም ለአባቶቻቸው አይሆንላቸውም።”'),
  ('d8bad8c9-368b-5d5b-ad5e-590a6aeb5688', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 14, 14, 'ሚካኤልንም እግዚአብሔር አለው- “ሄደህ ለስምያዛ ንገረው፤ በርኵሰታቸው ሁሉ ከእነርሱ ጋር ይጠፉ ዘንድ ከሴቶች ጋር ለተባበሩ ከእርሱ ጋራ ላሉ ለሌሎችም ንገራቸው።'),
  ('05b90b5e-eeee-5736-ae74-66741970c5cd', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 15, 15, 'ልጆቻቸውም ሁሉ በሚዋጉበት ጊዜ፥ የወዳጆቻቸውንም ጥፋት በሚያዩበት ጊዜ እስከ ፍርዳቸው ዕለትና እስከ ፍጻሜያቸው ድረስ፥ የዘለዓለም ፍርድ እስኪፈጸም ድረስ ሰባውን ትውልድ በምድር ኮረብታ በታች እሰራቸው።'),
  ('3c6fdee5-ddc4-564c-aeb5-14ab6f2234f4', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 16, 16, '“በዚያም ወራት ከእሳቱ በታች ወደ አለው ቦታ በጭንቅ ይወስዷቸዋል፤ በግዞት ቤትም ለዘለዓለም ይዘጋባቸዋል።'),
  ('54970af3-145a-54a8-a3e8-52060af29778', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 17, 17, 'ያንጊዜም ከእነርሱ ጋር የተባበረ ከዛሬ ጀምሮ እስከ ዘለዓለም ድረስ ይቃጠላል፤ ይጠፋልም፤ እስከ ልጅ ልጅ ዘመን መጨረሻ ድረስም ይጋዛሉ።'),
  ('4851fb42-71c1-5693-a271-02a39c8bc40e', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 18, 18, 'ሰዎችን በድለዋቸዋልና የዋዛ ሰዎችን ሁሉና የትጉሃን ልጆችን አጥፋቸው፤ ግፉንም ሁሉ ከገጸ ምድር አጥፋ፤ ክፉ ሥራም ሁሉ ይጥፋ፤ የጽድቅና የርትዕ ተክልም ለዘለዓለም ይገለጣል።'),
  ('7dba81a4-cd92-5eac-a6dc-cbe9d51b55d2', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 19, 19, 'ሥራውም ሁሉ ለበረከት ይሆናል፤ ጽድቅና ርትዕም ለዘለዓለም በደስታ ይተከላሉ።'),
  ('af1b7970-c3f7-5c18-af8d-7c0330592060', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 20, 20, 'አሁንም ጻድቃን ሁሉ ያመልጣሉ፤ ሺህ ልጆችንም እስኪወልዱ ድረስ ሕያዋን ይሆናሉ።'),
  ('0722ff37-5fe9-5c24-a238-d313d93cd5ad', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 21, 21, 'የሕፃንነታቸውንና የሽምግልናቸውን ዘመን ሁሉ በሰላም ይፈጽማሉ።'),
  ('5304b39b-69ec-5067-acfc-d9b402d3770b', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 22, 22, 'በእነዚያም ወራቶች ምድር ሁሉ በእውነት ትታረሳለች፤ በመላዋም ዛፎች ይተከሉባታል፤ በረከትንም ትሞላለች።'),
  ('192df62d-214e-5e86-a1ea-6b7f8e8b63d1', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 23, 23, 'የደስታ ዛፎችም ሁሉ በእርሷ ላይ ይተከላሉ፤ ወይኖችም በእርስዋ ላይ ይተከላሉ፤ በእርስዋም ላይ የሚተከለው ወይን፥ በእርስዋም ላይ የሚዘራው ዘር ለጥጋብ ፍሬን ያደርጋል።'),
  ('68a1feff-1401-5620-a3a4-a442581332ce', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 24, 24, 'አንዲቱ መስፈሪያ ሺህ መስፈሪያ ታፈራለች፤ አንዲቱ የዘይት መስፈሪያም ዐሥር የዘይት ዐውድማን ትመላለች።'),
  ('95afca5a-037d-52d2-a32b-6562c606a3b6', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 25, 25, 'አንተ ግን ከግፉ ሁሉ፥ ከዐመፅም ሁሉ፥ ከኀጢአትም ሁሉ፥ ከበደልም ሁሉ፥ በምድር ላይም ከሚሠራው ርኵሰት ሁሉ ምድርን አንጻት።'),
  ('4b492b99-818b-54ba-a1fb-d7c62a121392', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 26, 26, 'በምድር ላይም አጥፋቸው፤ የሰው ልጆችም ሁሉ ጻድቃን ይሁኑ፤ አሕዛብም ሁሉ እኔን የሚያመልኩና የሚያመሰግኑ ይሁኑ።'),
  ('e06b5717-7970-56d4-a613-e8c64cc84005', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 27, 27, 'ሁሉም ለእኔ ይሰግዳሉ፤ ምድርም ከጥፋት ሁሉ፥ ከኀጢአትም ሁሉ፥ ከመቅሠፍትም ሁሉ፥ ከጭንቅም ሁሉ ትነጻለች።'),
  ('bf929c5f-5fda-52de-ab00-f6655bd1c7eb', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 28, 28, 'ለልጅ ልጅ ዘመንና እስከ ዘለዓለም ድረስ በእርሷ የጥፋትን ውኃ አልደግምም።'),
  ('8a816b9f-3eb0-5873-a2e0-fde4f428cadc', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 29, 29, '“በእነዚያም ወራቶች በሰዎች ልጆች ሥራና ድካም ላይ ወደ ምድር አወርዳቸው ዘንድ በሰማያት ያሉ የበረከት መዛግብትን እከፍታለሁ።'),
  ('fcbb2759-330b-5a36-a9cd-fa96c306b580', 'f5fd451a-2840-5e0c-a245-3a7eac0802de', '0090908b-c250-59c3-a132-c661ed4d7f62', 30, 30, 'ሰላምና ርትዕ በአንድነት በዚህ ዓለም ዘመን ሁሉና በልጅ ልጅ ዘመን ሁሉ አንድ ይሆናሉ።”'),
  ('bec236d6-35d3-5393-ae26-709622e63b71', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 1, 1, 'ከነገር ሁሉ አስቀድሞ ሄኖክ ተሰወረ።'),
  ('72ef73e7-b9a7-574e-adbe-f357d0089fc3', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 2, 2, 'ከሰው ልጆችም የተሰወረበትንና ያለበትን ቦታ፥ ምን እንደሆነም የሚያውቅ አልነበረም።'),
  ('ebd946c4-add6-53c4-ab35-6b5f8b072526', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 3, 3, 'በዘመኑ ሥራው ሁሉ፥ ከቅዱሳንና ከትጉሃን ጋር ነበር።'),
  ('f7eadded-868a-53ad-a0bb-7a64149579a8', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 4, 4, 'እኔም ሄኖክ ታላቁን ጌታ የዓለምን ንጉሥ አመሰግን ጀመር።'),
  ('3ad87f3c-0963-5b77-a80c-3010289b8b88', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 5, 5, 'እነሆም ትጉሃን- እኔን ጸሓፊውን ሄኖክን ጠሩኝ።'),
  ('339714d1-d2cd-5e24-aedd-ca98b5dfe26e', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 6, 6, 'እንዲህም አሉኝ- “የጽድቅ ጸሓፊ ሄኖክ፥ ከፍተኛውን ሰማይና ዘለዓለማዊዉን ቅዱስ ቦታ ለተዉ ለሰማይ ትጉሃን ሂድና ንገር፥'),
  ('127b62b6-5711-5044-a178-bf6e19dcf305', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 7, 7, 'ከሴቶችም ጋር ጠፉ፤ የሰው ልጆችም እንደሚያደርጉ አደረጉ።'),
  ('41236491-3fee-5193-aa55-90cb7032f96b', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 8, 8, 'ለራሳቸውም ሚስቶችን አገቡ፥ በምድርም ላይ ታላቅ ጥፋትን ጠፉ።'),
  ('b5fc9d5c-9a48-5be3-ab6d-6b1b5857b014', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 9, 9, 'በምድርም ላይ ሰላምና የኀጢአት ስርየት አይሆንላቸውም።'),
  ('83f19ae1-6efb-53c4-a6ff-127e16f13456', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 10, 10, 'በልጆቻቸውም ደስ አይላቸውምና፥ የወዳጆቻቸውን ሞት ያያሉ፤ በልጆቻቸውም ጥፋት ጮኸው ያለቅሳሉ።'),
  ('11da02c6-d565-58f9-a2c3-c3490025a4f7', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 11, 11, 'ለዘለዓለም ይለምናሉ፥ ምሕረትም፥ ሰላምም አይደረግላቸውም።”'),
  ('81684a91-2b69-517b-a213-9284baa6421a', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 12, 12, 'ሄኖክም ሄዶ አዛዝኤልን አለው- “ሰላም አይደረግልህም።'),
  ('6bf3f5c2-b342-5b5d-a23a-1d0553755e3b', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 13, 13, 'ሊያጠፋህ ታላቅ ፍርድ በአንተ ላይ ወጣ።'),
  ('ef129fc7-9c7c-5943-acf9-f64e6812c0ea', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 14, 14, 'ግፍን ስለ አስተማርህ፥ ለሰው ልጆችም ስላሳየኸው የፅርፈት፥ የግፍና የኀጢአት ሥራ ሁሉ ዕረፍትና ልመና፥ ይቅርታም አይደረግልህም።”'),
  ('d12d2de2-2ba2-5878-a148-dc1f4dda8d60', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 15, 15, 'ያንጊዜ ሄጄ ለሁሉም በአንድነት ነገርኋቸው።'),
  ('49e5e722-0ac5-5ee1-a3a3-fac18752eb7f', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 16, 16, 'እነርሱም ሁሉ ፈሩ፤ ፍራት፥ መንቀጥቀጥም ያዛቸው።'),
  ('21dc0152-e1b5-5290-a025-6ee040392bf3', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 17, 17, 'የኀጢአት ማስተስረያ እንዲሆናቸው ወደ ሰማይ ወደ እግዚአብሔር የልመናቸውን መታሰቢያ እንዳሳርግላቸው የልመናቸውን መታሰቢያ እጽፍላቸው ዘንድ ለመኑኝ።'),
  ('e65ea437-6d58-5531-a275-adddf649b715', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 18, 18, 'እነርሱ ከዛሬ ጀምረው መነጋገር አይችሉምና፥ ከተፈረደባቸው የበደል ኀፍረት የተነሣም ዐይኖቻቸውን ወደ ሰማይ አቅንተው ለማየት አይችሉምና።'),
  ('7d3dd0ae-4736-5b21-acb0-91e96a00dcd6', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 19, 19, 'ያንጊዜም ስለ ሰውነታቸውና ስለ እያንዳንዳቸው ሥራ፥ የኀጢአት ማስተስረያና የዘመን ርዝመት ይሆንላቸው ዘንድ ስለሚለምኑ የልመናቸውንና የምልጃቸውን መታሰቢያ ጻፍሁ።'),
  ('67143533-cd1e-5875-afa6-b927aed4697c', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 20, 20, 'ሄጄም በዳን ውኃዎች አጠገብ በዳን ተቀመጥሁ፤ ይህቺውም ከአርሞን ምዕራብ በቀኝ ያለች ናት።'),
  ('26b05f42-7e32-5f86-a7b3-71306290a973', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 21, 21, 'እስካንጎላችም ድረስ የልመናቸውን መታሰቢያ ተናገርሁ።'),
  ('8bab2167-09e8-569a-a88d-d59936c56855', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 22, 22, 'እነሆም፥ ሕልም መጣብኝ፤ ራእዮችም ተገለጡልኝ።'),
  ('e2c675f1-fdf6-5dfa-a0b9-57b4f1bc74ec', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 23, 23, 'ለሰማይ ልጆች እነግር ዘንድ፥ እዘልፋቸውም ዘንድ የመቅሠፍት ራእይን አየሁ።'),
  ('80d47fd2-777c-5e72-a21b-b2d96db9b6dd', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 24, 24, 'ነቅቼም ወደ እነርሱ መጣሁ፤ ሁሉም በሊባኖስና በሴንሴር መካከል ባለች በኡብልስያኢል ፊታቸውን ተሸፋፍነው እያለቀሱ ተሰብሰበው ነበር።'),
  ('2b51140e-ac72-59ea-a74c-a4f270dfb6d8', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 25, 25, 'እኔም ተኝቼ ያየሁትን ራእይ ሁሉ በፊታቸው ተናገርሁ።'),
  ('1fd6d715-5953-5e26-afaf-36704ae64c8a', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 26, 26, 'እነዚያንም የጽድቅ ቃላት እናገር ዘንድ፥ ለሰማይ ትጉሃንም አስተምር ዘንድ ጀመርሁ።'),
  ('7e3fcf9e-ff2b-5ea3-a4e3-8aa1ee388253', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 27, 27, 'ቅዱሱና ገናናው በዚች ራእይ እንዳዘዘ የጽድቅና ከጥንት ጀምሮ የነበሩ የትጉሃን የዘለፋ መጽሐፍ ይህ ነው።'),
  ('79663dca-5c4e-59d8-a58b-d48e2016379b', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 28, 28, 'በሥጋ አንደበትና በመንፈሴ እኔ ዛሬ የምናገረውን ነገር ተኝቼ አየሁ፤ ገናናው አምላክ ይናገሩበት ዘንድ፥ እንደ ፈጠረም በልብ ያስተውሉ ዘንድ ለሰዎች አፍን ሰጠ፤ ያስተውሉም ዘንድ ለሰዎች የዕውቀት ቃልን ሰጠ።'),
  ('a3c84b85-305f-5985-ac18-b385cde70425', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 29, 29, 'ለእኔም ፈጠረልኝ፥ ለትጉሃን የሰማይ ልጆችም አስተምራቸው ዘንድ ሰጠኝ።'),
  ('4202b885-7e23-5bd5-ac5b-c636af0e48f5', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 30, 30, 'እኔ ልመናችሁን ጻፍሁ።'),
  ('d36db590-8063-568b-a930-28cd7b304660', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 31, 31, 'በራእዬም እንዲህ አሳየኝ፥ በዓለም ዘመን ሁሉ ልመናችሁ አትደረግላችሁምና።'),
  ('9c4f7567-100f-5365-a7db-256894504fd4', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 32, 32, 'ፍጽምት ፍርድም በእናንተ ላይ ወጣች፤ አይሆንላችሁምም።'),
  ('4be26d85-a365-59ed-ad1c-bd101c01aeb8', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 33, 33, 'ከዛሬ ጀምሮ ዓለም ሁሉ እስኪያልፍ ድረስ ወደ ሰማይ አትወጡም።'),
  ('c832b93f-d74a-54e9-aafd-ff5f0d28437d', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 34, 34, 'በዓለም ዘመን ሁሉ ያስራችሁ ዘንድ በምድር ተነገረ።'),
  ('367a298f-5619-590c-afe4-805493f031b8', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 35, 35, 'ከዚህም አስቀድሞ የምትወዷቸው የልጆቻችሁን ጥፋት አያችሁ።'),
  ('56c24d14-9068-55a9-a2fe-45519b750f92', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 36, 36, 'በፊታችሁ በሰይፍ ያልቃሉ እንጂ ጥሪትነታቸው አይኖራችሁም።'),
  ('a27412ec-d921-52ad-a66a-f37b3731e67d', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 37, 37, 'ስለ እናንተና ስለ እነርሱም የለመናችሁት ልመና አይደረግላችሁም።'),
  ('68bd16b2-4647-5be7-a7cc-f99b043a2959', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 38, 38, 'እናንተም እያዘናችሁና እያለቀሳችሁ ከጻፍሁላችሁ መጽሐፍ ምንም ቃል አትናገሩም።'),
  ('b69b4844-3134-5eb4-a279-de1e1ee9b966', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 39, 39, 'ለእኔም እንዲህ ያለ ራእይ ታየኝ።'),
  ('86fe989a-4a43-58dd-abac-4035c92e7398', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 40, 40, 'እነሆ፥ ደመናዎች በራእይ ይጠሩኛል፥ ጉምም ይጠራኛል።'),
  ('40c49976-06b9-5699-a7e1-aca9f366bd74', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 41, 41, 'ኮከቦችና መብረቆችም በሩጫ ያስቸኩሉኛል፥ ያስጨንቁኛልም።'),
  ('0f3e8be7-8bbc-592d-a0cb-d150a4c9dfe8', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 42, 42, 'ነፋሶችም በራእይ ያበርሩኛል፥ ያስቸኩሉኛልም። ወደ ላይ ወደ ሰማይም ወሰዱኝ።'),
  ('98af319d-bfff-531e-a813-d6b4d09b77d1', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 43, 43, 'በእብነ በረድ ወደ ተሠራች ግንብ እስክቀርብ ድረስ ገባሁ።'),
  ('ca783fb2-6ed1-5535-a263-193839be3881', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 44, 44, 'የእሳትም ላንቃ ይከብባታል፥ እኔንም ያስፈራኝ ጀመረ።'),
  ('0676c3fd-30c7-59c6-a8db-fda92adf18b5', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 45, 45, 'ወደ እሳቱም ላንቃ ገባሁ፥ በእብነ በረድም ወደ ተሠራው ታላቅ ቤት ቀረብሁ።'),
  ('b8d1baf9-0413-5033-ac62-c4fa70f91562', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 46, 46, 'የዚያም ቤት ግድግዳ ከእብነ በረድ እንደ ተሠራ ወለል ነው።'),
  ('40b6f2ab-b552-5d85-ab34-bacd0bc28ce9', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 47, 47, 'ምድሩም በረድ ነው፥ ጠፈሩም እንደ ኮከብና መብረቅ ሩጫ ነው።'),
  ('da9b9778-0f22-596a-a23c-b19ae6487e22', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 48, 48, 'በመካከላቸውም እሳታውያን ኪሩቤል አሉ። ሰማያቸውም ውኃ ነው።'),
  ('0e1245fa-0332-5d89-a4be-db09ea902eed', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 49, 49, 'በቅጥሩም ዙሪያ የሚነድ እሳት አለ፥ ደጃፉም በእሳት ይቃጠላል።'),
  ('f3394f3f-46d8-51e7-a20e-5b74584d4bf2', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 50, 50, 'ወደዚያም ቤት ውስጥ ገባሁ፥ እንደ እሳትም ይሞቃል፤ እንደ በረድም ይቀዘቅዛል።'),
  ('7c6e0a4c-b729-58df-a09b-6c1f0b70ebb6', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 51, 51, 'ምንም ደስታና ሕይወት በውስጡ የለም፤ ፍርሀት ሸፈነኝ፥ እንቅጥቅጥም ያዘኝ፤ እየታወክሁና እየተንቀጠቀጥሁም በግንባሬ ወደቅሁ፥ በራእይም አየሁ።'),
  ('126df6a7-dd89-5eac-ae36-5cc634e9e380', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 52, 52, 'እነሆም፥ ከዚህ ቤት የሚበልጥ ሌላ ቤት አለ።'),
  ('c168e913-0b37-576f-a4fd-75aca5e15ebf', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 53, 53, 'በፊቴም ደጃፉ ሁሉ የተከፈተ ነው፥ በእሳት ላንቃም የተሠራ ነው።'),
  ('5c008817-12c1-5e08-a4eb-f55e2194f88d', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 54, 54, 'ስለ ክብሩና ስለ ገናናነቱ ልነግራችሁ እስከማልችል ድረስ በሁሉም በብርሃንና በክብር፥ በገናናነትም ይበልጣል።'),
  ('8556157d-1ff2-5ecd-a30a-a1990d81deef', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 55, 55, 'ወለሉም እሳት ነው፥ በላዩም መብረቅና የኮከቦች መሮጫ አለበት፤ ጠፈሩም የሚነድ እሳት ነው።'),
  ('b99557c3-6a5b-5698-ab4c-9ab2e9d3fc17', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 56, 56, 'በውስጡም ከፍ ያለ ዙፋንን ፈጽሜ አየሁ።'),
  ('6dd02b48-12ad-5a13-a937-35d06257d3fa', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 57, 57, 'መልኩም እንደ ውርጭ ነው፥ ክበቡም እንደሚያበራ ፀሐይ ነው፥ የኪሩቤልም ቃል ይሰማል።'),
  ('bce3f593-c03a-5ee5-a396-a3ec145d7de2', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 58, 58, 'ከታላቁ ዙፋንም በታች የሚነድ የእሳት ፈሳሾች ይወጣሉ፤ ማየትም አይቻላቸውም።'),
  ('adba5700-a066-54f5-a3c4-5ccc91183961', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 59, 59, 'የክብር ጌታም በእርሱ ላይ ተቀምጧል፤ መጐናጸፊያውም ከፀሐይ ይልቅ ያበራል፥ ከበረድም ሁሉ ይልቅ ይነጣል።'),
  ('eca62ef9-a533-5676-a2c6-e8319c4815cb', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 60, 60, 'ከመላእክትም ማንም ወደ እርሱ መግባት፥ የክቡሩንና የምስጉኑንም ፊት ማየት አይችልም፤ ማንም ሥጋዊ ሰውም ያን እሳት ያይ ዘንድ አይችልም።'),
  ('1474980b-8173-5013-a78d-cfbd07c0d2d0', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 61, 61, 'በዙሪያውም የሚነድ እሳት አለ፥ በፊቱም ታላቅ እሳት ይቆማል።'),
  ('80de792b-bc88-5e22-af24-7168961e9ed8', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 62, 62, 'በዙሪያው ካሉም ወደ እርሱ የሚቀርብ የለም፥ የብዙ ብዙ መላእክትም በፊቱ አሉ።'),
  ('efd55cc3-e79d-5eab-ab54-091fb166c0fc', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 63, 63, 'እርሱ ግን ልዩ ምክርን አይሻም።'),
  ('79406b12-1da7-54cd-a9c9-46f102552315', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 64, 64, 'ወደ እርሱ የሚቀርቡ ቅዱሳንም በቀንና በሌሊት አይርቁም፥ ከእርሱም አይወገዱም።'),
  ('b07fefdd-1060-5b7c-acdc-1faef9dedca9', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 65, 65, 'እኔም እስከዚህ ድረስ እየተንቀጠቀጥሁ ፊቴን ተከናንቤ ነበርሁ።'),
  ('baba2b3b-7bfb-5289-acba-8e360371f93b', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 66, 66, 'ጌታም በአንደበቱ ጠርቶ “ሄኖክ! ወደዚህ ወደ ቅዱስ ቃሌ ቅረብ” አለኝ።'),
  ('37ae043d-1110-5780-a900-aa1c94ed2f3d', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 67, 67, 'አንሥቶም እስከ ደጃፉ ድረስ አቀረበኝ፥ እኔ ግን ፊቴን ደፍቼ ወደታች እመለከት ነበር።'),
  ('f52fc515-f0fc-53f7-a5e2-36b0a15261f8', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 68, 68, 'መለሰልኝ፥ በቃሉም እንዲህ አለኝ- “ጽድቅን የምትጽፍ ጻድቅ ሰው ሄኖክ፥ ስማ፥ አትፍራም።'),
  ('5daeb8da-e86c-531e-a884-a226bb7a8aa8', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 69, 69, 'ወደዚህ ቅረብ፥ ቃሌንም ስማ፤ ስለ እነርሱ ልትለምንላቸው ለላኩህ ለሰማይ ትጉሃንም ሄደህ እንዲህ በላቸው-'),
  ('c9641ef5-0f96-548b-aa15-336f3a67337f', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 70, 70, 'እናንተ ስለ ሰው ልትለምኑ ይገባችሁ ነበር፤ ሰዎች ግን ስለ እናንተ አይደለም።'),
  ('a13241a9-dc49-5f47-ae1f-bc09798471b1', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 71, 71, 'ከፍ ያለውን ሰማይና ለዘለዓለም ቅዱስ የሆነውን ቦታ ስለምን ተዋችሁት?'),
  ('90858327-adaa-5fa8-a09e-a18d72f42c31', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 72, 72, 'ከሴቶችም ጋር ተኛችሁ፥ ከሰው ሴቶች ልጆች ጋርም ረከሳችሁ።'),
  ('7d798ff8-9291-5b8e-a37f-55cd50910dc4', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 73, 73, 'ለራሳችሁም ሚስቶችን አገባችሁ፤ እንደ ምድር ልጆችም አደረጋችሁ፥ ረዓይት ልጆችንም ወለዳችሁ።'),
  ('718e9f43-16d9-58ce-ab57-c5ccc96d22cd', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 74, 74, 'ለዘለዓለም በሕይወት የምትኖሩ ቅዱሳን መንፈሳውያን እናንተ ግን በሴቶች ረከሳችሁ።'),
  ('612199b3-003e-5439-a4f5-7167ecc6df44', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 75, 75, 'በሥጋዊ ደም አስወለዳችሁ፥ የሰውን ደምግባትም ተመኛችሁ፥ እነርሱም ሥጋዊና ደማዊ ሥራን እንደሚሠሩ ሠራችሁ።'),
  ('2f1fe2dc-6504-589a-a893-9a0fce00fe80', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 76, 76, 'እነዚህም የሚሞቱና የሚጠፉ ናቸው፥ ስለዚህም ዘራቸውን በእነርሱ ላይ ይዘሩ ዘንድ፥ ልጆችም ከእነርሱ ይወለዱ ዘንድ ሴቶችን ሰጠኋቸው።'),
  ('632917bd-7106-569f-a6f6-2b6cc3c0b342', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 77, 77, 'በምድርም ላይ እንደዚህ ያለ ሥራ ሲሠራ ይኖራል።'),
  ('45eb7566-f56d-55c6-ace3-953cfc27892a', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 78, 78, 'እናንተ ግን ከዚህ አስቀድሞ በልጅ ልጅ ዘመን በማይጠፋ፥ በዘለዓለማዊ ሕይወት ሕያዋን የሆናችሁ መንፈሳውያን ነበራችሁ።'),
  ('fcbca8ae-9040-543d-a96e-a32dfbb033bd', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 79, 79, 'ስለዚህም ለእናንተ ሴቶችን አላደረግሁላችሁም፥ የመንፈሳውያን ማደሪያቸው በሰማይ ነውና።'),
  ('0724de0c-f024-5cf2-af3a-d17ddf86b18a', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 80, 80, 'አሁንም ከመንፈስና ከሥጋ'),
  ('8c416137-3f1e-5e5f-aa27-fff1e36c8b15', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 81, 81, 'ማደሪያቸውም በምድር ይሆናል።'),
  ('9cf4ee0d-de49-5bd8-a75d-ab1edecb0804', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 82, 82, 'ክፉዎች ነፍሳትም ከሥጋቸው ወጡ፤ መሠረታቸው ከሚሆኑ ከቅዱሳን ትጉሃን ከላይ ተፈጥረዋልና።'),
  ('bd8a963b-d92d-50e5-a01a-1f613fb2dbf8', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 83, 83, 'መጀመሪያ መሠረት የነበሩ በምድር ላይ ክፉ መንፈስ ይሆናሉ፤ ክፉ መንፈስም ተብለው ይጠራሉ።'),
  ('eff9f1f3-991f-52a1-a48a-720eb27a46a7', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 84, 84, 'ለሰማይ መናፍስትም ማደሪያቸው በሰማይ ይሆናል፤ በምድር ለተወለዱ መናፍስትም ማደሪያቸው በምድር ይሆናል።'),
  ('e6f51348-4f1d-5067-aeab-ba879dee50dd', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 85, 85, 'ደመናትን የሚገፉ የረዓይት መናፍስትም ይጠፋሉ፤ ይወድቃሉም፥ እርስ በርሳቸውም ይጣላሉ፤ በምድርም ያደቅቃሉ።'),
  ('0da53b69-a160-5c5e-a7ed-b2aa8824e6e3', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 86, 86, 'ኀዘንንም ያደርጋሉ፥ የሚበሉትንም እህል ምንም አያገኙም።'),
  ('2cd131b5-524d-5f74-a171-d9582faa1925', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 87, 87, 'አይጠሙም፥ አይታወቁምም።'),
  ('cc2218ff-53ed-5fbc-afbe-eb04c37239bf', '2914ad82-6df8-5920-afb6-88e457abefc0', 'd4d5927e-d87b-5ffa-ace7-ca37a6934e2c', 88, 88, 'በሰልፍና በጥፋት ወራት ተወልደዋልና እነዚህ ሰዎች በሰዎች ወንዶች ልጆችና በሴቶች ላይ አይነሡም።”'),
  ('c9fc33e9-e7ef-550b-a81c-ab840966cae1', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 1, 1, 'የረዓይትም ሞት መናፍስት ከሥጋቸው በወጡበት ይሆናል።'),
  ('f8ee8437-9f4e-52a2-a043-ef7854292f78', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 2, 2, 'የሚጠፋም ይሁን።'),
  ('e8228c3e-f4ea-59a6-a7e7-0bcc6d80bc5f', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 3, 3, 'ፍርድም ሳይደረግ እንዲሁ ይጠፋሉ፤ እስከ ታላቋ የፍጻሜ ዕለት ድረስ ከታላቋ ዓለም ከትጉሃንና ከዝንጉዎች የተነሣ ፍርድ ይፈጸማል።'),
  ('fd50b149-132d-5b07-a7a9-bce6460338db', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 4, 4, 'አሁንም ስለ እነርሱ ልትለምንላቸው የላኩህን አስቀድሞ በሰማይ የነበሩ ትጉሃንን እንዲህ በላቸው።'),
  ('02854670-c430-585d-a24d-7bcd88fd1d7d', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 5, 5, '“ዛሬም እናንተ በሰማይ አላችሁ፥ ምሥጢራትም ገና አልተገለጡላችሁም።'),
  ('4eb2f66f-7952-547e-a8f1-caf69264a98f', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 6, 6, 'የተናቀ ምሥጢርንም ዐወቃችሁ፥ በልቡናችሁም ጽናት ይህን ለሴቶች ነገራችሁ።'),
  ('89b71a1a-3b77-5dc4-a2ce-c87d0eab3205', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 7, 7, 'በዚህም ምሥጢር ሴቶችና ወንዶች በምድር ላይ ክፋትን ያበዛሉ፤ እንግዲህስ ሰላም የላችሁም።”'),
  ('2fd4a821-9b79-5abb-a470-d5d64ff40afe', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 8, 8, 'እንደ ቋያ የሚቃጠሉ ሰዎች ወዳሉበት አንድ ቦታ ወሰዱኝ፤ በወደዱም ጊዜ እንደ ሰው ይታያሉ።'),
  ('ccbfca54-e8e3-5ee6-a390-392212866080', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 9, 9, 'ጥቅል ነፋስ ወዳለበት ቦታ፥ ራሱም እስከ ሰማይ ወደሚደርስ ተራራ ወሰዱኝ።'),
  ('3941c2c4-5d79-5eb0-ad18-ef877de15ef9', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 10, 10, 'የሚያበሩ አራት ቦታዎችንም አየሁ፤ በጥልቁም ዳርቻ ነጐድጓድ አለ፤ የእሳት ቀስትና ጐራንጕሪያቸውም፥ የእሳት ሰይፍና መብረቆችም ሁሉ አሉ።'),
  ('2ca1d966-b55d-5cf7-a906-a157de2636d4', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 11, 11, 'የሚናገር የሕይወት ውኃና የምዕራብ እሳት እስካለበት ድረስ ወሰዱኝ፤ ይኸውም የፀሐይን መግቢያ ሁሉ የሚይዝ ነው።'),
  ('e6737692-bba4-5420-a0c3-99fcab338a1e', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 12, 12, 'እሳቱ እንደ ውኃ እስከሚፈስስ እስከ እሳት ፈሳሽ ድረስ መጣሁ፤ በምዕራብ ወዳለው ወደ ታላቁም ባሕር ይፈስሳል።'),
  ('f1f5307c-35ec-5eb7-ae54-52ca299789b1', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 13, 13, 'ታላላቅ ወንዞችንም ሁሉ አየሁ፤ እስከ ታላቁ ጨለማም ድረስ ደረስሁ፥ ሥጋዊ ሁሉ ወደሚመላለስበትም ሄድሁ።'),
  ('1601b103-6085-5cde-ae3c-717867378254', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 14, 14, 'የክረምት ጭጋጎች ያሉባቸው ተራሮችንም፥ የወንዙም ሁሉ ውኃ የሚፈስበትን አየሁ።'),
  ('1c369e4b-df6e-5e1e-a6cb-cbab130ef7be', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 15, 15, 'የምድር ወንዞችን ሁሉ አፋቸውን፥ የጥልቁንም አፍ አየሁ።'),
  ('934ab412-55b9-5889-a8b4-fa9fdea6f3b4', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 16, 16, 'የነፋሶችንም ሁሉ ቦታዎች አየሁ፤ ፍጥረቱንና የምድሩን ሁሉ መሠረቶች በእነርሱ እንዳስጌጠ አየሁ።'),
  ('551adf25-e5ae-5066-af4d-05d2ad3355bf', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 17, 17, 'የምድርንም የማዕዘን ድንጋይ አየሁ፤ ምድርንና ጠፈርንም የሚሸከሙ አራቱን ነፋሳት አየሁ።'),
  ('ed1886d6-9dfc-5cac-a2bd-502451d10587', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 18, 18, 'የሰማይንም ከፍታ ነፋሳት እንደ ዘረጓት አየሁ።'),
  ('ff27d4f4-4292-50ec-a466-765215fd8789', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 19, 19, 'እነርሱም በሰማይና በምድር መካከል ይቆማሉ፤ እነርሱም የሰማይ ምሰሶዎች ናቸው።'),
  ('1ee4ded6-348c-5892-a365-829dee5c7f63', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 20, 20, 'ሰማይን የሚመልሷት፥ የፀሐይን ክበብና ከዋክብትን ሁሉ የሚያገቡ ነፋሳትንም አየሁ።'),
  ('9591b867-321b-5d86-aafe-7d08e3afcdce', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 21, 21, 'በምድር ላይ ደመናትን የሚሸከሙ ነፋሳትንም አየሁ።'),
  ('76e73e71-ed88-5ca3-a385-848d815003fd', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 22, 22, 'የመላእክትንም መንገድ አየሁ፤ በምድር ዳርቻም በላይ ያለ ጠፈርን የሚያጸና አድማስን አየሁ።'),
  ('d038cfa0-ebc9-530d-ae12-24e242f15bb4', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 23, 23, 'ወደ አዜብ፥ ከከበረ ድንጋይም ይልቅ ወደሚያበሩ ወደ ሰባት ተራሮች ሄድሁ።'),
  ('ec9d2464-51c4-5b21-a543-42f196317dd6', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 24, 24, 'ሦስቱ በምሥራቅ በኩል፥ ሦስቱም በአዜብ በኩል ናቸው። በምሥራቅ በኩል ያለው ግን አንዱ ከቅጥልጣል ዕንቍ ነው፤ አንዱ ከባሕርይ ዕንቍ ነው፤ አንዱም ደምርፅ ከሚባል ዕንቍ ነው፤ በአዜብ በኩል ያለውም ከቀይ ዕንቍ ነው።'),
  ('ad75d48a-90e6-5b64-a15d-42dc687a2657', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 25, 25, 'መካከለኛው ግን ፔካ ከሚባል ዕንቍ እንደ ተሠራ እንደ እግዚአብሔር ዙፋን እስከ ሰማይ ይደርሳል።'),
  ('c0ebf307-cbea-5d66-a1a2-2970609db7b7', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 26, 26, 'አጎበሩም ሰንፔር ከሚባል ዕንቍ ነው፤ በተራራው ሁሉ ያለ የሚነድድ እሳትንም አየሁ።'),
  ('5d53cea5-2cf8-57a7-a395-e2bb7856ba57', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 27, 27, 'በዚያም በታላቅ ምድር መጨረሻ የሚሆን ቦታን አየሁ፤ በዚያም ውኃዎች ይሰበሰባሉ።'),
  ('9297885d-1b27-597e-a1d6-83f104ab17c0', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 28, 28, 'በሰማይ እሳት ምሰሶዎችም ጥልቅ የሆነ የምድር ጕድጓድን አየሁ።'),
  ('4fcffb16-85df-56ff-a0af-d6952cc9d673', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 29, 29, 'በውስጣቸውም የሚቃጠሉና የሚወርዱ፥ በላይ በኩልና በታች በኩልም የማይቈጠሩ የሰማይ አዕማድን አየሁ።'),
  ('ea49199a-e1d1-57be-a1be-3fb80898ca39', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 30, 30, 'በጕድጓዱም ላይ ቦታን አየሁ፥ ለዚያም ቦታ በላይ ጠፈር በታችም የምድር መሠረት የለውም።'),
  ('82880cf5-e11b-55d5-a0e6-64511fda5537', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 31, 31, 'በላዩም ውኃ የለም፤ ወፎችም የሉበትም፤ ነገር ግን ምድረ በዳ ነው።'),
  ('8d2d499b-8781-5e0f-a8ef-a2a78cb6e5e9', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 32, 32, 'በዚያም እንደሚቃጠሉ ታላላቅ ተራሮች ሰባት ከዋክብትን በሚያስፈራ ሁኔታ አየሁ።'),
  ('5a9c7ba1-c050-5164-abca-094e7a6ba1bd', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 33, 33, 'መልአኩም የሚጠይቀኝ መንፈስ እንደ መሆኑ እንዲህ አለኝ- “ይህ ቦታ የሰማይና የምድር መጨረሻ ነው።'),
  ('f9cf8b54-4677-505e-a2b6-52457e6e67da', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 34, 34, 'ይህም- ለሰማይ ከዋክብትና ለሰማይ ሠራዊት፥ በእሳት ላይ ለሚገለባበጡ ከዋክብትም የግዞት ቤት ሆናቸው።'),
  ('43963e24-e949-5b6d-a3dc-33db7347eee7', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 35, 35, 'እነዚህም በጊዜያቸው አልመጡምና ከመውጣታቸው አስቀድሞ የእግዚአብሔርን ትእዛዝ የተላለፉ ናቸው።'),
  ('6329b682-cf3e-5d82-a655-7c533a151342', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 36, 36, 'በምሥጢር ዘመንም እስከ ኀጢአታቸው መጨረሻ ድረስ ተቈጥቶ አጋዛቸው።”'),
  ('cb0ad067-5b96-5284-a6e6-9b96beda6cac', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 37, 37, 'ዑርኤልም እንዲህ አለኝ- “መላእክት'),
  ('3067f995-09b5-52a9-a942-65143c7a47d5', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 38, 38, 'መንፈሶቻቸውም ብዙ መልክ ሆነው ሰዎችን ያረክሷቸዋል፤ እስከሚፈጸሙባት እስከ ታላቅዋ የፍርድ ቀን ድረስም እንደ አማልክት ለአጋንንት ይሠዉ ዘንድ ሰዎችን ያስትWaቸዋል።'),
  ('8467a0a4-0bc0-55b9-a2f1-2a61ad6defe4', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 39, 39, 'ሴቶቻቸውም የሰማይ መላእክትን አስተው እንደ ሰላማውያት ሴቶች ይሆናሉ።”'),
  ('75017b6a-7ae5-56a0-a506-a96876cb2ffe', '470cddf1-15b8-514c-a4a8-c7b395c6bede', '41cf1969-201b-5c4e-a4fe-c68b3a6b6150', 40, 40, 'እኔ ሄኖክ የሁሉን ፍጻሜ ራእይ ብቻዬን አየሁ፤ እኔም እንዳየሁ ከሰዎች ወገን ያየ የለም።'),
  ('0d0fb534-0e84-51f7-a5bf-161428421ac8', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 1, 1, 'የትጉሃን ቅዱሳን መላእክት ስማቸው ይህ ነው።'),
  ('5bab3dd3-2029-5169-a667-cc6c50c697a3', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 2, 2, 'ከቅዱሳን መላእክት አንዱ ዑርኤል በመብረቅና በነጐድጓድ የተሾመ ነው።'),
  ('0ed53a83-c897-569d-a04d-16ae634893e8', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 3, 3, 'ከቅዱሳን መላእክት አንዱ ሩፋኤል በሰዎች ነፍሳት ላይ የተሾመ ነው።'),
  ('193bdb80-4137-55f5-a58f-7b943a27ec35', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 4, 4, 'ከቅዱሳን መላእክት አንዱ ራጉኤል ስለ ዓለምና ስለ ብርሃናት የሚበቀል ነው።'),
  ('ff6f835a-d13d-55d7-ad6a-d7ab321e03d8', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 5, 5, 'ለሰው በሚያደርገው በጎነት ላይ ለሕዝቡ ታዛዥ ነውና ከቅዱሳን መላእክት አንዱ ሚካኤል ነው።'),
  ('c3d877ff-7aac-58be-ad40-41d638cc33eb', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 6, 6, 'ከቅዱሳን መላእክት አንዱ ሠረቃኤል በሰውነታቸው ኀጢአት በሚሠሩ በሰዎች መናፍስት ላይ የተሾመ ነው።'),
  ('a65134d9-9e11-56ec-a2a0-ef678cebcdba', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 7, 7, 'ከቅዱሳን መላእክት አንዱ ገብርኤል በእባቦች ላይ፥ በገነትና በኪሩቤልም ላይ የተሾመ ነው።'),
  ('90a56cb1-5593-5f36-af84-669b8591f627', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 8, 8, 'የሚሠራ ሥራ እስከሌለበት ቦታ ድረስ ዞርሁ፥ በዚያም የሚያስፈራ ሥራን አየሁ። የተዘጋጀና የሚያስፈራ ምድረ በዳ ነው እንጂ በላይ ጠፈር፥ በታችም መሠረት የለውም።'),
  ('c338d1fb-7a27-5365-ac48-a75ddcc859a2', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 9, 9, 'በዚያም እንደ ታላላቆችና በእሳት እንደሚቃጠሉ ተራሮች በአንድነት በእርሱ ላይ የተጋዙ ሰባት የሰማይ ከዋክብትን አየሁ።'),
  ('3773b51b-7d7f-595e-acd5-9642f6643046', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 10, 10, 'ያንጊዜም “በምን ኀጢአታቸው ታስረው ተግዘዋል? በምንስ ኀጢአታቸው በዚህ ወድቀዋል?” አልሁ።'),
  ('2954ce3a-f0d8-5b44-a380-efe7e82e2aaf', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 11, 11, 'ከእኔም ጋር ያለውና የሚመራኝ ከቅዱሳን መላእክት አንዱ ዑርኤል፥ እንዲህ አለኝ- “ሄኖክ፥ ስለምን ትጠይቃለህ? ስለማንስ ልትረዳ ትፈልጋለህ?'),
  ('9dcd12b1-487c-53ea-a6df-500ca584fd3f', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 12, 12, 'እኒህ የልዑል እግዚአብሔርን ትእዛዝ የተላለፉ መላእክት'),
  ('cd473372-ca80-5d34-ad3f-56e271b92808', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 13, 13, 'ከዚያም ከዚህ ይልቅ ወደሚያስፈራ ወደ ሌላ ቦታ ሄድሁ።'),
  ('afb5b100-008b-5054-a085-89fe6a672faa', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 14, 14, 'በዚያም የሚያስፈራ ሥራን አየሁ፤ በዚያም የሚነድድና የሚንበለበል ታላቅ ቋያ አለ፤ መጋዝም አለበት፥ ወሰኑም እስከ መጨረሻው ውቅያኖስ ነው።'),
  ('cb234755-7731-5d28-ad21-b53aafba3592', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 15, 15, 'ወደዚያው የሚያወርዷቸው ታላላቅ የእሳት አዕማድም አሉ፥ መጠኑንና ከፍታውንም ለማየት አልቻልሁም፤ ዐይኑንም ማየት ተሳነኝ።'),
  ('9152f9a0-948b-52fe-a579-c460950bbfd5', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 16, 16, 'ያንጊዜም “ይህ ቦታ እንዴት የሚያስፈራ ነው? ለማየትም ደዌ ነው” አልሁ።'),
  ('43399e6c-cb02-5fca-ad9b-2717daba3777', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 17, 17, 'ያንጊዜም ከእኔ ጋር ያለው ከቅዱሳን መላእክት አንዱ ዑርኤል መለሰልኝ እንዲህም አለኝ-'),
  ('947c7af7-74e1-5dc2-a9da-2c0a55eab337', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 18, 18, '“ሄኖክ፥ እንደዚህ መፍራትህ ምንድን ነው? ስለዚህ ስለሚያሰፈራው ቦታስ፥ በዚህ መከራ ፊት መደንገጥህ ምንድን ነው?'),
  ('876389eb-acd3-5609-adb1-8ce6fd26a56f', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 19, 19, 'እንዲህም አለኝ- ይህ ቦታ ለመላእክት የግዞት ቤታቸው ነው፤ በዚያም እስከ ዘለዓለም ድረስ ይጋዛሉ።”'),
  ('778c1b53-6e0a-5187-a95c-e815054f8e89', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 20, 20, 'ከዝያም ወደ ሌላ ቦታ ሄድሁ፤ በምዕራብ ረጅምና ታላቅ ተራራን፥ የጸና ዓለትንም አሳየኝ።'),
  ('677e8d1a-af34-5de7-a235-8219e485b7af', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 21, 21, 'ባጠገቡም ያማሩ አራት ቦታዎች አሉ፤ በውስጡም ጥልቅና ሰፊ፥ እንደሚያድጥ ልሙጥ ነገርም ፈጽሞ ልሙጥ አለ፤ ለማየትም ጥልቅና ጨለማ ነው።'),
  ('f5e11ba2-7df2-5cf1-a417-d12aac189ddd', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 22, 22, 'ያንጊዜም ከቅዱሳን መላእክት አንዱ ከእኔ ጋር ያለው ሩፋኤል መለሰልኝ።'),
  ('acbd5fc9-da99-5572-a3d4-9ba69d38c7df', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 23, 23, 'እንዲህም አለኝ- “እኒህ ያማሩ ቦታዎች የሞቱ ሰዎች ነፍሳት ሊሰበሰቡባቸው እነዚህ ለእነርሱ ተፈጠሩላቸው፤ የሰው ልጆች ነፍሳትንም ሁሉ በዚያ ይሰበስባሉ።'),
  ('d7df5286-2791-53a9-adf9-85c38809731d', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 24, 24, 'እስከ ፍርዳቸው ቀንና እስከ ቀጠሮአቸው ጊዜ ድረስ እነርሱን የሚያኖሩባቸውን እነዚህን ቦታዎች ሠሩ።'),
  ('5e5d8d9f-9497-5a7a-a1e4-7106c36790c3', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 25, 25, 'ይኸውም በእነርሱ ላይ እስከሚሆነው ታላቅ መከራ ድረስ ብዙ ዘመን ነው።”'),
  ('a595ed26-1723-53c3-ae52-61463122b6ed', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 26, 26, 'የሰዎች ልጆች ነፍሳትንም አየሁ፤ እነርሱም ሙተው ሳሉ ቃላቸው እስከ ሰማይ ይደርሳል፤ ይከስሳልም።'),
  ('992839aa-3921-5fde-af4a-a2cf8ca0d892', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 27, 27, 'ያንጊዜም ከእኔ ጋር ያለውን ሩፋኤልን ጠየቅሁት፤ እንዲህም አልሁት- “ቃሉ እስከ ሰማይ የሚደርስና የሚከስ ይኸ ነፍስ የማን ነው?”'),
  ('c145c4b9-8fdd-56de-a9ef-a1fd180e3817', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 28, 28, 'እርሱም መለሰልኝ እንዲህም አለኝ- “ይህ ነፍስ ወንድሙ ቃየል በግፍ ከገደለው ከአቤል የወጣ ነው፤ ዘሩ ከምድር ፊት እስኪጠፋ ድረስ፥ የልጅ ልጁም ከሰው ዘር ተለይቶ እስኪጠፋ ድረስ እርሱን ይከስሳል።”'),
  ('4e702b55-2676-5be1-a0a6-37612f053d84', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 29, 29, 'ያንጊዜም ስለ እርሱና ስለ ሁሉም ፍርድ ጠየቅሁ፤ “ለምንስ አንዱ ካንዱ ተለየ?” አልሁ።'),
  ('ac1f0766-71ef-553f-aad9-cf82fadfdbaf', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 30, 30, 'እርሱም መለሰልኝ እንዲህም አለኝ- “እነዚህ ሦስቱ የሞቱ ሰዎች ነፍሳትን ይለዩ ዘንድ ተፈጠሩ፥ የጻድቃንም ነፍስ እንደዚህ ተለየ፤ ይህም በላዩ ብርሃን ያለበት የውኃ ምንጭ ነው።'),
  ('06707e84-8327-5702-a42e-7c3c4066e500', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 31, 31, 'እንደዚሁም ለኃጥአን በሚሞቱበትና በምድር በሚቀበሩበት ጊዜ ሊኖሩበት ቦታ ተፈጠረላቸው።'),
  ('71cc6bf2-fa4b-5ed4-a2d9-946ec2b11f26', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 32, 32, 'በሕይወተ ሥጋ ሳሉ በእነርሱ ላይ ፍርድ አልተደረገባቸውም።'),
  ('5c807038-e774-5967-a995-b5dda05a5866', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 33, 33, 'እስከ ታላቅዋም የፍርድ ቀን ድረስ በዚች ታላቅ ጭንቅ ላይ በዚያ ቦታ ነፍሶቻቸው ይለያሉ፤ ለሚራገሙም ሰዎች እስከ ዘለዓለም መቅሠፍትና ጭንቅ አለባቸው፤ ለነፍሳቸውም በቀል አለባት።'),
  ('d6a497e2-b412-5551-abda-1b4a8536f502', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 34, 34, 'በዚያም ምንም እንኳ ከዓለም ጀምሮ ቢሆንም እስከ ዘለዓለሙ አስሮ ያግዛቸዋል፤'),
  ('2233f4ec-ec69-5f26-a338-c99e668a1c26', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 35, 35, 'እንደዚሁም ለሚከስሱና በኃጥኣን ዘመን በተገደሉ ጊዜ ስለ ጥፋት ለሚያመለክቱ ሰዎች ነፍስ ቦታ ተለየ።'),
  ('702050f7-6d9c-5367-ac79-9fe1ced07904', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 36, 36, 'እንደዚሁም ፍጹማን በደለኞች ኃጥአንን እንጂ ጻድቃንን ላልሆኑ ለክፉዎች ሰዎች ነፍስም ቦታ ተፈጠረ፤ ከበደለኞችም ጋር እንደ እነርሱ ይሆናሉ።'),
  ('afcfccc1-1379-521e-ac87-fd40ab3560d1', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 37, 37, 'ነፍሳቸው ግን በፍርድ ቀን አትገደልም፤ ከዚህም አይነሡም።”'),
  ('5b9ffdc9-c6d0-58d0-afa8-567a73b3ff44', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 38, 38, 'ያንጊዜም የክብር ጌታን አመሰገንሁት፤ እስከ ዘለዓለሙ ድረስ ሁሉን የሚችል የክብርና የጽድቅ ጌታዬም የተመሰገነ ነው አልሁ።'),
  ('2836fafd-9fd0-5cfb-a801-a9a20c2b496a', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 39, 39, 'ከዚያም እስከ ምድር ዳርቻ ድረስ በምዕራብ በኩል ወደ ሌላ ቦታ ሄድሁ።'),
  ('cd00136c-931b-5e67-a81c-80e6fdd9500a', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 40, 40, 'ሳያርፍ የሚነድና የሚሮጥ እሳትንም አየሁ፤ መቸም መች እንዲሁ ነው እንጂ በሌትና በቀን ከሩጫው አይገታም።'),
  ('67ee6047-a54b-5bdd-a112-74476554e8d6', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 41, 41, '“ይህ ዕረፍት የሌለው ምንድን ነው?” ብዬ ጠየቅሁ።'),
  ('d0d509ba-3f8c-5e20-a989-ee7b61dcdccc', '39cf8dda-1c26-5850-a0f5-6527b3588529', 'ae1897d1-41f8-5c9b-a6a6-0c4dbd0de30f', 42, 42, 'ያንጊዜም ከእኔ ጋር ያለው ከቅዱሳን መላእክት አንዱ ራጉኤል መለሰልኝ፥ እንዲህም አለኝ- “ወደ ምዕራብ ሲሮጥ ሩጫውን ያየኸው ይህ የሚነድ እሳት የሰማይ ብርሃን ሁሉ ነው።”'),
  ('318b35bc-0c78-5a1e-a041-52f12a020a4d', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 1, 1, 'ከዚያም ወደ ሌላ ምድራዊ ቦታ ሄድሁ፤ በቀንና በሌሊት የሚቃጠል የእሳት ተራራንም አሳየኝ።'),
  ('cfbcd718-9995-5a52-a96b-2034d56adf68', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 2, 2, 'በዚያም በኩል ሄድሁ፥ የከበሩ ሰባት ተራሮችንም አየሁ።'),
  ('a65b67e4-cf69-55c3-a119-a35addada2bf', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 3, 3, 'ሁሉም አንዱ ካንዱ ልውጥ ነው፤ የከበሩና ያማሩ ድንጋዮችንም አየሁ፥ ሁሉም የከበረ ነው።'),
  ('8e8e43e2-af42-5e2b-ac94-25ea0a17190e', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 4, 4, 'መልካቸውም የበራ ነው፥ ፊታቸውም ያማረ ነው፥ ሦስቱም በምሥራቅ በኩል ናቸው፥ አንዱም ባንዱ ላይ የጸኑ ናቸው።'),
  ('c3912a4c-7f08-517c-a1cf-9080c542967f', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 5, 5, 'ሦስቱም በሰሜን በኩል ናቸው፤ አንዱም ባንዱ ላይ የጸኑ ናቸው፤ ጥልቆች ቆላዎችም አሉ፥ ጠማሞችም ናቸው፥ አንዲቱም አንዲቱን አትቀርባትም።'),
  ('01c330f2-343a-51a3-a8a7-a84dc03eb921', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 6, 6, 'ሰባተኛውም ተራራ በእነዚህ መካከል ነው፥ ቁመታቸው ግን እንደ አትሮንስ ወንበር ሁሉም ይመሳሰላሉ።'),
  ('59d361f8-de00-54eb-a00d-cb26b8e197f6', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 7, 7, 'መዓዛ ያላቸው ዛፎችም ይከቡታል፤ በመካከላቸውም አንድ ዛፍ አለ፥ ከእነርሱ አንዱ ስንኳ ለእኔ የሸተተበት ጊዜ ከቶ የለም።'),
  ('09df83b8-2397-54ef-ad1e-fd2eb543ef34', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 8, 8, 'እንደ እርሱም ያሉ ሌሎች አይሸቱም፤ ከሸቱውም ሁሉ ይልቅ ይሸታል።'),
  ('cc388523-dfcf-5381-a046-dd1aeb4f32a9', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 9, 9, 'ቅጠሉና አበባው፥ እንጨቱም ለዘለዓለም አይጠወልግም።'),
  ('068fa1f4-b209-5073-aa40-07d647b4b4e2', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 10, 10, 'ፍሬውም ያማረ ነው፤ ፍሬው ግን እንደ ዘንባባ ፍሬ ነው።'),
  ('14f9149d-60d7-5cdf-aba6-b83655822bfa', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 11, 11, 'ያንጊዜም “ይህ ዛፍ እነሆ፥ ያማረ ነው፥ ለማየትም ያማረ ነው፥ ቅጠሉም መልካም ነው፥ ፍሬውም ለማየት ፈጽሞ የተወደደ ነው” አልሁ።'),
  ('8ce8e194-2344-5602-acdb-8d5cc64e6f73', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 12, 12, 'ያንጊዜም ከእኔ ጋር ያለው፥ በላያቸውም የተሾመው ከቅዱሳንና ከክቡራን መላእክት አንዱ ሚካኤል መለሰልኝ።'),
  ('c4f941d1-6815-54a2-a13a-2532449f32d6', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 13, 13, 'እንዲህም አለኝ- “ሄኖክ፥ ስለዚህ ዛፍ ሽታ ለምን ትጠይቃለህ? ልታውቅስ ስለምን ትመራመራለህ?”'),
  ('1dd9429f-2ff8-5eec-a85d-58ba4a476cba', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 14, 14, 'ያንጊዜም እኔ ሄኖክ እንዲህ ብዬ መለስሁለት- “ስለ ሁሉ ላውቅ እወዳለሁ፥ ይልቁንም ስለዚህ ዛፍ ላውቅ እወዳለሁ።”'),
  ('7ff8d4d2-094f-5cdc-aaa2-c7b38dac5a54', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 15, 15, 'እርሱም እንዲህ ብሎ መለሰልኝ- “ይህ ያየኸው፥ ራሱ የጌታን ዙፋን የሚመስለው ረጅም ተራራ፥ ቅዱሱና ታላቁ የዘለዓለም ንጉሥ የክብር ጌታ ምድርን በበጎ ሊጐበኛት በወረደ ጊዜ የሚቀመጥበት ዙፋኑ ነው።'),
  ('2c1c5ae8-99b0-5f9a-adae-3ee0e9ba8054', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 16, 16, 'ይህንም የመልካም መዓዛ ዛፍ ጌታ ሁሉን እስከሚበቀልበት እስከ ታላቁ የፍርድ ጊዜና ለዘለዓለም እስከሚፈጸምበት ጊዜ ድረስ አንድ ሰው እንኳ ሊነካው ሥልጣን የለውም።'),
  ('5459bcf9-9c83-5beb-a889-7472a4cb9241', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 17, 17, 'ይህም ለጻድቃንና ለትሑታን ይሰጣል፤ ከፍሬውም ለተመረጡ ሰዎች ሕይወት ይሰጣል።'),
  ('09c3f6da-4498-550e-adff-009eb2ead0da', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 18, 18, 'በዘለዓለማዊው ንጉሥ በጌታ ቤት አንጻር በመስዕ በኩል በቅዱስ ቦታ ይተከላል።'),
  ('26d2c2b3-b68d-519f-af18-1dee634d88f9', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 19, 19, 'ያንጊዜም ደስ ይላቸዋል፥ ሐሤትንም ያደርጋሉ።'),
  ('dc993123-f034-5f1d-ad65-f9531c3dc82d', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 20, 20, 'በየወገናቸውም በቅዱስ ቦታ ሽቱን ያቀርቡለታል፥ አባቶችህ ብዙ ዘመን እንደ ኖሩ እነርሱም በምድር ላይ ብዙ ዘመን ይኖራሉ።'),
  ('9030f334-b2ed-5c19-af09-945498e578e5', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 21, 21, 'በዘመናቸውም ኀዘንና መከራ፥ ድካምና መቅሠፍት አይዳስሳቸውም።”'),
  ('69666c3f-6949-59f3-a614-71c95a0f1698', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 22, 22, 'ለጻድቃን ሰዎች እንደዚህ አዘጋጅትWaልና፥ እንደዚህም ፈጥሮ ይስጧቸው ብሏልና የዘለዓለም ንጉሥ የክብር ጌታን አመሰገንሁት።'),
  ('54572710-d5df-53ba-a1df-2f4f39ad5df8', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 23, 23, 'ከዚያም ወደ ምድር መካከል ሄድሁ፥ የተባረከና የለመለመ፥ ከተቈረጠ ዛፍም አቈጥቍጠው የሚኖሩ ቅርንጫፎች የጋረዱት ቦታን አየሁ።'),
  ('6497cb38-f412-52c9-a501-227b16023260', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 24, 24, 'በዚያም ቅዱስ ተራራን አየሁ፥ ከተራራውም በታች በምሥራቁ በኩል ውኃ አለ፤ የሚፈስሰውም ወደ ሰሜን ነው።'),
  ('00a316ca-7764-5439-a2c8-2bf2dc645c39', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 25, 25, 'በምሥራቅም በኩል ከዚህ የሚረዝም ሌላ ተራራን አየሁ።'),
  ('1ef6f9dd-14d6-5963-a5bd-69afa76ea16c', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 26, 26, 'በመካከላቸውም ጥልቅ ሸለቆ አለ። ስፋትም የለውም፤ በእርስዋም ውኃ ወደ ተራራው ይፈስሳል።'),
  ('c4388445-1ab9-516b-a129-0a08fd141548', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 27, 27, 'በዚህም በሁለተኛው ተራራ ምዕራብ በኩል ከእርሱ የሚያንስ ተራራ አለ። ርዝመትም የለውም፥ በመካከላቸውም በበታቹ ሸለቆ አለ።'),
  ('306b5d2a-2d86-5843-aa33-c761974af961', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 28, 28, 'በሦስቱ ተራሮች ዳርቻ በኩልም ጥልቅ የሆኑና የደረቁ ሌሎች ሸለቆዎች አሉ።'),
  ('c9faafda-3cdb-59b8-acc0-05be0c3442c3', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 29, 29, 'ሸለቆዎች ሁሉ ጥልቆች ናቸው፥ ከጽኑ ዓለት ድንጋይ የተነሣም ስፋት የላቸውም።'),
  ('f288a69b-36d6-5793-ad80-b23d034acb53', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 30, 30, 'በእነርሱ ላይም ዛፍ ይተከላል፥ ስለ ዓለቱም አደነቅሁ፥ ስለ ሸለቆውም አደነቅሁ፤ እጅግም አደነቅሁ።'),
  ('024f0b52-3595-593a-a507-07502d2f459a', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 31, 31, 'ያንጊዜም እንዲህ አልሁ- “የተባረከችና ሁለመናዋ ዛፎችን የተመላች ይህች ምድር ስለምን ናት?'),
  ('874e21d8-1c1b-5fe0-a959-e50aa3a03e0d', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 32, 32, 'ይህችስ በመካከላቸው የተረገመች ሸለቆ ስለምን ናት?”'),
  ('69de53a0-2741-5fb2-a255-389b62c523b8', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 33, 33, 'ያንጊዜም ከእኔ ጋራ ያለው ከቅዱሳን መላእክት አንዱ ዑራኤል መለሰልኝ እንዲህም አለኝ- “ይህች የተረገመች ሸለቆ እስከ ዘለዓለሙ ለተረገሙ ናት።'),
  ('2d13f1ea-7c94-5ea6-a7d5-cfc4f98c34b2', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 34, 34, 'በአንደበታቸውም በእግዚአብሔር ላይ የማይገባ ነገርን የሚናገሩ ሁሉ በዚያ ቦታ ይሰበሰባሉ።'),
  ('75d3f973-9480-540b-a8b7-3ec98d75585b', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 35, 35, 'ስለ ክብሩም ጭንቅ ነገርን ስለ ተናገሩ በዚያ ይሰበሰባሉ፤ በኋለኛውም ዘመን ፍርዳቸው በዚያ ይሆናል።'),
  ('a90fec47-aa43-5869-a979-d3411ab161ab', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 36, 36, 'በእውነት የሚሆን የፍርድ ዐይነትም በጻድቃን ፊት ለዘለዓለም በእነርሱ ላይ ይሆናል።'),
  ('04071646-53a4-50fa-a53d-5cd8818ddf4f', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 37, 37, 'ምሕረትን የሚያደርጉም- የዘለዓለም ንጉሥ የክብር ጌታን በዘመኑ ሁሉ በዚያ ያመሰግኑታል።'),
  ('278f6c73-c553-5647-a3bb-aad3bf8a5cc1', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 38, 38, 'በተፈረደባቸውም ወራት እንዳደላቸው በቸርነቱ ያመሰግኑታል።”'),
  ('318628a1-2843-5c2f-ae7f-b2f54a78de24', 'b968ec6d-af49-5627-ab61-5182119fd807', 'f5183d08-2225-582a-a255-edbcfb3ef783', 39, 39, 'እኔም ያንጊዜ የክብር ጌታን አመሰገንሁት፥ ለገናናነቱም እንደሚገባ ተናገርሁለት፥ ስሙንም ጠራሁ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('43568da5-7d6b-59f0-a67e-5a75b7c2979b', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 1, 1, 'ከዚያም በመድበራ ተራራ መካከል ወደ ምሥራቅ ሄድሁ።'),
  ('309a3bbb-76e2-5ac4-a605-3084bb2751fe', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 2, 2, 'ምድረ በዳውንም ብቻ አየሁ።'),
  ('8d24e3b5-ff9c-51a4-abd7-bf9f0da8af63', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 3, 3, 'ነገር ግን ከዚህ ዘር ዛፎችን የተመላ ነው።'),
  ('35781b11-97cf-54d7-a7b0-5dead2bfcaff', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 4, 4, 'ውኃም ከወደ ላይ ይመነጫል፤ ሻሻቴውም በዝቶ እንደሚንሻሽ በላዩ ይታያል።'),
  ('82e5a8ce-07bd-5794-a424-727b0f82b1bc', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 5, 5, 'በመስዕ በኩል እንደሚፈስስ ወደ ምዕራብ ይፈስሳል፤ ከአራቱም ማዕዘን ይወጣል፥ ከዚያም ውኃና ጠል አለ።'),
  ('53cfe525-80ff-52c2-acfd-d6d0ec95b286', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 6, 6, 'ከመድበራም ወደ ሌላ ቦታ ሄጄ ወደዚህ ተራራ ምሥራቅ ቀረብሁ።'),
  ('28ff640c-864c-58cd-ac51-2de3326c2190', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 7, 7, 'በዚያም የፍርድ እንጨቶችን አየሁ፤ ይልቁንም የነጭ ዕጣንና የከርቤ መዓዛ ያላቸውን ዛፎች አየሁ፥ ዛፎቹም አይመሳሰሉም።'),
  ('334ebd5e-5e38-5e4e-a6bb-2561e58c208a', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 8, 8, 'በእርሱ ላይ፥ በእነርሱም ላይ፥ ሩቅም ባይደለ በምሥራቅ ተራራ ላይ፥'),
  ('2d23c465-33fa-5188-abd3-5222ea4fe3af', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 9, 9, 'የማይገታ ውኃ ያለባቸው የሸለቆዎችን ሌላ ቦታ አየሁ።'),
  ('178f07ba-91c8-5dc2-aa7e-1dfd2587ed3f', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 10, 10, 'ያማረ ዛፍንም አየሁ፤ ሽታውም እንደ ለውዝ ሽታ ነው።'),
  ('c8f8f44a-aebd-55df-ab61-0193d1b06002', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 11, 11, 'በእነዚህ ሸለቆዎች አጠገብም መዓዛ ያለው ሽቱን አየሁ።'),
  ('edda9058-3c60-55ed-a4e5-ae1ee8c0b60e', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 12, 12, 'ከእነዚህም በላይ ወደ ምሥራቅ ቀረብሁ፥ በውስጡ ዛፎች ያሉበት ሌላ ተራራንም አየሁ።'),
  ('2c989cab-d26a-5561-a905-9c21ac7cd0af', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 13, 13, 'ከእርሱም ስሙ ሰሪራ፥ ከልበኔም እንደሚባል እንደ ነቄጥሮ ያለ ውኃ ይፈስሳል።'),
  ('0a0062ca-5bc9-5b33-ac1f-72f2222c6308', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 14, 14, 'በዚያም ተራራ ላይ ሌላ ተራራን አየሁ፤ በውስጡም ዋግራ የሚባሉ ዛፎች አሉበት።'),
  ('9f20f7b5-dff5-5937-a7f4-6714517b137d', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 15, 15, 'እነዚያም ዛፎች እንደ ከርካዕ ምሉኣንና ጽኑዓን ናቸው፤ ይህንም ፍሬ በያዙት ጊዜ ከሽቱ ሁሉ ይበልጣል።'),
  ('98446338-2278-5ddc-a142-235d9ff8d168', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 16, 16, 'ከእነዚህም ሽቱዎች በኋላ በተራሮች ላይ ወደ መስዕ ስመለከት፥'),
  ('f95ce365-b743-5e3b-a14b-4e54ec53b5b9', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 17, 17, 'ያማረ ሽቱን፥ ቀናንሞስና ፕፕሬ የሚባል መዓዛ ያላቸው ዛፎችንም የተመሉ ሰባት ተራራዎችን አየሁ።'),
  ('bfb0d678-af57-5aac-a246-3817064ff7cd', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 18, 18, 'ከዚያም በእነዚያ ተራሮች ራስ ላይ ርቄ ወደ ምሥራቅ ሄድሁ።'),
  ('4d2d4cb1-e411-5f29-aa27-6d0f6a49930a', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 19, 19, 'በኤርትራ ባሕርም ሄድሁ፤ ከዚያም የራቅሁ ሆንሁ።'),
  ('48b5d7ae-522e-56e3-a563-08eb04e3cf26', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 20, 20, 'ዙጡኤል በሚባል መልአክ ላይም አልፌ ሄድሁ፤ ወደ ጽድቅ ገነትም መጣሁ።'),
  ('3d3cccbe-1920-55ac-ac7f-0ccac7545eb5', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 21, 21, 'ከእነዚህ ዛፎችም ወዲያ ብዙዎችንና ታላላቆች ዛፎችን በዚያ በቅለው አየሁ።'),
  ('84935ed4-4771-512e-ad59-adf0bdf186af', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 22, 22, 'ሽታቸውም ያማረ ሲሆን ታላላቆች ነበሩ። ብርሃናቸውም ብዙ ነው፤ እነርሱም ያበራሉ።'),
  ('9fe28f16-73d2-534b-a9ad-6e3b0051d579', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 23, 23, 'ከእርሱም በልተው ታላቅዋን ጥበብ የሚያውቁበት የጥበብ ዛፍን አየሁ፤ እርሱም ተረርቃሞ ይመስላል።'),
  ('5c40d1c6-93bf-50ae-a134-68801f76c6c1', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 24, 24, 'ፍሬውም እንደ ወይን ዘለላ እጅግ ያማረ ነው፤ የዚያም ዛፍ ሽታው ሄዶ ከሩቅ ይደርሳል።'),
  ('feb9c162-7247-593b-a5c4-7be7c3602daa', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 25, 25, 'እንዲህም አልሁ- “ይህ ዛፍ መልካም ነው፤ መልኩም ያማረና ደስ የሚያሰኝ ነው።”'),
  ('b6162d10-7422-571c-a5a6-6c9387631a94', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 26, 26, 'ከእኔ ጋራ ያለው መልአክ ቅዱስ ሩፋኤልም መለሰልኝ፥ እንዲህም አለኝ-'),
  ('5be57c6d-61c6-590a-ae3b-fbcd406834d1', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 27, 27, '“የቀደሙህ ሽማግሌው አባትህና ባልቴቷ እናትህ ከእርሱ የበሉ የጥበብ ዛፍ ይህ ነው።'),
  ('2bba1722-db5b-5752-ac7f-1213cbd96172', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 28, 28, 'ጥብብንም ዐወቋት፤ ዐይኖቻቸውም ተገለጡ፤ ዕራቁታቸውንም እንዳሉ ዐወቁ፤ ከገነትም ተሰደዱ።”'),
  ('6925b252-b0cd-5e86-af4f-a315b58e2615', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 29, 29, 'ከዚያም እስከ ምድር ዳርቻ ድረስ ሄድሁ፤ በዚያም ታላላቅ አውሬዎችን አየሁ።'),
  ('62937813-70fe-567b-a314-b245cb00a920', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 30, 30, 'አንዱ ከሌላው ልዩ ነው፤ የወፎችም ፊታቸው ይለያያል፥ መልካቸውም፥ ቃላቸውም አንዱ ከሌላው ይለዋወጣል።'),
  ('d4349a53-b242-527f-a0bb-b8ca001e2bd5', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 31, 31, 'ከእነዚህ አውሬዎችም በስተምሥራቅ ሰማዩ በላዩ ያረፈበትን የምድር ዳርቻንና የተከፈቱ ደጆችን አየሁ።'),
  ('d9bacd4e-85f2-53bf-a8cf-a20047bcd577', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 32, 32, 'የሰማይ ከዋክብትም እንዴት እንደሚወጡ አየሁ፤ ከእርሱ የሚወጡባቸው ደጃፎችንም ቈጠርሁ።'),
  ('b390e3d8-67aa-5bad-ac4b-048acba3108f', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 33, 33, 'የእያንዳንዱን መውጫ ሁሉ በየቍጥራቸው፥ በየስማቸውና በየደረጃቸው፥ በየመኖሪያቸው፥ በየጊዜያቸውና በየወራታቸው ከእኔ ጋር ያለው መልአኩ ዑርኤል እንዳሳየኝ ጻፍሁ።'),
  ('282ba277-eae6-5a8f-ac0c-9558a9fc3464', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 34, 34, 'ሁሉንም ለእኔ አሳየኝ፥ እርሱም ጻፈው፤ ዳግመኛም ስማቸውን፥ ሥርዐታቸውንና ሥራቸውን ጻፈልኝ።'),
  ('97d83e54-5feb-5c64-a2d9-2e0201b442bf', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 35, 35, 'ከዚያም በምድር ዳርቻ ወደ መስዕ ሄድሁ፤ በዚያም በምድር ሁሉ ዳርቻ ታላቅና የከበረ ተአምራትን አየሁ።'),
  ('b39e18fd-6815-5e52-ac35-ecc472c5a077', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 36, 36, 'በዚያም የተከፈቱ ሦስት የሰማይ ደጃፎችን በሰማይ አየሁ፤ ከእነዚያም በየአንዳንዱ ነፋሳት ይወጣሉ።'),
  ('73a0dcc6-12a3-5872-a28e-cc53ad7f469f', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 37, 37, 'በመስዕ በኩል ነፋስ በነፈሰ ጊዜ ቀቅና በረዶ፥ ውርጭና አመዳይ፥ ጤዛና ዝናምም ይፈስሳል፤ ካንዲቱም መስኮት በበጎ ይነፍሳል።'),
  ('49cf15fb-ef8c-55e8-ae28-664b98b1db21', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 38, 38, 'በሁለቱ መስኮቶችም በኀይል በነፈሱ ጊዜ በምድር ላይ ጭንቅ ይሆናል። በኀይልም ይነፍሳሉ።'),
  ('152d0ff1-e41f-567a-ae05-ab4b91a0be82', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 39, 39, 'ከዚያም በምድር ዳርቻ ወደ ምዕራብ ሄድሁ፤ በዚያም በመስኮቶቹ ልክና በመውጫው ልክ በምሥራቅ እንዳየሁ የተከፈቱ ሦስት መስኮቶችን አየሁ።'),
  ('01abcca8-d56d-5ad5-a900-685cc32a3e42', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 40, 40, 'ከዚያም በምድር ዳርቻ ወደ አዜብ ሄድሁ።'),
  ('3511a546-aed3-58b3-a36f-af536a284266', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 41, 41, 'በዚያም የተከፈቱ ሦስት የሰማይ መስኮቶችን አየሁ፤ ከዚያም ከአዜብ ዋዕይ ጤዛና ዝናም፥ ነፋስም ይወጣል።'),
  ('03a7d3c2-5360-54fd-adb2-cc04e94f59ec', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 42, 42, 'ከዚያም በሰማይ ዳርቻ ወደ ምሥራቅ ሄድሁ።'),
  ('1d465115-6321-5018-a8aa-2b33702c565d', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 43, 43, 'በዚያም በምሥራቅ በኩል የተከፈቱ ሦስት የሰማይ ደጃፎችን አየሁ።'),
  ('9a7060b1-b729-5bc6-a005-94cdbbc980ed', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 44, 44, 'በእነዚህ በትናንሽ ደጃፎችም በእያንዳንዱ በኩል ታናናሾች የሰማይ ከዋክብት ያልፋሉ።'),
  ('fff667ba-013a-52a1-abbb-fdab6a86f8ea', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 45, 45, 'በታየችላቸውም ጎዳና ወደ ምዕራብ ይሄዳሉ።'),
  ('de47a2b0-ce0f-5066-aaa1-a0764fe7e72c', '3c679a4b-42dd-5c98-a059-47c5b1d2d335', 'efd76f3d-d2f8-5e80-a523-7c45a5c73641', 46, 46, 'ይህንም ባየሁ ጊዜ አመሰገንሁ፤ የፍጥረቱንም ገናናነት ለመላእክቱና ለሰዎች ነፍሳት ይገልጥ ዘንድ፥ ሥራውንም ያመሰግኑ ዘንድ፥ ፍጥረቱም ሁሉ የኀይሉን ሥራ ያዩ ዘንድ፥ ታላቅ የሆነ የእጁንም ሥራ ያከብሩ ዘንድ፥ እርሱንም ለዘለዓለሙ ያመሰግኑት ዘንድ ታላላቅና የከበሩ ተአምራትን ያደረገ የክብር ጌታን ሁልጊዜ አመሰግነዋለሁ።'),
  ('42af095a-48d8-5260-a6fe-8b9e6b3576ed', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 1, 1, 'ሁለተኛ ጊዜ ሄኖክ ያየው ራእይ፤ የአዳም ልጅ፥ የሴት ልጅ፥ የሄኖስ ልጅ፥ የቃይናን ልጅ፥ የመላልኤል ልጅ፥ የያሬድ ልጅ ሄኖክ ያየው የጥበብ ራእይ ይህ ነው።'),
  ('818a393f-ac5c-5300-a66e-3e44c12d1838', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 2, 2, 'በምድር ላይ ለሚኖሩ ሰዎች እናገረው ዘንድ የጀመርሁት የጥበብ ነገር መጀመሪያ ይህ ነው።'),
  ('882ef89c-1983-51f6-afb8-f2f2d1f30d41', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 3, 3, 'የቀድሞ ሰዎች፥ ስሙ፤ በኋላም የተነሣችሁ ሰዎች፥ በመናፍስት ጌታ ፊት የምናገረው የቅዱሱን ነገር አስተውሉ።'),
  ('f10c9435-ed69-51a1-a264-110be09c0c7c', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 4, 4, 'እነዚህ “መጀመሪያው ይሻላል” ይላሉ፤ እኛም በኋላ የተነሣን ሰዎች የጥበብ መጀመሪያን አንከለክልም።'),
  ('6ce17dd7-a8c0-57ba-a01f-1e0d0066e3a6', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 5, 5, 'እኔ እንዳሰብሁት የዘለዓለም የሕይወት እድል ከእርሱ የተሰጠኝ የመናፍስት ጌታ እንደ ወደደ የያዝሁት ጥበብ ከመናፍስት ጌታ ፊት እስከ ዛሬ ድረስ አልተሰጠኝም ነበር።'),
  ('f7d9a7b0-bede-5bb6-a1ae-544aeb6a9d3a', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 6, 6, 'ሦስት ምሳሌዎችም ተገለጡልኝ።'),
  ('f10da25e-caa2-52d4-a269-5d74251519d9', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 7, 7, 'እኔም በምድር ለሚኖሩ ሰዎች እነግራቸው ጀመር።'),
  ('02689268-6425-57e2-aeff-f75a3c32cedd', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 8, 8, 'መጀመሪያው ምሳሌ ይህ ነው፥ የጻድቃን ማኅበር በተገለጠ ጊዜ፥ ኃጥኣንም በኀጢአታቸው በተፈረደባቸው ጊዜ፥ ከምድር ፊትም በታወኩ ጊዜ፥'),
  ('8bcaaa4f-d684-5eb7-a754-95c53753e6cc', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 9, 9, 'በመናፍስት ጌታ ዘንድ ሥራቸው በጸናላቸው በተመረጡ ጻድቃን ፊት ጻድቁ በተገለጠ ጊዜ፥'),
  ('73a23387-2b8a-58d5-a7b9-7985f8df59cc', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 10, 10, 'በምድር ላይ ለሚኖሩ ለጻድቃንና ለተመረጡ በተገለጠ ጊዜ፥'),
  ('e42164ff-dcc3-5a6f-af14-6e945ad6e84b', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 11, 11, 'የኀጢአተኞች ማደሪያ ወዴት ነው? የመናፍስት ጌታን የካዱት ሰዎችስ ማረፊያቸው የት ነው?'),
  ('35958931-5614-5c3b-a27b-b4ca0b65fdd6', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 12, 12, 'ጥንቱን ባልተወለዱ በተሻላቸው ነበር፤ የጻድቃንም የተሰወሩ ክብሮቻቸው በተገለጡ ጊዜ በኃጥአን ይፈረድባቸዋል፤ ከጻድቃንና ከተመረጡት ሰዎች ፊትም የተነሣ ዝንጉዎች ይታወካሉ።'),
  ('7dc2fda3-fada-5365-a478-21f3e2175f76', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 13, 13, 'ከዛሬም ጀምሮ ምድርን የሚገዟት ሰዎች አዛዦችና ልዑላን አይሆኑም።'),
  ('d82348f2-9938-5912-adbf-fba243a532db', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 14, 14, 'የቅዱሳንንም ፊት ማየት አይችሉም። ለቅዱሳን ጻድቃንና ለተመረጡ ሰዎች ፊት የመናፍስት ጌታ ክብሩ ተገልጧልና።'),
  ('c2f7df0a-84f5-516b-a914-c3cd029daf2b', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 15, 15, 'ያንጊዜም አዛዦች ነገሥታቱ ይጠፋሉ፥ በጻድቃንና በቅዱሳን እጅም ይሰጣሉ።'),
  ('3d58c0d5-2c9c-5295-aa1c-51c2530fbb97', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 16, 16, 'ከዚያ ወዲያ የእነርሱ ሕይወት ተፈጽሞአልና በመናፍስት ጌታ ዘንድ ለእነርሱ የሚያማልድ የለም።'),
  ('62adafb3-9d8e-5543-a101-5736a5e781f3', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 17, 17, 'በዚያም ወራት እንዲህ ይሆናል፥ የተመረጡና ቅዱሳን ልጆች'),
  ('ec62127b-7414-5c51-a0af-9e02a9c3a2d4', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 18, 18, 'በዚያም ወራት ሄኖክ የቅንዐትና የቍጣ መጻሕፍትን፥ የችኮላና የሁከት መጻሕፍትንም ያዘ።'),
  ('2732fcd2-8e03-5a3d-a39f-36fff15e6474', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 19, 19, 'የመናፍስት ጌታም ምሕረት አይደረግላቸውም አለ።'),
  ('48e73740-9cdb-5d1a-a9d6-619f2c79a1b9', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 20, 20, 'በዚያም ጊዜ ደመናና ጥቅል ነፋስ ከምድር ፊት ነጥቆ በሰማያት ዳርቻ አኖረኝ።'),
  ('ec6444a4-7a04-5623-a536-95af7bc1a69f', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 21, 21, 'በዚያም ሌላ ራእይ አየሁ፤ የጻድቃንን ማደሪያቸውንና የቅዱሳንን ማረፊያቸውን አየሁ።'),
  ('9c13b026-0091-589c-aaba-69976cd57c44', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 22, 22, 'በዚያም ዐይኖቼ ከመላእክት ጋራ ማደሪያቸውን፥ ከቅዱሳንም ጋር ማረፊያቸውን አዩ።'),
  ('c354a4ba-6991-5df6-a4b0-d3e3a9637145', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 23, 23, 'ስለ ሰው ልጆች ይለምናሉ፥ ይማልዳሉ፥ ይጸልያሉም።'),
  ('51fb0c9d-a264-5de9-a697-c12e5675bea0', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 24, 24, 'ጽድቅም በፊታቸው እንደ ውኃ ይፈስሳል፤ ምሕረትም በምድር እንደ ጠል ይሆናል፤ በመካከላቸውም ለዘለዓለሙ እንዲህ ይሆናል።'),
  ('172840ab-42d8-59e5-ae7a-b0cc521baf2a', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 25, 25, 'በዚያም ወራት ዐይኖቼ በጽድቅና በሃይማኖት የተመረጡ ሰዎችን ቦታ አዩ።'),
  ('48fdc3c8-ae42-5d57-ad6f-0f40d9c99c8d', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 26, 26, 'በዘመናቸውም ጽድቅ ይሆናል፥ ለጻድቃንና ለተመረጡትም ለዘለዓለሙ በእርሱ ፊት ቍጥር የላቸውም።'),
  ('d4e773b2-09e7-5f96-a786-8658414f3607', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 27, 27, 'ከመናፍስት ጌታ ክንፍ በታችም ማደሪያቸውን አየሁ።'),
  ('05698253-dd59-5402-a4d5-db19bc105d1f', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 28, 28, 'ጻድቃንና የተመረጡትም ሁሉ በፊቱ እንደ እሳት ብርሃን ያበራሉ።'),
  ('29243fad-58b1-5837-a08b-141386f25c73', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 29, 29, 'አፋቸውም በረከትን ይሞላል፥ ከንፈሮቻቸውም የመናፍስት ጌታን ስም ያመሰግናሉ።'),
  ('9cb4f298-9ed7-5b30-a68a-8a8d044a7dc0', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 30, 30, 'ጽድቅም በፊቱ አያልቅም፥ ርትዕም በፊቱ አይፈጸምም።'),
  ('fe1b0366-d57e-51a0-abcb-2a4dcddddc1c', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 31, 31, 'በዚያም እኖር ዘንድ ወደድሁ፥ ነፍሴም ያን ቦታ ወደደችው።'),
  ('a33af0f8-eae8-5a7c-a574-938021a30d04', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 32, 32, 'በመናፍስት ጌታ ፊት ስለ እኔ እንዲህ ጸንቶአልና ጥንቱን እድል ፋንታዬ በዚያ ሆነ።'),
  ('4d4d6333-9a9f-5ba1-a625-6373d562b8fd', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 33, 33, 'በዚያም ወራት የመናፍስት ጌታን ስም አመሰገንሁ፥ ከፍ ከፍም አደረግሁ፤ የመናፍስት ጌታም በበረከትና በክብር እንደ ወደደ እርሱ አጽንቶኛልና በረከትንና ክብርን ሰጠሁ።'),
  ('fdcfef1e-390f-550e-aa80-55827aede137', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 34, 34, 'ቈይቶም ዐይኖቼ ያን ቦታ አዩ።'),
  ('5817dfab-0568-50ba-a0bc-89fe0756fae0', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 35, 35, 'እንዲህም እያልሁ አከበርሁት፥ አመሰገንሁትም- “ቡሩክ ነው፥ ከጥንትም ጀምሮ እስከ ዘለዓለሙ ይመስገን።'),
  ('b42e673b-83d2-5267-a014-183305a5adbd', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 36, 36, 'በፊቱም ፍጻሜ የለም።'),
  ('e6234468-2ce7-51fa-a03b-4532d6470f6b', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 37, 37, 'ዓለም ሳይፈጠር ይህ ዓለም ምን እንደ ሆነ እርሱ ያውቃል፤ ለልጅ ልጅ ዘመን የሚሆነውንም ነገር ያውቃል።'),
  ('91a7bfaa-da08-53e0-a799-895aa6c0bb97', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 38, 38, 'የማያንቀላፉ ያመሰግኑሃል፥ በጌትነትህም ፊት ይቆማሉ።'),
  ('98a22219-4cd5-57f8-a547-2fe609e64e87', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 39, 39, 'የመናፍስት ጌታ ቅዱስ፥ ቅዱስ፥ ቅዱስ ነህ፥ ፍጥረትህም'),
  ('494aec56-58cd-5ea1-a16f-66b4bcbab9ce', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 40, 40, 'በዚያም የማያንቀላፉትን ሁሉ በፊቱ ቁመው ሲያመሰግኑ ዐይኖቼ አዩ።'),
  ('dae983db-0130-570c-acd9-083d2ff312e4', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 41, 41, '“አንተ ቡሩክ ነህ፥ የመናፍስት ጌታም ስም ለዘለዓለም ቡሩክ ነው” ይላሉ።'),
  ('c6dfdb0e-bfc0-5d33-a756-01cb498ec752', 'f0e3261e-1efb-5a3f-a517-0541d71f0f70', 'cdd3a0ea-2e2d-5119-a981-a61821d9870c', 42, 42, 'ማየት እስኪሳነኝም ድረስ ፊቴ ተለወጠ።'),
  ('58f588db-14f8-5f0f-a779-836a8ac54c91', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 1, 1, 'ከዚህም በኋላ ፈጽመው የበዙ፥ የብዙ ብዙ የሚሆኑ መላእክትን አየሁ፤ በመናፍስት ጌታ ፊት የሚቆሙ መላእክትም ቍጥርና ግምት የላቸውም።'),
  ('e60b1d0d-4f1a-5a94-ad61-34e73ea54547', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 2, 2, 'በመናፍስት ጌታ አራት ክንፎችም ከሚቆሙት የተለዩ ሌሎች አራት ገጻትን አየሁ።'),
  ('81537350-90e9-5cea-ad8c-0629e2642182', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 3, 3, 'ስማቸውንም ዐወቅሁ፤ ስማቸውንም የነገረኝ ከእኔ ጋራ የመጣው መልአክ ነው።'),
  ('1f9db657-11a7-51af-adc6-8f7fdb634997', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 4, 4, 'የተሰወረውንም ሁሉ ገለጠልኝ፥ የእነዚያን የአራቱን ገጻት ቃላትም በክብር ጌታ ፊት ሲያመሰግኑ ሰማሁ።'),
  ('faf66ac3-f375-5c62-acce-8ed7833f1bc8', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 5, 5, 'መጀመሪያውም ቃል የመናፍስት ጌታን ለዘለዓለሙ ያመሰግነዋል።'),
  ('187f0d91-cf69-5bc8-a1ed-341ec9cb834e', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 6, 6, 'ሁለተኛውንም ቃል የተመረጠውንና በመናፍስት ጌታ የታመኑ ምርጦችን ሲያመሰግናቸው ሰማሁ።'),
  ('929ec1d1-e220-528d-ae6d-535737214138', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 7, 7, 'ሦስተኛውንም ቃል በምድር ስለሚኖሩ፥ በመናፍስት ጌታ ስምም ስለሚማልዱ ሰዎች ሲለምንና ሲጸልይ ሰማሁ።'),
  ('6832649f-2920-5b96-a9b5-fa8fc5385ff2', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 8, 8, 'አራተኛውንም ቃል ሰይጣናትን አስወጥቶ ሲሰዳቸው ሰማሁ።'),
  ('33fc9ef1-e186-550f-a7e1-1343d62399bf', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 9, 9, 'በምድር የሚኖሩ ሰዎችንም ያጣሏቸው ዘንድ ወደ መናፍስት ጌታ እንዲገቡ አይተዋቸውም።'),
  ('0fd6427b-b765-560a-afc8-4a66a5061314', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 10, 10, 'ከዚህም በኋላ ከእኔ ጋራ የሚሄደውን፥ የተሰወረውንም ሁሉ የገለጠልኝን የሰላም መልአክ፥'),
  ('bcb2bc13-ec82-526b-ab61-6544c4a49dd9', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 11, 11, 'ያየኋቸውና ቃላቸውን የሰማኋቸው፥ የቈጠርኋቸውም እነዚህ አራቱ ገጻት እነማን እንደ ሆኑ ጠየቅሁት።'),
  ('231bae7c-d6b5-5e89-a54b-31b28946eef3', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 12, 12, 'እንዲህም አለኝ- “ይህ መጀመሪያው ቃል ይቅር የሚልና ከመዓት የራቀ ቅዱስ ሚካኤል ነው።'),
  ('5225f0e1-9f85-55e9-adff-0c3eb72716c9', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 13, 13, 'ሁለተኛውም በበሽታው ሁሉ ላይና በሰው ልጆች ቍስል ላይ የተሾመ ቅዱስ ሩፋኤል ነው።'),
  ('3adda24b-d3ed-56a2-a2ab-5ae52f0f8a19', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 14, 14, 'ሦስተኛውም በሠራዊት ሁሉ ላይ የተሾመ ቅዱስ ገብርኤል ነው።'),
  ('8a7a52a7-09db-5ae1-a038-7074a83e645a', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 15, 15, 'አራተኛውም የዘለዓለም ሕይወትን ለሚወርሱ ሰዎች ተስፋ በንስሓ ላይ የተሾመ ፋኑኤል ነው።'),
  ('5b079a9e-6719-59a5-ae00-dee5775c391d', '8206777e-19f3-5f2e-a8cb-f2e203cc308f', 'f7eb49b9-f2ce-595a-a42b-a755b8692cf7', 16, 16, 'እኒህም አራቱ የልዑል እግዚአብሔር መላእክት ናቸው፤ በዚያም ወራት አራቱን ቃላት ሰማሁ።'),
  ('38324c00-c7a5-55e4-a5d7-27cf16842ffb', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 1, 1, 'ከዚህም በኋላ የሰማያትን ምሥጢሮች ሁሉ አየሁ።'),
  ('5efe5466-b05a-57a8-a8c3-908bab4cd029', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 2, 2, 'መንግሥት እንዴት እንደምትከፈል፥ የሰዎች ሥራም በሚዛን እንደሚመዘን አየሁ።'),
  ('6d0147ca-48bb-5838-a72d-04c213c78a7c', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 3, 3, 'በዚያም የተመረጡትን ሰዎች ማደሪያቸውን፥ የጻድቃንንም ማደሪያቸውን አየሁ።'),
  ('9cd608a6-41f4-570e-af46-59851f26348e', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 4, 4, 'ዐይኖቼም የመናፍስት ጌታን ስም የካዱ ኃጥአን ሁሉ ከዚያ ሲሰደዱ አዩ።'),
  ('14bb1f58-6a71-58db-a196-73d76a751f5d', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 5, 5, 'ስበውም ያወጧቸዋል፥ ከመናፍስት ጌታ በምትወጣ መቅሠፍትም መቆም የላቸውም።'),
  ('a88c97f9-8bb3-58b5-ac80-e2f52ed42e6e', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 6, 6, 'በዚያም የመብረቆችንና የነጐድጓድን ምሥጢራት፥ በምድርም ላይ ይነፍሱ ዘንድ እንዴት እንደሚከፈሉ የነፋሳትን ምሥጢራት፥ የደመናና የጠል ምሥጢራትንም አየሁ።'),
  ('ab207010-56d5-56d3-aeed-a88d68bdb3d8', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 7, 7, 'በዚያም ቦታ የሚወጡበትን አየሁ፥ ከዚያም የምድር ትቢያን ይጠግባሉ።'),
  ('d11d2290-8169-55d7-a4e8-7327851eb8af', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 8, 8, 'በዚያም የተዘጉ መዛግብትን አየሁ፤ ከእነዚያም ነፋሳት ይከፈላሉ።'),
  ('49b5e6cd-c64a-5946-a94a-d67282b49f51', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 9, 9, 'የበረድን መዝገብና የጉምን መዝገብ፥ የደመናዎችንም መዝገብ አየሁ፤ ደመናውም ከጥንት ጀምሮ ከምድር በላይ ይኖራል።'),
  ('31fb6244-406a-5300-a426-ee4616287c7d', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 10, 10, 'የፀሐይና የጨረቃ መዛግብትንም ከየት እንደሚወጡና ወዴት እንደሚገቡ አየሁ፤ አመላለሳቸውም ብሩህ ነው።'),
  ('85a4f59d-1f4e-5eed-ad10-8ebd79d20454', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 11, 11, 'አንዱም ከሌላው እንደሚከብር አየሁ፥ አካሄዳቸውም የከበረ ነው። ቀን አያሳልፉም፥ ከመሄዳቸውም አይጨምሩም፥ አያጐድሉምም።'),
  ('6f1b5cda-a5ea-5cb6-a794-eaad199d350d', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 12, 12, 'ጸንተው በሚኖሩበት ሥርዐትም አንዱ ከሌላው ጋር ሃይማኖታቸውን ይጠብቃሉ።'),
  ('5b21e824-d302-5ed1-a42c-c33e1f1480c0', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 13, 13, 'ፀሐይ ከሁሉ አስቀድሞ ይወጣል፤ በመናፍስት ጌታ ትእዛዝም ጎዳናውን ያደርጋል፤ ስሙም ለዘለዓለም ጸንቶ ይኖራል።'),
  ('dfb95b62-1078-50b2-afa9-a084d502daa6', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 14, 14, 'ከዚህም በኋላ የተሰወረና የተገለጠ የጨረቃን ጎዳና አየሁ፥ የጎዳናውንም መሄጃ በዚያ ቦታ በሌሊትና በቀን ይጨርሳል።'),
  ('29b8c25d-81c8-5f0c-ad93-037689bcb319', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 15, 15, 'በመናፍስት ጌታ ፊትም አንዱ ሁለተኛውን ያየዋል።'),
  ('943ba970-d192-5072-ab67-88caa2a86e58', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 16, 16, 'ለእነርሱ ዕረፍታቸው ምስጋናቸው ነውና ያመሰግናሉ፥ ያከብራሉም፤ አያርፉምም፥ ለሚያበራ ፀሐይ ለበረከትና ለመርገም ብዙ መለዋወጥ አለውና።'),
  ('bb0ce3e0-2710-5e8d-a17f-69ac0b097f88', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 17, 17, 'የጨረቃ ጎዳና መመላለሻም የብርሃንና የጨለማ ማእከልን በፈጠረ በመናፍስት ጌታ ስም ለጻድቃን ብርሃን ነው፤ ለኃጥአን ግን ጨለማ ነው።'),
  ('747b77e8-ed28-506e-a15b-4e7bf2aa970d', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 18, 18, 'ለሰውም ዕውቀትን አደለ፥ በጽድቁም ስም የጻድቃንን ዕውቀት አጸና።'),
  ('0ce194c8-0f0a-5fc3-a797-33fc60556a57', '177adde2-f841-5729-a334-86745c0094d8', 'b4a3e831-b930-563a-a231-617a4f2364a3', 19, 19, 'አለቃው አይከለክልም፥ ንጉሡም መከልከል አይችልም፥ ሁሉን የሚመረምር ፈራጅ አለና፤ እነዚህንም ሁሉ እርሱ በፊቱ ይገዛል።'),
  ('2d6cf5de-6436-508b-a754-283e4deea6de', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 1, 1, 'ጥበብ የምታድርበትን ቦታ አላገኘችም፤ ማደሪያዋም በሰማያት አለ።'),
  ('13ed0b16-b24e-59da-af5b-f47ee440b50e', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 2, 2, 'ጥበብ በሰው ልጆች ታድር ዘንድ ወጣች፤ ማደሪያንም አላገኘችም፤ ጥበብም ወደ ቦታዋ ተመለሰች፤ በመላእክትም መካከል አደረች።'),
  ('104a0afe-812a-5a97-a83f-cc3aa8c75f0f', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 3, 3, 'ዐመፃ ከመዛግብትWa ወጣች፤ ያልወደደችውን አገኘች፤ ዝናም በምድረ በዳ፥ ጠልም በተጠማች ምድር እንደሚያድር በእነርሱ አደረች።'),
  ('822aed8f-0073-560d-a4c2-83f51b37df13', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 4, 4, 'ሌሎች መብረቆችንና የሰማይ ከዋክብትንም አየሁ።'),
  ('e13887d8-5878-5188-a796-528c25e67115', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 5, 5, 'ሁሉንም በየስማቸው እንደሚጠራቸው፥ እነርሱም እንደሚሰሙት አየሁ።'),
  ('95b80dde-b805-5cea-a87f-9a619b897205', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 6, 6, 'በብርሃናቸውና በቦታቸው ስፋት ይመዘኑ ዘንድ የጽድቅ ሚዛኖችንም አየሁ።'),
  ('b081e408-e934-53a4-a57c-d1cadd9a451b', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 7, 7, 'የፍጥረታቸውንና የመመለሻቸውንም ቀን አየሁ፤ መብረቅ መብረቅን ይወልዳል። አመላለሳቸውም በመልአኮቻቸው ቍጥር ነው፤ ሃይማኖታቸውንም እርስ በርሳቸው ይጠብቃሉ።'),
  ('6fa813a0-4eae-596e-acf8-cee1275e7307', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 8, 8, 'ከእኔ ጋራ የሚሄደውንና የተሰወረውን የገለጠልኝን መልአክ ጠየቅሁት። እንዲህም አልሁት- “እነዚያ ምንድን ናቸው?”'),
  ('ab0d44b4-2b28-54f8-a3b3-c27bbc74444e', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 9, 9, 'እርሱም እንዲህ አለኝ- “የመናፍስት ጌታ የእነርሱን ምሳሌ አሳየህ። እነዚህም በምድር ላይ የሚኖሩ፥ በመናፍስት ጌታም ስም ለዘለዓለሙ የሚያምኑ የጻድቃን ስሞች ናቸው።'),
  ('892763ac-1615-5f44-a6c8-a0b1c42c5b40', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 10, 10, 'ስለ መብረቅም ሌሎችን አየሁ፤ ከከዋክብት እንዴት እንደሚጸኑና መብረቅን እንደሚሆኑ አየሁ። ከእነርሱም ጋር'),
  ('04b53211-808b-59f7-a1a2-ec47e65c9dd7', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 11, 11, 'ይህም ሁለተኛው ምሳሌ የቅዱሳን ማደሪያንና የመናፍስት ጌታን ስም በሚክዱ ላይ ነው።'),
  ('a413a1a9-3666-55e8-ada4-08acca759d4c', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 12, 12, 'ወደ ሰማይም አይወጡም፤ ወደ ምድርም አይወርዱም፤ የመናፍስትን ጌታ ስም የሚክዱ፥ ለድካምና ለመከራ ቀንም እንደዚህ የሚጠበቁ የኃጥኣን ዕድል እንዲህ ይሆናል፤ በዚያችም ቀን የተመረጠው በጌትነቱ ዙፋን ይቀመጣል።'),
  ('f09427e9-99b5-5354-a822-ed2d14c96485', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 13, 13, 'ሥራቸውንና ቦታቸውንም ይመርጣል፤ ቍጥርም የላቸውም።'),
  ('db5d2864-734b-5fdd-a3c6-95b448ad32f0', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 14, 14, 'እኔ የመረጥሁትን፥ ቅዱስና ክቡር ስሙን የሚማጠኑትንም'),
  ('da6c157c-6867-57e6-ae02-7a921908d68b', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 15, 15, 'በዚያችም ቀን እኔ የመረጥሁትን በመካከላቸው አኖረዋለሁ።'),
  ('59b4ac26-2324-5f3d-a1fa-bf0c099b0a0a', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 16, 16, 'ሰማይን እለውጣታለሁ፥ ለዘለዓለምም ለበረከትና ለብርሃን አደርጋታለሁ። ምድርንም እለውጣታለሁ፤ ለበረከትም አደርጋታለሁ።'),
  ('647e4ab4-8f1e-5111-a800-885e97922217', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 17, 17, 'የመረጥኋቸውንም በውስጧ አኖራቸዋለሁ። ኀጢአትንና በደልን የሚሠሩ ግን አይረግጧትም፤ እኔ ጻድቃንን አይቻቸዋለሁና፤ ሰላምንም አጥግቤአቸዋለሁና፥ በፊቴም አኖርኋቸው።'),
  ('b622b94e-e80f-5cdb-a9d4-a1e764b51f4c', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 18, 18, 'ከገጸ ምድር አጠፋቸው ዘንድ የኃጥኣን ፍርድ ወደ እኔ ቀረበች።'),
  ('c457d1dc-b64e-5b6e-a2ea-3868a318c828', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 19, 19, 'በዚያም ብሉየ መዋዕልነት ያለውን አየሁ፥ ራሱም እንደ ባዘቶ ነጭ ነው።'),
  ('04e3068d-17a5-5a40-a850-cf80dc221fde', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 20, 20, 'መልኩ እንደ ሰው መልክ የሆነ ሌላም ከእርሱ ጋር አለ። ጸጋንም የተመላ ነው፤ ፊቱም ከቅዱሳን መላእክት እንደ አንዱ ነው።'),
  ('5dc7ea95-3761-5d70-a829-df9becd84d74', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 21, 21, 'ከእኔ ጋራ የሚሄደውንና የተሰወረውን ሁሉ የገለጠልኝ ከቅዱሳን መላእክት አንዱን ስለዚሁ የሰው ልጅ ጠየቅሁት።'),
  ('af06603b-fc08-5bac-a647-5c7c7b90fb35', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 22, 22, 'እንዲህም አልሁት- “ያ ማን ነው? እርሱስ ከወዴት ይሆን? ከብሉየ መዋዕልስ ጋር ስለምን ይኖራል?”'),
  ('c9b1013f-aa14-5796-a61c-580ea7412c0c', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 23, 23, 'እርሱም መለሰልኝ እንዲህም አለኝ- “ጽድቅ የሆነለት፥ ጽድቅም ከእርሱ ጋር የኖረ የሰው ልጅ ነው። ጌታ እርሱን መርጧልና እርሱ የተሰወሩ መዛግብትን ሁሉ ይከፍታል።'),
  ('8a9344c7-c110-58f5-a50d-0cd1903c142a', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 24, 24, 'ዕድሉ በመናፍስት ጌታ ፊት ለዘለዓለም በርትዕ ሁሉን ድል ያደረገ ነው።'),
  ('4124ff5d-8f73-5842-a67e-27c2e08787e4', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 25, 25, '“ይህም ያየኸው የሰው ልጅ ነገሥታቱንና ኀያላኑን ከአልጋዎቻቸው፥ ጽኑዓኑንም ከዙፋኖቻቸው ያስነሣቸዋል።'),
  ('62b73a38-ee6f-5c03-a5fe-af9413b8fda5', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 26, 26, 'የጽኑዓኑንም ልጓሞች ይፈታል፥ የኃጥአንንም ጥርሶች ይሰብራል፤ ከፍ ከፍ አያደርጉትምና፥ አያመሰግኑትምምና፥ መንግሥትም ከየት እንደ ተሰጠቻቸው አያምኑምና ነገሥታትን ከዙፋናቸውና ከመንግሥታቸው ይገለብጣቸዋል።'),
  ('b3c3eb51-c3bb-50b2-a156-c0fc15c83760', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 27, 27, 'የጽኑዓኑንም ፊት ይገለብጣል፤ ኀፍረትንም ይመላባቸዋል፥ ማደርያቸውም ጨለማን ይሆንባቸዋል።'),
  ('13108fef-0790-5ab6-adb7-1bee86d99e1f', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 28, 28, 'ትሎችም ምንጣፍ ይሆኗቸዋል፤ የመናፍስትን ጌታ ስም ከፍ ከፍ አያደርጉምና ከመኝታቸው ይነሡ ዘንድ ተስፋ አያደርጉም።'),
  ('389e5e82-19f3-5f2a-a5d9-1ae05ba7d239', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 29, 29, 'እነርሱም የሰማይ ከዋክብትን የሚገዙ ሆነዋል፤ እጆቻቸውንም ወደ ልዑል ይዘረጋሉ፥ በምድር ይሄዳሉ፥ በውስጧም ይኖራሉ።'),
  ('30e80931-25ec-5be4-acb2-a476d8eea733', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 30, 30, 'ዐመፅ ሥራቸውንም ሁሉ ይገልጣሉ፤ ሥራቸውም ሁሉ ዐመፅ ነው፥ ኀይላቸውም በባለጸግነታቸው ላይ ነው።'),
  ('553b44e3-ea42-5479-a1f3-ad2ff8ef7d31', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 31, 31, 'ሃይማኖታቸውም በእጃቸው ለሠሯቸው ጣዖታት ሆኗል፥ የመናፍስትን ጌታ ስምም ክደዋል።'),
  ('62a7778a-9a52-5d75-aa57-46fae86fa100', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 32, 32, 'ከእርሱና በመናፍስት ጌታ ስም ከሚያምኑ ምእመናን ማደሪያዎችም ይሰደዳሉ።'),
  ('0941d68d-d257-5612-ae80-6013bb114401', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 33, 33, '“በዚያም ወራት የጻድቃን ጸሎት ከምድር ዐረገች፥ የጻድቁም ደም በመናፍስት ጌታ ፊት ተወደደ።'),
  ('b0085521-47d7-50c1-a83c-467fa40e7684', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 34, 34, 'በእነዚህም ወራቶች በሰማያት የሚኖሩ ቅዱሳን አንድ ይሆናሉ፤ በአንድ ቃልም ይማልዳሉ፥ ይጸልያሉም፥ ያመሰግናሉም።'),
  ('f1e89d27-31e7-5875-a1bf-2f322d63edfd', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 35, 35, 'ስለ ፈሰሰውም የጻድቃን ደም በመናፍስት ጌታ ስም ያመስግናሉ፥ ይባርካሉም።'),
  ('6ab99560-8a44-56aa-a367-10ed4881ac79', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 36, 36, 'የጻድቃንም ጸሎታቸው ለዘለዓለም ፍርድ ይደረግላቸው ዘንድ፥ መዘግየትም ለዘለዓለም እንዳይሆንባቸው በመናፍስት ጌታ ፊት አትቋረጥም።”'),
  ('5bff16be-b417-5a19-ae6a-d28d4d9b8bb5', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 37, 37, 'በእነዚያም ወራቶች ብሉየ መዋዕልን በጌትነቱ ዙፋን ተቀምጦ አየሁት፤ የሕያዋን መጻፎቻቸውም በፊቱ ተገለጡ።'),
  ('54b91221-b688-546d-ada5-ad8285f3b2c9', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 38, 38, 'በሰማያት የሚኖሩ ሠራዊትም ሁሉ በዙሪያው ሆነው በፊቱ ይቆማሉ።'),
  ('d757ab3c-6af1-5017-afef-0495b77cb7ff', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 39, 39, 'የቅዱሳን ልብ ደስታን ትሞላለች፤ የጽድቅ ቍጥሯ ሞልትWaልና፥ የጻድቃንም ጸሎት ተሰምትWaልና።'),
  ('c19cacbe-b40e-5f8a-aacc-988374264728', '6d6e97ea-fc4c-5cef-a230-27224a2955bd', 'a0dea25e-0e8e-5bdc-aaaf-463ec76f8ad3', 40, 40, 'የጻድቁም ደም በመናፍስት ጌት ፊት ተወደደ።'),
  ('2e9d5c6f-e4c4-517d-a3d1-97e41891e934', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 1, 1, 'በዚያ ቦታ የማይቈጠር የጽድቅ ምንጭን አየሁ።'),
  ('5b61368e-7dd1-50b8-a508-117a712d1ea2', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 2, 2, 'በዙሪያውም ብዙ የጥበብ ምንጮች ይከቡታል። የተጠሙ ሰዎችም ሁሉ ከእርሱ ይጠጣሉ፥ ጥበብንም ይሞላሉ።'),
  ('fb163047-e17c-5024-a27f-d7a683408250', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 3, 3, 'ማደሪያቸውም ከጻድቃን፥ ከተመረጡትና ከቅዱሳን ጋር ነው።'),
  ('06d18989-1321-51ed-a1eb-da2304983805', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 4, 4, 'በዚያችም ሰዓት ያ የሰው ልጅ በመናፍስት ጌታ ፊት ተጠራ።'),
  ('c92a2716-9da1-5423-aff6-62f90c150316', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 5, 5, 'ስሙም ከዕለታት መጀመሪያ የቀደመ ነው።'),
  ('93215112-b661-5b5b-a4c8-4c34e406089a', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 6, 6, 'ፀሐይ፥ ምልክትም'),
  ('4a46259d-c7d5-542b-ad98-1473d62cf83c', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 7, 7, 'እንዳይወድቁም እርሱን ይመረጐዙ ዘንድ ለጻድቃንና ለቅዱሳን በትር ይሆናል። እርሱም የአሕዛብ ብርሃን ነው፤ በልቡናቸው ላዘኑም እርሱ ተስፋ ይሆናል።'),
  ('c5c092a3-d524-5075-ac13-20392528e827', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 8, 8, 'በምድር ላይ የሚኖሩ ሁሉ በፊቱ ወድቀው ይሰግዳሉ፤ ያመሰግኑታል፥ ያከብሩታልም፥ ለመናፍስት ጌታ ስምም ያዘምራሉ።'),
  ('6d8b95f0-e7f5-5d30-ac1f-2d1dc8063297', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 9, 9, 'ስለዚህም አስታራቂ ሆነን፤ ይህም በመናፍስት ጌታ ፊት ከጥንት ጀምሮ እስከ ዘለዓለም ድረስ የተሰወረ ሆነ።'),
  ('2b0b0921-065e-515d-aee7-2dbd1b4ab738', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 10, 10, 'እርሱንም የመናፍስት ጌታ ጥበቡ ለጻድቃንና ለተመረጡት ገለጠው። የጻድቃንን ዕድል ፋንታ ጠብቋልና፤'),
  ('338a782f-c7cb-5ef4-ab01-cae11bcce16e', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 11, 11, 'ይህን የዐመፅ ዓለም ጠልተው ንቀውታልና፤ ሥራውንና መንገዱንም በመናፍስት ጌታ ስም ጠልተውታልና።'),
  ('908bfc3a-aaef-51cc-a8f1-2610f712b024', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 12, 12, 'በስሙ ይድናሉና፤ ድኅነታቸውንም ወደደ።'),
  ('342bf002-8e6c-50b9-af5e-dbfb1ce781ce', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 13, 13, 'በዚያም ወራት በጭንቀታቸውና በመከራቸው ቀን የምድርን ነገሥታትና ምድርን የያዙ ኀያላን ሰውነታቸውን አላዳኑምና ስለ እጃቸው ሥራ አንገታቸውን የደፉ ሆኑ።'),
  ('1349d259-13a8-5c8b-a25b-36c2963d2158', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 14, 14, 'በመረጥኋቸውም ሰዎች እጅ ይጥሏቸዋል።'),
  ('eb0ed7fe-da38-5115-a429-8fd83580e28e', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 15, 15, 'ሣር በእሳት እንደሚቃጠል፥ እርሳስም በውኃ ውስጥ እንደሚሰጥም እንዲሁ ከጻድቃን ፊት የተነሣ ይቃጠላሉ፤ ከቅዱሳንም የተነሣ ይሰጥማሉ።'),
  ('bd7e8d3e-1d0d-533c-a705-12af8cf675f4', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 16, 16, 'ፍለጋቸውም አይገኝም፥ በተጨነቁባትም ቀን በምድር ላይ ፍርሀት ትደረጋለች።'),
  ('d885ba36-a352-5090-a8be-565fe6784086', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 17, 17, 'በፊቱም ይወድቃሉ፥ አይነሡምም፤ እጁንም ሰጥቶ የሚያነሣቸው የለም፤ የመናፍስት ጌታን፥ መሲሑንም ክደውታልና፥ የመናፍስት ጌታም ስሙ ይመሰገናል።'),
  ('3b051ca3-0112-51d5-ab6f-2898336d248e', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 18, 18, 'ጥበብ እንደ ውኃ ፈስሶአልና፤ ክብርም በፊቱ ለዘለዓለም አትፈጸምም፤ በጽድቅ ምሥጢር ሁሉ ኀያል ነውና።'),
  ('87ea9c75-fe88-5597-a658-c8347f73822f', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 19, 19, 'አስታራቂው በመናፍስት ጌታ ፊት ቁሟልና፥ ዐመፅ እንደ ጥላ ያልፋል፥ መቆምያም ቦታ የለም።'),
  ('3436b399-2836-5d17-a062-ec5e2b4ce4fe', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 20, 20, 'ጌትነቱ ለዘለዓለም ነው፥ ኀይሉም ለልጅ ልጅ ዘመን ነው።'),
  ('322f37c6-3457-5a93-a301-b192616a917f', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 21, 21, 'የጥበብ መንፈስ፥ የማስተዋል መንፈስ፥ የትምህርትና የኀይል መንፈስ፥ በጽድቅ የሞቱትን ሰዎች በእውነት የሚያስነሣቸው መንፈስም በእርሱ ይኖራል።'),
  ('c8208f38-5ad8-5ca4-a362-783b3e6858b9', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 22, 22, 'እርሱም የተሰወሩትን ይፈርዳል፥ ከንቱ ነገርንም በፊቱ መናገር የሚችል የለም፤ እርሱ እንደ ወደደ በመናፍስት ጌታ ፊት አስታራቂ ነውና።'),
  ('7bfe7fdf-cbed-548c-a12a-a18bad5aeeb1', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 23, 23, 'በእነዚያም ወራቶች ለቅዱሳንና ለተመረጡት መመለስ ትደረግላቸዋለች፤ የዘመን ብርሃንም በእነርሱ ያድራል፥ ፍጹም ክብርም ለቅዱሳን ይመለስላቸዋል።'),
  ('003a4cf7-2439-53b8-afa2-d733d770deb4', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 24, 24, 'በጭንቅ ቀንም ለኃጥአን መከራ ትደልብላቸዋለች፤ ጻድቃንም በመናፍስት ጌታ ስም ድል ይነሣሉ።'),
  ('f1645865-3c0c-5375-a480-d822d2790f9a', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 25, 25, 'ንስሓ ይገቡ ዘንድ፥ የእጃቸውንም ሥራ ይተዉ ዘንድ ለሌሎች ይገልጣል።'),
  ('27526b45-8a94-5e99-ae45-3f592338c631', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 26, 26, 'በመናፍስት ጌታ ፊትም ክብር ይደረግላቸዋል፥ በስሙም ይድናሉ።'),
  ('08ed00f3-8149-5d0a-a6c0-2acb4fa542a6', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 27, 27, 'ቸርነቱ ብዙ ነውና፥ በፍርዱና በጌትነቱም ፊት ጻድቅ ነውና የመናፍስት ጌታ ይቅር ይላቸዋል።'),
  ('ae03d2d4-8acb-5a32-a019-cd84df8a879d', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 28, 28, 'ዐመፅም በፍርዱ ጊዜ አትጸናም፥ ንስሓ የማይገባም በፊቱ ይጠፋል፥ “ከእንግዲህ ወዲያም የመናፍስት ጌታ ይቅር አልላቸውም” አለ።'),
  ('7775373c-f904-54b4-a2d2-35fac314d5a3', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 29, 29, 'በእነዚያም ወራቶች ምድር አደራዋን ትመልሳለች፤ መቃብርም የተቀበለችውን አደራ ትመልሳለች።'),
  ('db8093cd-66b7-5fdd-aa0e-434b87dfe5cb', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 30, 30, 'ሞትም የሚከፍለውን ይመልሳል፥ እነርሱም ይድኑ ዘንድ ቀንዋ ቀርባለችና ጻድቃንንና ቅዱሳንን ከእነርሱ ይመርጣል።'),
  ('d4d7106b-d9bd-5842-a55a-27d115a5eee2', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 31, 31, 'አስታራቂውም በእነዚያ ወራቶች በዙፋኑ ይቀመጣል፤ የጥበብንም ምሥጢር ሁሉ ከአንደበቱ ያወጣል፤ የመናፍስት ጌታ ሰጥቶ አክብሮታልና።'),
  ('b7b5c21a-a027-5a0a-a9c6-df5629ca0c51', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 32, 32, 'በእነዚያም ወራቶች ተራሮች እንደ ጊደሮች ይዘፍናሉ፤ ኮረብቶችም ወተት እንደ ጠገቡ ጠቦቶች ይዘላሉ።'),
  ('4b665857-253f-57cf-ac48-f8575cdec7dd', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 33, 33, 'በእነዚያም ወራቶች አስታራቂው ተነሥትWaልና ሁሉም በሰማይ እንደ መላእክት ይሆናሉ። ፊታቸውም በደስታ ይበራል።'),
  ('1eb0c1f8-6c5b-5e46-a48c-d93ef12d0ff4', '2f4a1073-8fb9-59ab-a90e-908568880e69', '29481190-7907-5ba5-a3d2-311b854949d2', 34, 34, 'ምድርም ደስ ይላታል፥ ጻድቃንም በእርሷ ይኖራሉ፥ የተመረጡትም በእርሷ እየተመላለሱ ይኖራሉ።'),
  ('ea478ac9-21ec-50d0-a3ad-fc2ebc56e4b2', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 1, 1, 'ከእነዚያም ወራቶች በኋላ የተሰወሩትን ራእዮች ሁሉ ባየሁበት በዚያ ቦታ በነፋስ ሠረገላ ተነጥቄ ነበርና፥ ወደ ምዕራብም ወስደውኝ ነበርና፥'),
  ('b48baf5d-745d-5952-aca1-46101710035c', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 2, 2, 'በዚያ በምድር ላይ ይደረግ ዘንድ ያለውን የሰማይ ምሥጢር ሁሉ ዐይኖቼ አዩ።'),
  ('fa3a05f6-02a7-5512-a3c0-a8287331f457', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 3, 3, 'የብረት ተራራንና የናስ ተራራን፥ የብር ተራራንና የወርቅ ተራራን፥ የዕይር ተራራንና የርሳስ ተራራን አዩ።'),
  ('291f5eee-bc33-5a6c-a94d-ce95d35627a9', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 4, 4, 'ከእኔም ጋር የሚሄደውን መልአክ “በስውር የማያቸው እኒህ ምንድን ናቸው?” ብዬ ጠየቅሁት።'),
  ('d492a15d-1dc5-5d41-ab66-de66f9ce3693', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 5, 5, 'እርሱም እንዲህ አለኝ- “እኒህ ያየሃቸው ሁሉ ያዝዝ ዘንድ፥ በምድርም ላይ ኀያል ይሆን ዘንድ ለመሲሑ ሥልጣን ይሆናሉ።”'),
  ('5f1e1c66-1a93-56e1-aec2-3b44c71b7a61', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 6, 6, 'ያም የሰላም መልአክ እንዲህ ሲል መለሰልኝ- “ጥቂት ቈይ፥ ታያለህም፥ የመናፍስት ጌታ ያጸናው፥ የተሰወረውም ሁሉ ይገለጥልሃል።'),
  ('3825d440-6e89-5371-a642-4b733196fae9', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 7, 7, 'ያየሃቸው እነዚህ ተራሮችም የብረቱ ተራራና የናሱ ተራራ፥ የብሩ ተራራና የወርቁ ተራራ፥ የዕይሩ ተራራና የርሳሱም ተራራ፥ እነዚህ ሁሉ በአስታራቂው ፊት በእሳት ፊት እንዳለ አደሮማር ይሆናሉ።'),
  ('75543542-da64-5029-a31b-d8c188129142', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 8, 8, 'ከላይ በእነዚያ ተራሮች ላይ እንደሚወርድ ውኃም ይሆናሉ። ከእግሩም በታች ደካሞች ይሆናሉ።'),
  ('afa3deab-9817-53d5-aee5-8627a59185c7', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 9, 9, '“በእነዚያም ወራቶች እንደዚህ ይሆናል፥ በወርቅም ቢሆን በብርም ቢሆን አይድኑም፥ ማምለጥና መሸሽም አይቻላቸውም።'),
  ('ac90f552-49c3-5e9a-a5e4-50b9c08b95f3', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 10, 10, 'ብረትም ለጠብ አይሆንም፥ ልብስም ለደረት ጥሩር አይሆንም፥ ብረትም አይረባም፥ ቅልቅልም አይጠቅምም፥ አይቈጠርምም፥ ርሳስም አይወደድም፥ ነገር ግን እኒህ ሁሉ ይካዳሉ።'),
  ('72ef47cc-76fb-53f2-aec7-b7629c0d1ecc', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 11, 11, 'አስታራቂውም በመናፍስት ጌታ ፊት በተገለጠ ጊዜ ከምድር ፊት ይጠፉ ዘንድ አላቸው።”'),
  ('d612ce4f-4f04-5160-ae97-276640e34e1c', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 12, 12, 'በዚያም ዐይኖቼ ጥልቅ ሸለቆን አዩ፥ አፉም የተከፈተ ነው።'),
  ('405b7114-a83b-5e97-a652-37e2c99dfa24', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 13, 13, 'በየብስና በባሕር፥ በደሴቶችም የሚኖሩ ሁሉ እጅ መንሻ፥ ገጸ በረከትና ግብርን ያመጡለታል፤ ይህም ጥልቅ ሸለቆ አይመላም።'),
  ('f9d5841e-dd88-5c31-aece-7b057e45379b', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 14, 14, 'እጆቻቸውም በደልን ያደርጋሉ፥ ኃጥአንም ለበደል የሚደክሙበትን ሁሉ ይበላሉ፤'),
  ('486bc05c-d95e-5850-ad45-590531305505', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 15, 15, 'ከመናፍስት ጌታ ፊትም የተነሣ ኃጥአን ይጠፋሉ፤ ኃጥአንም በምድሩ ፊት ይቆማሉ።'),
  ('aaa3b581-11fc-5d70-a3b6-6ac497827166', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 16, 16, 'ለዘለዓለሙ አያልቁም፥ የመቅሠፍት መላእክትን ሄደው ለሰይጣን ዙሃውን ሁሉ ሲያዘጋጁ አይቻቸዋለሁና።'),
  ('ad960446-49d4-5c45-ad8e-1dab9e0519d9', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 17, 17, 'ከእኔም ጋር የሚሄደውን የሰላም መልአክ ጠየቅሁት፥ እንዲህም አልሁት- “እነዚህን ዙሃዎችን ለማን ያዘጋጃሉ?”'),
  ('49add620-9af8-573f-abdf-b542a54a8a9b', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 18, 18, 'እርሱም አለኝ- “በእነርሱ ይጠፉ ዘንድ፥ ለዚህ ዓለም ነገሥታትና ኀያላን እነዚህን ያዘጋጃሉ።'),
  ('a889e2ff-c97d-5623-a578-57ea16c76f10', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 19, 19, 'ከዚህም በኋላ እውነተኛው አስታራቂ በመሰብሰቢያው ቤት ይገለጣል።'),
  ('2a2888cb-550c-53cf-af87-a8f5b702b6ad', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 20, 20, 'ከእንግዲህ ወዲያም በመናፍስት ጌታ ስም አይከለከሉም።'),
  ('af7f5273-4a46-54a2-a8cf-e887dce4e6de', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 21, 21, 'ተራሮች ሁሉ በፊቱ እንደ ምድር ይሆናሉ፤ ኮረብቶችም እንደ ውኃ ምንጭ ይሆናሉ፤ ጻድቃንም ከኃጥአን ድካም ያርፋሉ።”'),
  ('7a60cb35-50ea-5189-a826-750af4dfc156', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 22, 22, 'ተመልሼም ሌላ ገጸ ምድር አየሁ፥ በዚያም እሳት ሲነድ ጥልቅ ሸለቆን አየሁ።'),
  ('eeca7f0e-ad19-5145-af6b-ccb025917f6f', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 23, 23, 'ነገሥታቱንና ኀያላኑንም አምጥተው በዚያ ጥልቅ ሸለቆ ውስጥ ጣሏቸው።'),
  ('1b102384-c0e2-5c84-a8e5-d7b96abea746', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 24, 24, 'በዚያም ዐይኖቼ ዙሃዎችን ሚዛን የሌላቸው የብረት ማሠሪያዎችን አድርገው ሲሠሯቸው አዩ።'),
  ('cea4b439-5e26-549c-a271-7f9a4c316312', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 25, 25, 'ከእኔም ጋር የሚሄደውን የሰላም መልአክ “እነዚህ የዙሃዎች ማሠሪያዎች ለማን ይዘጋጃሉ?” ብዬ ጠየቅሁት።'),
  ('63f99b2b-3e0f-5747-a1f1-9076b630846e', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 26, 26, 'እርሱም እንዲህ አለኝ- “ተቀብለው ከገሃነም በታች ይጥሏቸው ዘንድ እነዚህ ለአዛዝኤል ሠራዊት ይዘጋጃሉ።'),
  ('80f79e9e-4d25-50d3-aa07-750361084ee6', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 27, 27, 'የመናፍስት ጌታም እንዳዘዘ በፊታቸው ጠማማ ድንጋዮችን ይገጥሙባቸዋል።'),
  ('83e07510-5163-5227-afc8-edeff77c6e89', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 28, 28, 'ሚካኤልና ገብርኤል፥ ሩፋኤልና ፋኑኤል እነርሱ በዚያች በታላቅዋ ቀን ያጠኑባቸዋል።'),
  ('3b870826-a06d-5819-a21a-d1f118f74436', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 29, 29, 'በዚያም ቀን የሰይጣን መልእክተኞች ስለሆኑ፥ በምድር ላይ የሚኖሩትንም ስላሳትWaቸው በዐመፃቸው የመናፍስት ጌታ ከእነርሱ በቀልን ይመልስ ዘንድ እሳት ወደሚነድድበት ምድጃ ይጥሏቸዋል።'),
  ('f7403989-a039-5d1c-a81f-db3aaf5bbf6e', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 30, 30, '“በዚያም ወራት የመናፍስት ጌታ መቅሠፍት ይወጣል።'),
  ('eee18d6a-bf41-5245-aab6-162e731dabee', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 31, 31, 'ከሰማያት በላይ ያሉ የውኃዎች መዛግብት ሁሉ፥ ከሰማያት በታችና፥ ከምድር በላይ ያሉ ምንጮችም ይከፈታሉ።'),
  ('c6bb0dd3-7637-54a4-a91f-19bc56130f6c', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 32, 32, 'ውኆችም ሁሉ ከሰማያት በላይ ካሉ ውኃዎች ጋር ይጨመራሉ።'),
  ('f2fdce2e-6af1-5e84-a822-c6575e79af3c', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 33, 33, 'ከሰማያት በላይ ያለ ውኃ ግን ተባዕታይ ነው፥ ከምድር በታች ያለችው ውኃም አንስታይ ናት።'),
  ('1a1e91a5-92f8-5847-adf9-3d804d0045a9', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 34, 34, 'በምድር ላይ የሚኖሩና ከሰማይ ዳርቻ በታች የሚኖሩ ሁሉ ይደመሰሳሉ።'),
  ('649f0869-af7a-561e-a862-7f6833fe0fb0', '20e26371-c8a6-59d9-a7f7-a5c1b19f96e0', '5cd6ad15-2cff-5acd-ac72-7a11ae77de03', 35, 35, 'ስለዚህም በምድር ላይ የሠሯትን ኀጢአታቸውን ዐወቋት፤ ስለዚህም ይጠፋሉ።”'),
  ('939cc756-5621-542b-a613-18f0e3fd40b1', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 1, 1, 'ከዚህም በኋላ ብሉየ መዋዕል አዘነ፥ እንዲህም አለ- “በምድር ላይ የሚኖሩትን ሰዎች ሁሉ በከንቱ አጠፋኋቸው፤”'),
  ('9ac10969-0697-5a25-a8c0-399be95fa881', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 2, 2, 'ከእንግዲህም ወዲያ በምድር ላይ በሚኖሩ ሰዎች ሁሉ እንዲህ እንደማያደርግ በገናና ስሙ ማለ።'),
  ('ee3d4e43-a1aa-57fa-a9e7-22272d69e6fc', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 3, 3, 'እንዲህም አለ- “በሰማይ ምልክት አደርጋለሁ፥ ይህም በእነርሱና በእኔ መካከል በምድር ላይ የሰማይን ዘመን ያህል እስከ ዘለዓለም መተማመኛ ይሆናል።'),
  ('6957c4b5-b63e-5110-aff6-69f9baabbb05', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 4, 4, 'ከዚህም በኋላ በመላእክት እጅ አጸናባቸው ዘንድ ብወድ በትእዛዜ ነው።'),
  ('9df33ff2-c412-50f2-abca-f846542bdc75', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 5, 5, 'በችግርና በመከራ ቀን ከዚህ አስቀድሞ መዓቴም፥ መቅሠፍቴም ያድርባቸዋል።'),
  ('567add40-7b38-59ff-adae-ab7a6f047bef', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 6, 6, 'የመናፍስት ጌታ እግዚአብሔርም በምድር የምትኖሩ ኀይለኞች ነገሥታት! እኔ የመረጥሁትን በጌትነቱ ዙፋን በሚቀመጥበት ጊዜ ታዩት ዘንድ አላችሁ አለ።'),
  ('fd46b5ca-3c82-5129-afa2-977adf29f0cb', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 7, 7, 'እርሱም በአዛዝኤልና በማኅበሩ ሁሉ፥ በሠራዊቱም ሁሉ ላይ በመናፍስት ጌታ ስም ይፈርዳል።”'),
  ('868f7c74-a2b3-5b49-abbd-f8a6c9c1a4dd', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 8, 8, 'በዚያም የመቅሠፍት መላእክትን ሠራዊት ሲሄዱ አየሁ፤ የብረትና የብርት ወጥመዶችንም ይዘዋል።'),
  ('9067f96f-a378-5cca-ac65-40416dc87598', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 9, 9, 'ከእኔም ጋር የሚሄደውን የሰላም መልአክ “ወጥመዶችን የያዙ እነዚህ ማንን ሊያሥሩ ይሄዳሉ?” ብዬ ጠየቅሁት።'),
  ('5b1b5a08-844f-5a54-a07a-450159800dfc', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 10, 10, 'እርሱም እንዲህ አለኝ- “በሸለቆው ጥልቅ ዋሻ ውስጥ ይወድቁ ዘንድ እያንዳንዳቸው ለመረጡአቸውና ለወደዱአቸው ናቸው።'),
  ('0ee8b8fa-b025-5899-aa48-74477cd2e1b3', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 11, 11, 'ያንጊዜም ያ ሸለቆ ከመረጧቸውና ከወደዷቸው የተነሣ ይሞላል።'),
  ('bf96c6b5-13e1-5304-a16b-7580769fd24e', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 12, 12, 'የሕይወትም ቀናቸው ያልቃል፥ የስሕተታቸውም ቀን ከዛሬ በኋላ አይቈጠርም።'),
  ('96201865-9739-539d-ac84-477da7d9cf81', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 13, 13, '“በእነዚያም ወራቶች አለቆች ተሰብስበው ወደ ጳርቴና ወደ ሜድ ሰዎች ወደ ምሥራቅ ራሳቸውን ይመልሳሉ።'),
  ('0ef796f3-9b1c-5213-a483-d104bb21356b', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 14, 14, 'ነገሥታቱንም ያነቃንቋቸዋል፥ የሁከት መንፈስም ያድርባቸዋል፥ ከዙፋናቸውም ይገለብጧቸዋል።'),
  ('a42b5162-12a5-527a-a332-cd293819fb79', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 15, 15, 'እንደ አንበሶች ከመደባቸው፥ እንደ ተራቡ ጅቦችም ከመንጋዎቻቸው መካከል ይወጣሉ።'),
  ('5708e6ad-3d5a-5059-ad1a-697ddf87e557', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 16, 16, '“ይዘምታሉ፥ የምርጦቻቸውንም ሀገር ይረግጣሉ፤ የእርሱ ምርጦች ሀገርም በፊታቸው መመላለሻና መገሥገሻ ትሆናለች።'),
  ('c9a1d8f6-ef58-5ef9-a84f-4086d6a15334', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 17, 17, 'የጻድቃኔ ከተማ ግን ለፈረሶቻቸው መሰናክል ትሆናለች።'),
  ('7ed69bbf-d1ed-5c5e-a601-276752c6c96f', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 18, 18, 'እርስ በርሳቸውም ጦርነትን ያነሣሉ፤ ቀኝ እጃቸውም በእነርሱ ላይ ትጸናለች፥ ሰውም ባልንጀራውን፥ ወንድሙንም አያውቀውም።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('a67da858-b23d-5c97-a56e-be1027a31e32', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 19, 19, 'ልጅም ከሞታቸው የተነሣ ሬሣቸው እስኪቈጠር ድረስ አባቱንና እናቱን አያውቅም። መቅሠፍታቸውም ከንቱ አይሆንም።'),
  ('52fa7ce0-5180-5051-ab9c-1ebffd8fadeb', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 20, 20, 'በእነዚያም ወራቶች መቃብር አፏን ትከፍታለች።'),
  ('05baaa9f-b29d-5c5b-a35f-9cf22a0f7a3d', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 21, 21, 'በውስጧም ይቀበራሉ፤ ታጠፋቸዋለችም፥ ከተመረጡት ፊት የተነሣም ሲኦል ትውጣቸዋለች።”'),
  ('70821e33-0a3e-5522-a667-74f46a82478a', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 22, 22, 'ከዚህም በኋላ እንዲህ ሆነ፥ ሰዎች ተቀምጠውባቸው ሌሎች ብዙዎች ሠረገላዎችን አየሁ።'),
  ('3904436a-58ed-587d-a09b-6447644699ec', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 23, 23, 'በነፋሳትም ላይ ሆነው ከምሥራቅና ከምዕራብ እስከ ቀን እኩሌታ ይመጣሉ።'),
  ('524b4b3a-72f6-5a91-aaae-0e54d9b36265', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 24, 24, 'የሠረገሎቻቸው ድምፅ ቃልም ተሰማ፥ ይህም ሁከት በተደረገ ጊዜ ቅዱሳን በሰማይ ሁነው ዐወቁ።'),
  ('b1c8d692-f667-5263-ab59-e57a36ed9092', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 25, 25, 'የምድር ምሰሶም ከቦታው ተናወጠ።'),
  ('37ec6b9d-7cbf-5b92-a2a9-cb7d58c26126', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 26, 26, 'ከሰማይ ዳርቻ ጀምሮ እስከ ምድር ዳርቻ ድረስም ባንዲት ቀን ተሰማ።'),
  ('6e2f3f3d-be21-5653-a756-0c61169936a2', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 27, 27, 'ሁሉም ወድቀው ለመናፍስት ጌታ ይሰግዳሉ።'),
  ('73654751-f106-5287-adb1-9048fb9dcab1', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 28, 28, 'የሁለተኛውም ምሳሌ መጨረሻ ይህ ነው።'),
  ('9b738b9e-2bd1-5701-a895-f892d97418b8', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 29, 29, 'ስለ ጻድቃንና ስለ ተመረጡት ሦስተኛውን ምሳሌ እናገር ዘንድ ጀመርሁ።'),
  ('823f727b-9c66-5209-a214-b8d0797c1469', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 30, 30, 'እናንተ ጻድቃንና የተመረጣችሁ ብፁዓን ናችሁ፤ ዕድላችሁ ክቡር ነውና።'),
  ('145ae2da-439c-5ce5-a36f-fc0d9fd61e96', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 31, 31, 'ጻድቃን በፀሐይ ብርሃን፥ የተመረጡትም በዘለዓለማዊ የሕይወት ብርሃን ይሆናሉ።'),
  ('c3c3e3a0-6c47-5647-abfc-3e24967e3d35', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 32, 32, 'ለሕይወታቸው ዘመንም ፍጻሜ የለውም፥ ለቅዱሳንም የዘመን ቍጥር የላቸውም።'),
  ('37c11ac7-f548-52cc-ab7f-dfcce9a0f758', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 33, 33, 'ብርሃንንም ይፈልጉታል፥ በመናፍስት ጌታም ዘንድ ጽድቅን ያገኛሉ።'),
  ('aad1396f-6bb7-5cd2-a866-e7dfc298f5cf', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 34, 34, 'በመናፍስት ጌታም ዘንድ ለጻድቃን ሰላም ይሆናል።'),
  ('401f1514-fdd6-54f4-a392-779160ebf9c0', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 35, 35, 'ከዚህም በኋላ የሃይማኖት ዕድል ፋንታ የሆነውን የጽድቅ ምሥጢር በሰማይ ይፈልጉ ዘንድ ለጻድቃን ይነገራል።'),
  ('4578505c-3528-5f6c-a22f-7f3f8a2424b3', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 36, 36, 'እንደ ፀሐይ በምድር ላይ ወጥትWaልና፥ ጨለማም አልፎአልና፤ የማይቈጠር ብርሃንም ይሆናል።'),
  ('71163ea6-b9f7-56ac-a8ce-0be08af1cbd6', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 37, 37, 'አስቀድሞ ጨለማ አልፎአልና በዘመን ቍጥር አይገቡም።'),
  ('ef54a535-0359-580b-a754-c309eb26d9db', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 38, 38, 'ብርሃንም በመናፍስት ጌታ ፊት ይጸናል፤ የእውነተኛ ፍርድ ብርሃንም በመናፍስት ጌታ ፊት ለዘለዓለም ትጸናለች።'),
  ('5a5fcdb3-3caa-5284-a671-367ca3765272', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 39, 39, 'በእነዚያም ወራቶች ዐይኖቼ የመባርቅትንና የብርሃናትን ምሥጢራት፥ ፍርዳቸውንም አዩ።'),
  ('0651639c-9aae-5485-a909-410c21d20a77', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 40, 40, 'የመናፍስት ጌታም እንደ ወደደ ለበረከትና ለመርገም ያበራሉ።'),
  ('022906ce-c22d-535b-a036-becd1730940f', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 41, 41, 'በዚያም የነጐድጓድ ምሥጢርን አየሁ፤ በሰማይ ላይም ብልጭ ባለ ጊዜ ቃላቸው ይሰማል።'),
  ('6da425a5-7105-5708-ac93-9a8990b3f61c', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 42, 42, 'የየብሱንም ቦታዎች አሳየኝ።'),
  ('a6215872-a262-5974-af9f-589bd98efa0d', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 43, 43, 'የነጐድጓዱም ቃል ለሰላምና ለበረከት ነው፤ ለመርገም ቢሆንም በመናፍስት ጌታ ቃል ነው።'),
  ('2cdefac9-7bac-51d4-adc0-4b12473cbca5', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 44, 44, 'ከዚህም በኋላ የብርሃናትና የመባርቅት ምሥጢሮች ሁሉ ተገለጡልኝ።'),
  ('e7217add-00c0-5f2c-aa63-437c34e2d85c', 'd0647ed3-6b0b-5887-a630-24aa26c18b27', '1c43f3ff-a360-5685-a3f5-4f61cd78184e', 45, 45, 'ለበረከትና ለጥጋብም ያበራሉ።'),
  ('61e3f76b-86cf-507e-a632-8c94d932c154', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 1, 1, 'ሄኖክ ከተሰወረ በኋላ በአምስት መቶ ዓመት፥ በሰባተኛውም ወር በዐሥራ አራተኛው ቀን ከሰማያት በላይ ያለች ሰማይ ታላቅ ንውጥውጥታን እንደምትነዋወጥ፥ የልዑልም ሠራዊት እንደሚነዋወጡ በዚያ ምሳሌ አየሁ።'),
  ('49dd06f3-8603-5cda-adc7-baee7d27644f', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 2, 2, 'ብዙ፥ የብዙ ብዙ መላእክትም ታላቅ ሁከትን ታወኩ።'),
  ('47cae4df-a40e-5f6a-a2dc-e172added406', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 3, 3, 'ያንጊዜም ብሉየ መዋዕልን በጌትነቱ ዙፋን ተቀምጦ አየሁ።'),
  ('6798feaf-301f-5463-aab7-69d5e6692fa3', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 4, 4, 'መላእክትና ጻድቃንም በዙሪያው ቆመው አየሁ፤ እኔንም ጽኑ እንቅጥቅጥ ፈጽሞ ያዘኝ።'),
  ('16121fb6-4f67-5d78-a63a-873a38b5aa8b', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 5, 5, 'ፍርሀትም ያዘኝ፥ ወገቤም ጐበጠ፤ ተለያየም፤ ሁለመናዬም እንደ ሰም ቀለጠ፤ በግንባሬም ወደቅሁ።'),
  ('cc5cf938-e333-506c-ab46-11c6c15638ae', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 6, 6, 'ቅዱስ ሚካኤልም ከቅዱሳን መላእክት አንዱን ሌላ መልአክ ልኮ አነሣኝ።'),
  ('bc5a9af3-dc51-59bd-a17e-eedde1b90e45', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 7, 7, 'ባነሣኝም ጊዜ ነፍሴ ተመለሰች፤ ያን ተአምራትና ያንም ሁከት፥ የሰማይንም መነዋወጥ ከማየት የተነሣ መታገሥን አልቻልሁምና።'),
  ('f4d6a521-9218-5bed-a558-c97f5538857a', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 8, 8, 'ቅዱስ ሚካኤልም እንዲህ አለኝ- “ምን ራእይ ስላየህ እንደዚህ ታወክህ?”'),
  ('45ebf3e3-5d8f-5feb-aeed-ceb9e2d7651c', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 9, 9, 'የምሕረቱ ቀንም እስከ ዛሬ አለች፤ መሓሪውም አለ፤ በምድር በሚኖሩ ላይም መዓቱ የራቀ ነው።'),
  ('c28a152f-b898-597b-a44c-fab0aa5faea9', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 10, 10, 'የመናፍስት ጌታ ለእውነተኛ ፍርዱ ለሚሰግዱ፥ እውነተኛ ፍርዱንም ለሚክዱ፥ ስሙንም በከንቱ ለሚያነሡ ያዘጋጃት፥ የኀይል፥ የመቅሠፍትና የፍርድ ቀን በምትመጣበት ጊዜ፥'),
  ('33a40951-3f12-53c5-aa9a-6b6ab32570f0', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 11, 11, 'ያች ቀን ለተመረጡት የቃል ኪዳን፥ ለኃጥኣንም የምርመራ ቀን ሆና ተዘጋጅታለች።”'),
  ('77dc625e-5f69-5004-a9d8-3f6f7830262c', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 12, 12, 'በዚያችም ቀን ሁለቱ አንበሬዎች ይለያያሉ፤ ሌዋታን የምትባለው አንስታይ አንበሪ ከውኃዎች ምንጮች በላይ በባሕሩ ጥልቅ ትኖር ዘንድ ትለያለች።'),
  ('12f6dfc1-d04a-56da-a960-6d92b93ff44b', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 13, 13, 'የማይታየውን ምድረ በዳ በደረቱ የሚይዝ፥ ስሙ ብሔሞት የሚባለው ተባዕት አንበሪም ይለያል።'),
  ('6dc299ea-be4a-5407-a2f9-9815e234d56f', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 14, 14, 'የቦታውም ስም ጻድቃንና የተመረጡት በሚኖሩበት፥ የመናፍስት ጌታ ለፈጠራቸው ሰዎች መጀመሪያቸው ከሆነው ከአዳም ሰባተኛ የሆነ አያቴ በተወሰደበት በገነት ምሥራቅ ያለ ዴንዳይን ይባላል።'),
  ('d217cd8f-6e11-5a2e-a932-aa7d47ca143f', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 15, 15, 'እኔም ባንዲት ቀን እንዴት እንደ ተለዩ፥ አንዱ በባሕሩ ጥልቅ፥ አንዱም በምድረ በዳ እንዴት እንደሚኖሩ የእነዚያን አንበሬዎች ኀይላቸውን ይገልጥልኝ ዘንድ ያን ሁለተኛውን መልአክ ጠየቅሁት።'),
  ('950cb2b8-9e89-59cb-a7f2-2c4be7a38d05', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 16, 16, 'እርሱም አለኝ- “አንተ የሰው ልጅ፥ የተሰወረን ነገር በዚህ ልታውቅ ትወዳለህ?”'),
  ('98731a5a-fb73-5326-af22-a898b7ce2568', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 17, 17, 'ከእኔ ጋር የሚሄደው፥ የተሰወረውን የፊተኛውንና የኋለኛውን፥ በላይ በሰማይ፥ በምድርም በጥልቁ፥ በሰማይ ዳርቻና በሰማይ መሠረትም፥ በነፋሳትም መዛግብት ያለውን የገለጠልኝ ሁለተኛው መልአክ፥'),
  ('a789c70a-7b7c-54fd-a109-2bfdb689faab', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 18, 18, 'ነፋሳት እንዴት እንደሚከፈሉና እንደሚመዘኑ፥ ምንጮችና ነፋሳትም በመንፈስ ኀይል እንደሚከፈሉ፥ የጨረቃም የብርሃኑ ኀይል፥ የእውነት ሥራ እንደ መሆኑ፥ የከዋክብትም ክፍሎች በየስማቸው እንደሚከፈሉ ንገረኝ።'),
  ('9744b210-3e83-53ba-a062-8612d0abef54', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 19, 19, 'ክፍሉም ሁሉ ይከፈላል፤ ነጐድጐዶችም በመውደቂያቸው ይሰማሉ፤ ለሚከፈለው ክፍል ሁሉ መጠን አለው።'),
  ('cefa249a-1025-528f-ab17-c4652e59b083', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 20, 20, 'መብረቁ ይበራ ዘንድ፥ ሠራዊታቸውም ፈጥነው ይሰሙ ዘንድ ለነጐድጓድ ማረፊያ አለውና በትዕግሥት ለቃሉ ተሰጠው።'),
  ('1722085e-1f6f-5727-a222-a17d57374a02', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 21, 21, 'ነጐድጓድና መብረቅ አይለያዩም፤ እያንዳንዳቸውም ሁለቱ በነፋስ ይሄዳሉ።'),
  ('95cd256d-7ecb-533e-abbf-8df58c1a5265', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 22, 22, 'መብረቅ ብልጭ ባለ ጊዜ ነጐድጓድ ቃሉን ይሰጣልና አይለያዩም፤ ነፋሱም ወዲያውኑ ያርፋል።'),
  ('9cac9c95-93c4-55ce-aee4-da9e39277084', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 23, 23, 'በመካከላቸውም እኩል ይከፍላል፤ የሚወጡበት ቅፅበት እንደ አሸዋ ነውና።'),
  ('927f444b-c05a-522c-a4cf-b9f79e1118e8', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 24, 24, 'ከእነርሱም እያንዳንዳቸው ወዲያውኑ በልጓም ይገታሉ።'),
  ('5b2d653f-0c29-56c5-a610-eaef8461af23', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 25, 25, 'በነፋስም ኀይል ይመላለሳሉ፤ እንደ ምድር ዳርቻዎች ብዛትም እንዲሁ ይነዳሉ።'),
  ('880d50d2-6130-5b6a-a378-cc105808b47f', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 26, 26, 'የባሕሩም መንፈስ'),
  ('267927e4-1199-526a-ae44-143c429f1871', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 27, 27, 'እንዲህም ትነዳለች፤ በምድር ተራሮችም ሁሉ ትበተናለች።'),
  ('a0669e12-3a57-55b9-a257-310f76915058', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 28, 28, 'የውርጩም ነፋስ የእርሱ መልአክ ነው፤ የበረዱም ነፋስ ቸር መልአክ ነው።'),
  ('e2609635-5799-5eb9-a9d3-045c144ef7cf', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 29, 29, 'የአመዳዩ ነፋስም ስለ ብርታቱ ቆመ፤ ለብቻውም መልአክ አለው።'),
  ('51e06ef9-8007-5e86-aba4-a860fe2d5b90', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 30, 30, 'ከእርሱም የሚወጣው እንደ ጢስ ያለ ነው፥ ስሙም ደደክ ይባላል።'),
  ('8a4e3814-c6db-5c6e-a4c9-82f4afc9fb24', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 31, 31, 'የጉም ነፋስም ከእነርሱ ጋር በመዛግብታቸው አይተባበርም፤ ነገር ግን አካሄዱ በጌትነት፥ በብርሃንና በጨለማ፥ በክረምትና በበጋ ነውና ለብቻው መዝገብ አለው።'),
  ('5fef192b-f03c-55d2-a6c3-7c9552506efb', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 32, 32, 'የእርሷም ቦታ'),
  ('eda4c207-7273-55d5-abef-b9d291602b75', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 33, 33, 'ከዝናም መዛግብትም ጋር አንድ ነው፤ መሄጃውም በክረምትና በበጋ ነው።'),
  ('192d68b2-92ea-50ee-ac8d-495abfd14a4d', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 34, 34, 'ደመናውም ከጉም ደመና ጋር አንድ ነው፤ አንዱ መግቦ ለሌላዉ ይሰጣል።'),
  ('12285395-5035-5ede-a818-e4500731f2f1', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 35, 35, 'የዝናሙ ነፋስ ከመዝገቡ በሚናወጥ ጊዜ መላእክት ይወጣሉ፤ መዝገቡንም ከፍተው ያወጡታል።'),
  ('b14199f9-4e2f-578a-a925-92afbc5c3b0e', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 36, 36, 'በምድር ሁሉ ላይ ዝናሙ በሚበተን ጊዜ በምድር ላይ ካለው ውኃ ሁሉ ጋር አንድ ይሆናል።'),
  ('b1f0dea7-8a92-56c6-a4b8-3c46b22e84f5', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 37, 37, 'ዝናሙም በየጊዜው ሁሉ በምድር ላይ ካለው ውኃ ጋራ በሚተባበርበት ጊዜ ውኃዎች በምድር ለሚኖሩ ሰዎች ለጥቅም ናቸው፤ ከሰማይ ከልዑል ዘንድ ለምድር ምግቧ ናቸውና። ስለዚህም ለዝናሙ መጠን አለው፤ መላእክትም ይቀበሉታል።'),
  ('ae995901-c2fb-512d-a53b-c9f858ff7099', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 38, 38, 'እነዚህንም ሁሉ እስከ ጻድቃን ገነት ድረስ አየሁ።'),
  ('7cca002c-8960-553c-a870-09257b829c0e', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 39, 39, 'ከእኔም ጋር የሚኖረው የሰላም መልአክ እንዲህ አለኝ- “እነዚህ ሁለቱ አንበሬዎች በታላቋ የእግዚአብሔር ቀን'),
  ('cf367c0f-a441-50fb-a2ea-e10c4504257e', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 40, 40, 'የመናፍስት ጌታ መቅሠፍት በእነርሱ ላይ ባረፈች ጊዜ ልጆች ከእናቶቻቸውና ከአባቶቻቸው ጋር ይገደላሉ።'),
  ('a88048b1-9df6-5dd9-ae5d-b7a407b05396', '175dee34-cab7-5521-a08d-8484e64df9b3', '817bdd93-3759-55f4-a9a6-a2f4ef7927bd', 41, 41, 'የመናፍስት ጌታ መቅሠፍቱም በከንቱ እንዳትመጣ በቸርነቱና በትዕግሥቱ ኋላ በእነርሱ ላይ ፍርድ ትሆናለች።'),
