  ('a31a9b60-0417-58ef-ab9b-ca6cd7eb6184', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 11, 11, 'ያንም ቀዳማዊ ቃል ያመሰግኑታል፤ ከፍ ከፍም ያደርጉታል፤ በጥበብም ያከብሩታል።'),
