  ('ed554759-da74-5b65-aaab-866006a4b5f9', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 18, 18, 'በየብስና በደሴት የሚኖረው ሌላው ኀይልም በዚያች ቀን አንድ ቃል ተቀብለው በሃይማኖት መንፈስ፥ በጥበብና በትዕግሥት መንፈስ፥'),
  ('cedea767-4110-5e53-adf3-04ba1a1bf57a', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 19, 19, 'በምሕረት መንፈስ፥ በፍርድና በሰላም መንፈስ፥ በቸርነት መንፈስ ይባርካሉ፤ ያከብራሉ፤ ያመሰግናሉም፤ ከፍ ከፍም ያደርጋሉ።'),
