  ('c1b08ef1-4b15-5062-a94c-fe629c1327ea', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 60, 60, 'ጌታንም በሥራው ሁሉ አላመሰገንነውም፤ አለኝታችንም በመንግሥታችንና በጌትነታችን ዙፋን ሥልጣን ላይ ሆነ።'),
  ('1b84649b-d295-50c7-a80c-7c73060b28d4', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 61, 61, 'በድካማችንና በመከራችን ቀንም አላዳነንም።'),
  ('4040e063-4ea9-540c-a722-1afbbc5797d0', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 62, 62, 'እናምንም ዘንድ ዕረፍትን አናገኝም፤ ጌታችን በሥራው ሁሉ፥ በፍርዱና በቸርነቱም ሁሉ የታመነ ነውና።'),
  ('7bf42187-6df8-51f6-a776-2c5605a8beb9', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 63, 63, 'የፍርዱንም ፊት አያገኙም፤ ስለ ሥራችንም ከፊቱ እንሄዳለን፤ ኀጢአታችንም ሁሉ በጽድቅ ተቈጠረ፤”'),
  ('a29dfa64-3b3d-5797-a2e2-352d32afab10', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 64, 64, 'አሁንም እንዲህ ይሏቸዋል- “ሰውነታችን ከዐመፅ ገንዘብ ትጠግባለች፤ ወደ ሲኦል መከራ ትኩሳት ከመውረድም አታድነንም።”'),
  ('7610c261-26d0-50c6-ad23-d91053cc2b2c', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 65, 65, 'ከዚህም በኋላ በዚያ በሰው ልጅ ፊት ፊታቸው ጨለማንና ኀፍረትን ይሞላል።'),
  ('fc3ad44a-6580-5b64-aca7-28811f11770b', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 66, 66, 'ከፊቱም ተሰድደው ይሄዳሉ፤ በመካከላቸውም በፊቱ ሰይፍ ያድራል።'),
  ('e0f534ab-d85d-5023-aed6-f42aae95774b', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 67, 67, 'የመናፍስትም ጌታ እንዲህ አለ- “የአዛዦችና የነገሥታት፥ የልዑላንና ምድርን የሚገዟት ሰዎች ሥርዐታቸው፥ ፍርዳቸውም በመናፍስት ጌታ ፊት ይህ ነው።”'),
  ('00330d1e-ba6b-5e81-a1df-7a559cf971f7', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 68, 68, 'በዚያም ቦታ የተሰወሩ ሌሎች ፊቶችን አየሁ።'),
  ('ac46f20c-1b9c-5aa3-a3cc-24b045997ce7', 'c7031434-b2b8-5b52-a81e-b9a0066f0a1c', '7abb382c-bb4f-5119-ad07-b2fc3cfdb978', 69, 69, 'የመልአኩንም ቃል እንዲህ ሲል ሰማሁ- “ከሰማይ ወደ ምድር የወረዱ፥ በስውር ያለውንም ለሰው ልጆች የገለጡ፥ ኀጢአትንም ይሠሩ ዘንድ የሰው ልጆችን ያሳትWaቸው መላእክት እኒህ ናቸው።”'),
  ('497e7bb9-e168-55fb-a32e-a2b0515843fa', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 1, 1, 'በእነዚያም ወራቶች ኖኅ ምድር እንደ አዘነበለች፥ ጥፋትWaም እንደ ቀረበ አየ።'),
  ('2ee8e1ce-0269-51fa-a79e-401c84ad0f28', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 2, 2, 'ከዚያም እግሩን አንሥቶ እስከ ምድር ዳርቻ ድረስ ሄደ።'),
  ('3890724c-134b-5381-ad22-59027a502daf', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 3, 3, 'ለአያቱ ለሄኖክም ጮኸ፤ ኖኅም በመረረ ቃል ሦስት ጊዜ “ስማኝ፤ ስማኝ፤ ስማኝ” አለ።'),
  ('f99f209e-d216-53e2-a9b7-85216a337e2c', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 4, 4, 'እንዲህም አለው- “በምድር ላይ የሚሠራው ሥራ ምንድን ነው? ንገረኝ!'),
  ('e31b659e-bf60-58d1-a028-6a86789aa56b', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 5, 5, 'ምድር ደክማለችና፥ እንዲህ ተነዋውጣለችና፥ ምንአልባት እነሆ፥ እኔ ከእርስዋ ጋር እጠፋ ይሆን?”'),
  ('ef9d3fe3-bea0-5ecf-a34d-b51fddb7e29b', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 6, 6, 'በዚያም ጊዜ በምድር ላይ ታላቅ ሁከት ሆነ፤ ከሰማይም ቃል ተሰማ።'),
  ('ed278356-8c00-511c-af6b-a708a141678a', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 7, 7, 'በግንባሬ ወደቅሁ፤ አያቴ ሄኖክም ወደ እኔ መጣ፤ በአጠገቤም ቆመ፤ እንዲህም አለኝ- “ወደ እኔ መራራ ጩኸትንና ልቅሶን ለምን ትጮኻለህ?'),
  ('4f27530f-c5d0-573b-a0f9-80e1e8a1390a', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 8, 8, 'እርሱም- ጥፋታቸው ይሆን ዘንድ በምድር በሚኖሩ ሰዎች ላይ ከመናፍስት ጌታ ፊት ትእዛዝ ወጣ።'),
  ('3c85b8c3-86cb-51fe-a740-5e984f24d490', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 9, 9, 'የመላእክትን ምሥጢር ሁሉ፥ የሰይጣናትን ግፍ ሁሉ፥ የተሰወረ ሥራቸውንም ሁሉ፥ ሟርት የሚያሟርቱ ሰዎችን ኀይል ሁሉ፥ የቀለማትንም ኀይል፥ የምድርን ሁሉ ጣዖት የሚሠሩ ሰዎችን ኀይል አሳውቀዋልና።'),
  ('b48491d1-b67b-5e05-ac26-cc669c4cd828', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 10, 10, 'ብር ከመሬት ትቢያ እንዴት ይገኝ ነበር? ቅልቅል ብረትስ በምድር ላይ እንዴት ይገኝ ነበር?'),
  ('72b82b20-f7b9-5fa5-ae28-47a3574e2e4d', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 11, 11, 'እነርሱን የሚያስገኛቸው መሬትና በውስጥዋ የሚቆመው መልአክ መጀመሪያ ምንጭ እንደ ሆኑ እርሳስና ቆርቆሮ ከምድር አይገኙም ነበርና፤'),
  ('bb9b8df5-ae82-5bcd-aa1e-cbb85c76aea9', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 12, 12, 'ከዚያም በኋላ አያቴ ሄኖክ በእጁ ይዞ አነሣኝ።'),
  ('9f448484-3ccd-52db-a2bb-9481391dfbca', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 13, 13, 'እንዲህም አለኝ- “በምድር ላይ ስላለው ሁከት የመናፍስትን ጌታ ጠይቄዋለሁና ሂድ።”'),
  ('d237d26e-14ad-5d39-aaa5-74be91d5547b', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 14, 14, 'እንዲህም አለኝ- “ስለ በደላቸው ፍርዳቸው ተፈጸመችባቸው፤ ስለ ፈለጓቸውም ወራቶች በፊቴ አይቈጠሩም።'),
  ('88f0190e-823b-5a82-ae7b-2cd06a9ed8f9', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 15, 15, 'ምድርም እንደምትጠፋ፥ በእርሷም የሚኖሩ ሰዎች እንደሚጠፉ ዐወቁ፤ እኒህም የተሰወረውን ለሰዎች አስተምረዋልና፥ እነርሱም የተፈረደባቸው ናቸውና ለዘለዓለም መመለሻ የላቸውም።'),
  ('f4e43e03-50a4-5547-a944-8723e14ed46d', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 16, 16, 'ነገር ግን አንተ ልጄ! ከዚህ ከተሰወረው ነቀፋ አንተ ንጹሕና ቸር እንደ ሆንህ የመናፍስት ጌታ ዐውቋልና ይህ ለአንተ አይደለም።'),
  ('dad2baec-709e-5271-a9db-af9708093a4c', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 17, 17, 'በቅዱሳን መካከልም ስምህን አጸናው፤ በምድርም ላይ ከሚኖሩት ለይቶ ይጠብቅሃል።'),
  ('2e923fc7-04db-5eef-a80a-9e7120c4a552', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 18, 18, 'ለመንግሥትና ለብዙ ምስጋናም ሊሆን ዘርህን በእውነት አጸናው፤ ከዘርህም የጻድቃንና የቅዱሳን መገኛ ይወለዳል፤ ለዘለዓለሙም ቍጥር የላቸውም።”'),
  ('5f42edfa-26cf-5495-a86c-5dd203b6e46d', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 19, 19, 'ከዚህም በኋላ እንዲመጡ በምድር ላይ በሚኖሩ ሰዎች ሁሉ ለፍርድና ለጥፋት ሊሆን ከምድር በታች ያለ የውኃውን ኀይል ሁሉ መጥተው ይከፍቱ ዘንድ የተዘጋጁ የመቅሠፍት መላእክትን አሳየኝ።'),
  ('6427f340-6b2b-549b-ae73-59d0e62cf9a6', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 20, 20, 'የመናፍስት ጌታም እነዚያ መላእክት በውኃው ኀይል ላይ ተሾመዋልና የወጡትን መላእክት እጃቸውን እንዳያነሡ፥ እንዲጠብቁም አዘዘ።'),
  ('d0f07d4e-b9bd-54d4-a510-890c2f792b76', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 21, 21, 'ከሄኖክም ፊት ወጣሁ።'),
  ('882b9663-6042-57f9-ad1d-d49c02f1a13a', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 22, 22, 'በእነዚያም ወራቶች የእግዚአብሔር ቃል ወደ እኔ መጣ።'),
  ('52ee3e4d-6a84-56f0-aad4-7441061e2ef8', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 23, 23, 'እንዲህም አለኝ- “ኖኅ! እነሆ፥ ዕድል ፋንታህ ወደ እኔ ደረሰ፤ “ነቀፋ የሌለበት ዕድል የፍቅርና የቅንነት ዕድል ነው።”'),
  ('c685f195-dcc2-5df1-afdb-f6e0d90bc725', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 24, 24, 'አሁንም መላእክት እንጨቶችን ያዘጋጃሉ፤ እነርሱም ለዚያ መልእክት በወጡ ጊዜ እጄን በላይዋ ጭኜ እጠብቃታለሁ።'),
  ('caa52fe1-480f-5286-ab27-f87eafdc85e6', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 25, 25, 'ከእርስዋም ወጥተህ የሕይወት ዘር ትሆናለህ፤ ምድርም ባዶውን እንዳይቀር ለውጡ ይግባ።'),
  ('e6b73828-0f43-58cb-ae76-5155450a4275', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 26, 26, 'ዘርህንም ለዘለዓለም በፊቴ አጸናዋለሁ፤ ከአንተ ጋራም የሚኖሩ ዘሮችህን በምድር ፊት አበዛቸዋለሁ።'),
  ('6bd01a31-6b1b-5774-a652-a5163563da03', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 27, 27, 'በመናፍስትም ጌታ ስም በምድር ላይ ይበዛል፤ ይባረካልም።'),
  ('a1a5fd74-70ed-5c1f-a270-3a7f8f48929b', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 28, 28, 'ዐመፅን የአሳዩ እነዚያን መላእክትም'),
  ('a033c0f1-ba6d-56f3-a113-50eae743054f', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 29, 29, 'ታላቅ ሁከትና የውኃዎች መታወክ ያለባትንም ያችን ሸለቆ አየኋት።'),
  ('aaec0029-7672-5060-a788-6e012554d8f2', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 30, 30, 'ይህ ሁሉ ከተደረገ በኋላ፥ ከዚህ ከእሳቱ ነጠብጣብ የተነሣ ከሚያውካቸውም ሁከት የተነሣ በዚያ ቦታ የድኝ ሽታ ተገኘ፤ ከእነዚያም ውኃዎች ጋር አንድ ሆነ።'),
  ('f9dbe615-afce-5645-a046-b8c8633371f4', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 31, 31, 'ያችም ሰውን የአሳቱ የመላእክት'),
  ('58fc4343-1059-539e-a581-99f2cb22bc93', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 32, 32, 'የእሳት ፈሳሾችም በምድር ላይ የሚኖሩትን ያሳትWaቸው መላእክት በሚኰነኑበት ቦታ ወደ ሸለቆዎችዋ ይፈስሳሉ።'),
  ('09e9f945-fd9e-545b-a62f-4bfe38541bb4', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 33, 33, 'በእነዚያም ወራት እነዚህ ውኃዎች ለነገሥታቱና ለአዛዦች፥ ለልዑላንና በምድር ለሚኖሩ ሰዎች፥ ለነፍስና ለሥጋ ፈውስ፥ ለመንፈስም ፍርድ ይሆናሉ።'),
  ('72ba9c96-29e8-5c63-a3ef-e20efe3bff57', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 34, 34, 'የመናፍስት ጌታን ክደውታልና በሥጋቸው ይፈረድባቸው ዘንድ ልቡናቸው ዋዛ ነገርን ይመላል።'),
  ('7b49ef04-f206-588d-a1e5-290e3c5da9ab', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 35, 35, 'የየቀኑን ሁሉ ፍርዳቸውንም ያያሉ፤ በስሙም አያምኑም።'),
  ('fa37f37c-dca3-5011-ab9a-3ae9fc225d07', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 36, 36, 'በመናፍስት ጌታ ፊት ዋዛ ፈዛዛ የሚናገር የለምና፥ ሥጋቸው ብዙ ጊዜ እንደ ተቃጠለ እንደዚሁ በነፍሳቸው ለዘለዓለሙ ለውጥ ይኖርባቸዋል።'),
  ('47389721-070b-58f0-aa35-166b64beaabf', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 37, 37, 'በእነርሱ ላይ ፍርድ ትመጣለችና፥ በሥጋቸውም ዋዛ ነገር ያምናሉና፥ የጌታንም መንፈስ ይክዳሉና።'),
  ('3a245ba5-d4e9-57fa-a134-65be11cb89ce', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 38, 38, 'በዚያም ወራት እነዚያ ውኃዎች ለውጥ ይኖራቸዋል፤ እነዚያ መላእክት በሚፈረድባቸው ጊዜ በዚያ ወራት የእነዚያ የውኃዎች ምንጮች መቃጠል ይለወጣልና።'),
  ('e8637f69-4fb2-57d6-a3fa-744502ff3a9b', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 39, 39, 'መላእክትም በወጡ ጊዜ የምንጮች ውኃ ተለውጦ ይቀዘቅዛል።'),
  ('85851532-c5f6-586b-a8ee-148dd14192a6', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 40, 40, 'ቅዱስ ሚካኤልንም እንዲህ ብሎ ሲመልስ ሰማሁት- “አለቆች የሚቀጡባት ይህች ፍርድ ለነገሥታትና ምድርን ለሚቈጣጠሩ አዛዦች ምስክር ናት፤ እኒህ የቅጣት ውኃዎች ለአለቆች ሥጋ ፈውስ፥ ለሥጋቸውም ለሞት ናቸውና።”'),
  ('70ed787d-0ea0-557d-a206-5f1859ec17a6', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 41, 41, 'እነዚያ ውኃዎች ተለውጠው ለዘለዓለም የሚነድድ እሳት እንደሚሆኑባቸው አያዩም፤ አያምኑምም።'),
  ('1c82f5fb-73a8-519d-a650-5d43bb5f41b3', '259c295b-8680-58c8-a5bc-32150fd69bbe', '3eb4fac9-639f-5cf5-a8f5-f5a36b8d76c6', 42, 42, 'ከዚህም በኋላ አያቴ ሄኖክ የተሰጡትን የምሥጢሮችን ሁሉና የምሳሌዎችን ምልክት በመጽሐፍ ሰጠኝ፤ በእኔ ዘንድ ከአለው የመጽሐፍ ቃል ጋርም ጨመራቸው።'),
  ('838b0b30-9921-5098-ab1b-e81326ea1ab4', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 1, 1, 'በዚያችም ቀን ቅዱስ ሚካኤል ለቅዱስ ሩፋኤል እንዲህ ብሎ መለሰለት- “የመንፈስ ኀይሉ ነጥቆ ይወስደኛል።'),
  ('36078219-4885-5460-a428-4a181ac90260', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 2, 2, 'ለአለቆች ቅጣት ስለ ተሰወረችው ስለ ፍርድ ጭንቀትም ያበሳጨኛል።'),
  ('30a0dc03-af20-5217-a600-4557cbdb6740', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 3, 3, 'ስትሠራ የኖረችውን፥ እነርሱም በፊትWa የቀለጡባትን ጭንቀት መታገሥ የሚቻለው ማንነው?”'),
  ('a68cbcca-8734-58de-a66a-4508c99b4f60', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 4, 4, 'ዳግመኛም ቅዱስ ሚካኤል ለሩፋኤል እንዲህ ብሎ መለሰለት- “በእርስዋ ላይ ልቡናውን የማያራራ ማን ነው?'),
  ('604baf31-43e1-5d03-a593-5f61291a4551', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 5, 5, 'እንደዚህም ካወጧቸው ከእነዚያ በእነርሱ ላይ ከወጣች ከዚች የፍርድ ቃል የተነሣ ኵላሊቱ የማይታወክ ማን ነው?'),
  ('2efec0ab-a117-5d4d-a776-44bb8aa3b3f3', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 6, 6, 'በመናፍስት ጌታ ፊት በቆመ ጊዜም እንዲህ ሆነ፤ ቅዱስ ሚካኤል ሩፋኤልን እንዲህ አለው- “የመናፍስት ጌታ ተቈጥትWaቸዋልና በጌታ ዐይን ምሕረት አይደረግላቸውም።'),
  ('3724e4df-90bb-5abe-ac52-1b92371331c2', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 7, 7, 'በጌታ አምሳል ይሠራሉና፥ ስለዚህ ለዘለዓለሙ የተሰወረ ፍርድ ይመጣባቸዋል።'),
  ('4d95ee97-cbfd-5d35-a082-54e25cc891d9', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 8, 8, 'እነርሱ ብቻ ፍርዳቸውን ለዘለዓለሙ ይቀበላሉ እንጂ መልአክም ቢሆን ሰውም ቢሆን የሌላውን ድርሻ አይቀበልምና።”'),
  ('d270abf9-b0a1-5a73-aea3-6656df4fc253', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 9, 9, 'ከዚህም ፍርድ በኋላ ያስደነግጧቸዋል፤ ያሳዝኗቸዋልም። በምድር ላይ ለሚኖሩ ሰዎች ይችን አሳይተዋልና።'),
  ('25cd5e87-1152-57ce-afd7-e321d0c013fa', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 10, 10, 'የእነዚያም መላእክት ስማቸው እነሆ፤ ስማቸውም ይህ ነው።'),
  ('ddf54a22-ad3a-5bd2-ae0a-3bd874db6562', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 11, 11, 'አለቃቸው ስማዝያ ነው፤ ሁለተኛውም አርስጢኪፋ ነው፤ ሦስተኛውም አርሚን ነው፤ አራተኛውም ኮከብኤል ነው።'),
  ('199572e4-4211-5630-a13c-bee00a7cc41d', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 12, 12, 'አምስተኛውም ጡርኤል ነው፤ ስድስተኛውም ሩምያል ነው፤ ሰባተኛውም ዳንኤል ነው፤ ስምንተኛውም ምቃኤል ነው፤ ዘጠነኛውም በረቃኤል ነው፤ ዐሥረኛውም አዛዝኤል ነው፤ ዐሥራ አንደኛውም አርማሮስ ነው፤ ዐሥራ ሁለተኛውም በጠርያል ነው።'),
  ('3a14edb3-c9d3-5a91-a1d9-7a1a023dbb04', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 13, 13, 'ዐሥራ ሦስተኛውም በሰሳኤል ነው፤ ዐሥራ አራተኛውም አናንያል ነው፤ ዐሥራ አምስተኛውም ጡርያል ነው፤ ዐሥራ ስድስተኛውም ሲምሳፓኤል ነው።'),
  ('7611a6f2-26b7-562a-abcf-0a615e31010e', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 14, 14, 'ዐሥራ ሰባተኛውም ይትርኤል ነው፤ ዐሥራ ስምንተኛውም ቱማኤል ነው፤ ዐሥራ ዘጠነኛውም ጥራኤል ነው፤ ሃያኛውም ራሙኤል ነው፤ ሃያ አንደኛውም አዛዝኤል ነው።'),
  ('8651fb74-a3b9-5ffd-ada8-6cabd0a0d2e6', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 15, 15, 'ያለቆቻቸው አለቆችም እኒህ ናቸው።'),
  ('4b2d6e87-b1e3-5e17-afa8-30c2ae8aab5d', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 16, 16, 'የመቶ አለቃቸውና የአምሳ አለቃቸው፥ የዐሥር አለቃቸውም ስማቸው ይህ ነው- የመጀመሪያው ስሙ ይቆን ነው።'),
  ('1c39a253-4896-5e77-aca6-ecf7a8907670', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 17, 17, 'የመላእክትን'),
  ('64945072-3821-583b-a12c-9fc8a1445ace', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 18, 18, 'ሁለተኛው ስሙ አስብኤል ነው፤ ይህም ለቅዱሳን መላእክት'),
  ('ae8a0790-2343-53ad-afe2-84b3d0547188', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 19, 19, 'ሦስተኛውም ስሙ ጋድርኤል ነው፤ በመምታት መግደልን ሁሉ ለሰው ልጆች ያስተማረ ይህ ነው።'),
  ('40252a64-fa7b-59a5-ad94-671c8234b1cd', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 20, 20, 'ሔዋንንም ያሳታት እርሱ ነው፤ ለሰው ልጆችም የሞት መሣሪያን ጋሻንና ጥሩርን፥ ለግድያም ሰይፍን ያስተማረ እርሱ ነው።'),
  ('7f311431-b009-54e7-aa6a-fd4829ceb884', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 21, 21, 'ለሰው ልጆችም የግድያ መሣሪያዎችን ሁሉ አስተማረ፤ ከዚያች ቀንም ጀምሮ እስከ ዘለዓለሙ ድረስ በምድር በሚኖሩ ሰዎች ላይ ይህ ሁሉ ከእርሱ ወጣ።'),
  ('37228841-879c-5e5a-a7af-3e0d4007f3b0', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 22, 22, 'አራተኛውም ስሙ ፔንሙዕ ነው፤ ለሰው ልጆችም የመረረውንና የጣፈጠውን ያሳየ ይህ ነው።'),
  ('569603a1-7b7d-59d6-a603-f2c640b69703', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 23, 23, 'የተሰወረ ጥበባቸውን ሁሉ አሳያቸው፤ ለሰዎችም በጥቁር ቀለምና በወረቀት መጽሐፍ መጻፍን አስተማራቸው።'),
  ('1c75c7b0-9a94-5605-a9a4-113ec9482b22', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 24, 24, 'ስለዚህም ነገር ከጥንት ጀምሮ እስከ ዘለዓለም፥ እስከዚችም ቀን ድረስ ብዙ ሰዎች ይስታሉ። እንደ መላእክት ጻድቃንና ንጹሓን ሆነው ይኖሩ ዘንድ ነው እንጂ ሰው ለእንደዚህ ያለ ሥራ አልተፈጠረም ነበርና፥ በቀይ ቀለምና በጥቁር ቀለምም ሃይማኖታቸውን ሊያጸኑ ሰው ለእንዲህ ያለ ሥራ አልተወለደም ነበርና።'),
  ('41929204-3845-5dc2-a272-3faa0bd04766', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 25, 25, 'ይህን በማወቃቸው ይጠፋሉ እንጂ ሁሉን የሚያጠፋ ሞት ባልዳሰሳቸውም ነበር።'),
  ('d6403936-12de-542d-afa8-3360119a1a0a', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 26, 26, 'ስለዚህም ኀይል ይበላኛል።'),
  ('e2cca422-6e35-58d1-aba5-0d06a6823938', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 27, 27, 'አምስተኛውም ስሙ ካሳድያዕ ነው፤ የነፍሳትንና የአጋንንትን ክፉ መማታትን ሁሉ ለሰው ልጆች ያሳየ እርሱ ነው።'),
  ('307bf09a-5c4c-532b-a200-4ca273771be9', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 28, 28, 'ከማኅፀን ወጥቶ ይወድቅ ዘንድ ፅንስ ማስወረድንና ነፍስ መግደልን የአስተማረ እርሱ ነው።'),
  ('ea3c7eef-2e5a-5b92-a3e3-7561609fe869', '2c3489b1-3d6a-5024-a175-bb0868f1eda3', '630bf0ae-dc4f-5e34-a3fc-920034eaddeb', 29, 29, 'በእባብ መነደፍንና በቀትር የሚሆን ምችን ተባዕ የሚባለው የእባብ ልጅ አስተማረ።'),
  ('69f343a3-402e-5775-a157-99314fbefb3c', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 1, 1, 'ልዑል በጌትነት በኖረ ጊዜ ለቅዱሳን የገለጠው የመሐላ ራስ የክስብኤል የስሙ ቍጥር ይህ ነው።'),
  ('6d7fc8ec-9b45-571d-ae4f-7c0a0ee49e71', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 2, 2, 'ስሙም ቤቃ ይባላል፤ ይኸውም ቅዱስ ሚካኤልን እንዲህ አለው- “ያን የተሰወረ ስሙን ያውቁት ዘንድ የተሰወረውን ስም ግለጥላቸው።'),
  ('448ff7fa-9f51-5e62-a2f4-a7639054b045', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 3, 3, 'የተሰወረውንም ሁሉ ለሰው ልጆች ያሳዩ ከዚህ ስምና መሐላ የተነሣ እንዲንቀጠቀጡ በመሐላ ጊዜ ይጠሩት ዘንድ ግለጥላቸው።'),
  ('f9391a40-2e26-59e0-a4d2-ef364f1d3d83', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 4, 4, 'ኀይለኛ ነውና፥ የጸናም ነውና የዚህ መሐላ ኀይሉ ይህ ነው።'),
  ('3958bbdb-21a3-5d37-a70a-b62a19b0b067', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 5, 5, 'ይህን አካዕ የተባለውንም ስም በቅዱስ ሚካኤል እጅ አኖረው። የዚህ ስም የተሰወሩ ምሥጢሮቹም እነዚህ ናቸው። በስሙም ጸኑ።'),
  ('0ca367c7-8349-50b6-a915-26b89a056204', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 6, 6, 'በዚያም ስም ሰማይ ጸና፤ ያም ስም ዓለም ሳይፈጠር ነበር፤ እስከ ዘለዓለምም ይኖራል፥ ምድርም በእርሱ በውኃው ላይ ተመሠረተች።'),
  ('fd3f74f4-24ba-58b5-aa20-7430cf5a7f4b', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 7, 7, 'ከተራሮች ስውር ቦታዎች ውስጥ ከጥንት ጀምሮ እስከ ዘለዓለም ድረስ የጣፈጡ ውኃዎች ይመነጫሉ።'),
  ('7aaf4347-a8b8-5ca2-ab48-e33d13c5a40c', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 8, 8, 'በዚያም ስም ባሕር ተፈጠረች፤ በተቈጣችም ጊዜ- ከዓለም ፍጥረት ጀምሮ እስከ ዘለዓለም ድረስ ከወሰንዋ እንዳታልፍ የአሸዋ መሠረት አኖረላት።'),
  ('a4acf82a-1d34-5952-a253-16711ea20d1b', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 9, 9, 'በዚያም ስም ጥልቆች ሁሉ ጸንተው ቆሙ፤ ከጥንትም ጀምሮ እስከ ዘለዓለም ድረስ ከቦታቸው አይናወጡም።'),
  ('1f8e897d-bf7b-523f-aaf4-12f434a93fe5', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 10, 10, 'በዚያም ስም ፀሐይና ጨረቃ ጎዳናቸውን ይጨርሳሉ፤ ከጥንት ጀምሮ እስከ ዘለዓለሙ ድረስ ከታዘዙት ትእዛዝ አያልፉም።'),
  ('951fa327-14a6-55c1-ad8d-73c280dd8210', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 11, 11, 'በዚያም ስም ከዋክብት ጎዳናቸውን ይጨርሳሉ፤ ስማቸውንም ይጠራል፤ እነርሱም ከጥንት ጀምሮ እስከ ዘለዓለሙ ድረስ ይመልሱለታል።'),
  ('6a840a61-125d-52b3-a59d-adc017981349', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 12, 12, 'እንደዚሁም ለውኃዎች አካላት ሕይወታቸው ነፋሳት ናቸው፤ የሁሉም አካሎቻቸውና መተላለፊያዎቻቸው ከነፋሳት ኅብር ሁሉ ነው።'),
  ('ab606874-6f54-52ff-aabd-ea09c45818e6', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 13, 13, 'በዚያም የነጐድጓድ የቃሉ መዛግብትና የመብረቅ ብርሃን ይጠበቃሉ።'),
  ('6f72e2a1-25d6-593d-a6a1-a8964f1e5c79', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 14, 14, 'በዚያም የበረድና የውርጭ መዛግብት፥ የጉም መዛግብትና የዝናምና የጠል መዛግብትም ይጠበቃሉ።'),
  ('e8a29a0f-afa2-589c-a0ed-9a02f3447a78', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 15, 15, 'እነዚያም ሁሉ በመናፍስት ጌታ ፊት አምነው ያመሰግናሉ፤ በፍጹም ኀይላቸውም ያመሰግናሉ።'),
  ('27cbf5d9-d650-52bd-a742-7b884e46b804', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 16, 16, 'ሁልጊዜም ምግባቸው ምስጋና ናት፤ ለዘለዓለም የሚኖር የመናፍስት ጌታ ስሙንም ያመሰግናሉ፤ ያከብራሉም፤ ከፍ ከፍም ያደርጋሉ።'),
  ('fab91bab-e5b8-5699-a4e5-232b34115600', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 17, 17, 'ይህም ስም በእነርሱ ላይ ጸና፤ በእርሱም ይጠበቃሉ፤ መንገዶቻቸውም ይጠበቃሉ፤ መተላለፊያዎቻቸውም አይጠፉም።'),
  ('0bb2ca84-c02c-5bcd-af64-f23a7d93b42f', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 18, 18, 'ታላቅ ደስታም ሆነላቸው፤ የሰው ልጅ ስሙ ስለ ተገለጠላቸውም አመሰገኑ፤ አከበሩም፤ ከፍ ከፍም አደረጉ።'),
  ('7e74c4ce-4bc5-5e90-a085-b4193971e197', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 19, 19, 'በጌትነቱ ዙፋን ላይም ተቀመጠ፤ ለሰው ልጅም የፍርድ ሥልጣን ተሰጠው።'),
  ('2235620c-3252-5938-ae8b-ba618e9a9f2c', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 20, 20, 'ከገጸ ምድርም ኃጥኣንን ያሳልፋል፤ ያጠፋልም፤ ዓለምን ያሳቱም በሰንሰለት ይታሰራሉ።'),
  ('57469da1-3e45-54a6-acc3-59c27b7de495', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 21, 21, 'በጥፋት ማኅበራቸውም ይጋዛሉ፥ ሥራቸውም ሁሉ ከገጸ ምድር ያልፋል።'),
  ('9fba661f-4208-5ba2-a9f3-dc432fe99a67', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 22, 22, 'ከእንግዲህ ወዲህም ፈርሶ በስብሶ የሚቀር የለም፤ ያ የሰው ልጅ ተገልጦ በጌትነቱ ዙፋን ተቀምጦአልና። ክፉ ነገርም ሁሉ ከፊቱ ይጠፋልና።'),
  ('8d2a8945-33e7-5372-a3c1-02286dab09ac', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 23, 23, 'ሄደውም ለዚያ ለሰው ልጅ ይነግሩታል፤ በመናፍስት ጌታ ፊትም ይጸናል፤ ሦስተኛው የሄኖክ ምሳሌ ይህ ነው።'),
  ('6374aaae-95df-5f01-a66e-cbf477a07318', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 24, 24, 'ከዚህ በኋላም እንዲህ ሆነ፤ በመናፍስት ጌታ ዘንድ የሰው ልጅ ሕያው ስሙ በምድር ላይ ከሚኖሩ ሰዎች ይልቅ ከፍ ከፍ አለ።'),
  ('b3188713-5038-5880-ab45-2e5c58cbde01', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 25, 25, 'በመንፈስ ሠረገላዎችም ከፍ ከፍ አለ፤ ስሙም በመካከላቸው ወጣ።'),
  ('2125852e-72ca-5a04-a501-d618c06c80ab', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 26, 26, 'ከዚያችም ቀን በኋላ በመካከላቸው አልተቈጠርሁም።'),
  ('8e5c7c4b-9bb6-59f9-ad9f-f5931b44ea2a', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 27, 27, 'ለተመረጡና ለጻድቃን ቦታን ይሰፍሩልኝ ዘንድ መላእክት ገመዶችን በተቀበሉበት በሁለቱ ማዕዘናት በመስዕና በምዕራብ መካከል አኖሩኝ።'),
  ('cadfe831-bc8a-5729-a59b-f45a3cf13274', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 28, 28, 'በዚያም ከጥንት ጀምሮ በዚያ ቦታ የሚኖሩ የቀደሙ አባቶችንና ጻድቃንን አየሁ።'),
  ('ce24051d-9f28-5c2c-a6b2-49c2dac06be4', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 29, 29, 'ከዚህም በኋላ እንዲህ ሆነ፤ ልቡናዬ ትራቀቅ ጀመረች፤ ከሰማያት በላይ ወዳለች ወደ ሰማይም ትወጣ ጀመረች።'),
  ('5b08d89c-a3cf-5777-a874-3e07a3163fb2', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 30, 30, 'የቅዱሳን መላእክት ልጆችንም በእሳት ወላፈን ላይ ቁመው አየኋቸው። ቀሚሳቸውና መጐናጸፊያቸውም ነጭ ነው፤ የፊታቸውም ብርሃን እንደ በረዶ ነው።'),
  ('8c257dcb-b72b-5b74-ae74-e78aa3d77bb3', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 31, 31, 'ሁለት የእሳት ፈሳሾችንም አየሁ፤ የዚያም እሳት ብርሃን እንደ ዕንቍ ያበራል፤ በመናፍስት ጌታ ፊትም በግንባሬ ወደቅሁ።'),
  ('9472617b-9233-5529-a4c5-7f36d3ae378f', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 32, 32, 'ከመላእክት አለቆች አንዱ መልአክ ሚካኤል ቀኝ እጄን ይዞ አነሣኝ፤ ምሕረት ወደ አለበት፥ ጽድቅም ወደ አለበት የተሰወረ ቦታ አወጣኝ።'),
  ('e5b564ff-c658-5a64-a2da-3ece1ea0d11d', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 33, 33, 'በሰማይ ዳርቻ የተሰወሩትንም ሁሉ፥ የከዋክብትንና የብርሃናትንም መዛግብት ሁሉ በቅዱሳን ፊት ከሚወጡበት አሳየኝ።'),
  ('369a741a-7503-5744-aa09-53e41ef33158', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 34, 34, 'መንፈስም ሄኖክን ከሰማያት በላይ ባለ ሰማይ ሰወረው።'),
  ('4345b221-8dd7-51f1-af8c-d9708821aebd', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 35, 35, 'በዚያም በብርሃን መካከል በዕንቍ የተሠራ ቤት እንዳለ አየሁ።'),
  ('e25adb0b-520d-5227-aa32-9b72bce89f28', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 36, 36, 'በእነዚያም ድንጋዮች መካከል የሕያው እሳት ላንቃዎች አሉ።'),
  ('d082dca9-72f3-56dd-a514-62705306f851', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 37, 37, 'መንፈሴም እሳት የሚከበው የዚያን ቤት ዙሪያ አየች፤ በዚያም በአራቱ ማዕዘን ሕያው እሳትን የተመሉ ወንዞች አሉ። ያንም ቤት ይዞሩታል።'),
  ('081bf80a-e145-518c-ac63-388e88d8e75a', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 38, 38, 'ሱራፌልና ኪሩቤል፥ አፍኒንም በዙሪያው አሉ። እነዚህም የማያንቀላፉ ናቸው፥ የጌትነቱንም ዙፋን ይጠብቃሉ።'),
  ('be769b53-60d5-56b7-afb2-d94e4bb0efaa', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 39, 39, 'የማይቈጠሩ ብዙ፥ የብዙ ብዙ የሚሆኑ መላእክትን አየሁ፥ ያንም ቤት ይከብቡታል።'),
  ('04c30ade-b3e1-5fec-a81a-941290116494', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 40, 40, 'ሚካኤልና ገብርኤል፥ ሩፋኤልና ፋኑኤል፥ በሰማያት ያሉ ቅዱሳን መላእክትም በዚያ ቤት ይገቡና ይወጡ ነበር።'),
  ('dbd3b7fe-5827-5412-af93-56ce279cf7e8', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 41, 41, 'ከዚያም ቤት ሚካኤልና ገብርኤል፥ ሩፋኤልና ፋኑኤል፥ ቍጥር የሌላቸው ብዙዎች ቅዱሳን መላእክትም ይወጡ ነበር።'),
  ('b4747851-b6ee-5c32-a40b-adcc3696c601', 'f804038e-9995-5717-a80e-e60393def827', '4792b152-477c-52e9-aa62-b364c356bb51', 42, 42, 'ብሉየ መዋዕልም ከእነርሱ ጋር አለ፤ ራሱም እንደ ባዘቶ ነጭ ነው፥ ንጹሕም ነው፤ ልብሱም የማይተረጐም ነው።')
